insert into robotter (slug, navn, producent, producentland, producentby, status, foerste_udgivelse, varianter, noter) values
  ('anybotics-anymal', 'ANYmal (Generation D)', 'ANYbotics', 'Schweiz', 'Zuerich', 'i_produktion', null, null, '["ANYbotics AG, Hagenholzstrasse 83a, 8050 Zuerich. Kontor ogsaa i San Francisco. Schweiz er ikke EU.","Et komplet datablad findes, men kun bag en formular (https://www.anybotics.com/anymal-specifications-sheet/). Ikke hentet."]'::jsonb),
  ('anybotics-anymal-x', 'ANYmal X', 'ANYbotics', 'Schweiz', 'Zuerich', 'annonceret', null, null, '["PRODUCENTEN OPLYSER INGEN TAL. Specifikationsafsnittet paa produktsiden bestaar af EN saetning: 2026 ANYmal X specifications coming soon.","PROJEKTETS BEDSTE ARGUMENT, OG DET LIGNER ET NEDERLAG. Den robot i feltet, der har den staerkeste europaeiske certificering - ATEX og IECEx op til Zone 1 IIB, det papir der afgoer, om en maskine overhovedet maa ind paa et raffinaderi - har den naestlaveste specifikationstaethed i hele indsamlingen. Taethed maaler AABENHED, ikke EGNETHED. Sorterer kataloget paa taethed som standard, lander den robot, en dansk procesindustri faktisk maa koebe, i bunden.","SKEMAET MANGLER ET FELT: ex_certificering. ATEX/IECEx-zoneklassifikation kan ikke skrives ind i nogen af de 33 felter uden at blive kvalt i ce_oplyst. Producentens ordrette tekst: ATEX & IECEx certified up to Zone 1 IIB; Certified for up to Zone 1 where inflammable gases are likely to occur; intrinsically safe. Forslag: ex_certificering med standard (ATEX|IECEx), zone (0|1|2) og gasgruppe (IIA|IIB|IIC), og ikke_oplyst som foerstegangsvaerdi for alle andre poster."]'::jsonb),
  ('astrall-dynamics-hypertron-t01', 'Hypertron-T01', 'Astrall Dynamics', 'Kina', 'Shenzhen', 'annonceret', null, null, '["STOPPROEVE (firbenet/hjul-ben-hybrid): Produktsiden kalder maskinen entydigt \"重负载行业级轮足机器狗\" (tunglast industri-klasse hjul-fod-robothund) og \"重载四足机器人平台\" (tunglast firbenet robotplatform) med \"轮足式设计结构\" (hjul-fod-designstruktur). Kilde: https://www.astralldynamics.com/project-Hypertron-T01.html, hentet 2026-08-24. Det er en hjul-ben-hybrid, som opgavebrevet eksplicit taeller som firbenet.","Selskabets kinesiske navn er 深圳璇玑动力科技(有限公司), forkortet 璇玑动力 (Xuanji Power/Dynamics). Det engelske brand paa selskabets egen side er \"ASTRALL\"/\"Astrall Dynamics\" (om-os-siden: \"深圳璇玑动力科技（以下简称：璇玑动力）\"; footer: \"深圳璇玑动力科技有限公司\"; e-mail contact@astralldynamics.com). Producentfeltet her bruger det engelske selvvalgte navn, samme princip som MagicLab/魔法原子.","SITE-INKONSISTENS FUNDET, IKKE BRUGT: forsidens ''hero''-boks paa produktsiden viser fire store tal - 100 km/h, 50 km raekkevidde, 300 kg last, 50 N·m moment - under overskriften \"A01全地形机器人\" (et ANDET modelnavn end \"Hypertron-T01\"). Billedfilerne bag boksen hedder ordret a01-shoux1.png / a01-shoux-hexin.png. Disse tal MODSIGER den detaljerede 产品参数-tabel laengere nede paa samme side (maks. hastighed 7 m/s, maks. staaende last 200 kg, moment 50/300 N·m raekkefolge byttet om). Vurderet som skabelontekst/billede genbrugt fra en anden/generisk produktside og ikke som Hypertron-T01''s egne tal - derfor IKKE brugt i felterne nedenfor. Baade hero-tallene og filnavnene er gemt i media/_kilder/raa-kand2-2026-08-24/ til efterproevning.","\"俯卧尺寸（长×宽×高）1130mm*755mm*320mm\" (liggende maal) er ogsaa oplyst, men skemaet har ingen felter til foldemaal (L30) - noteret her i stedet for hoejde-feltet.","驱动&电机: encoder \"双编码器\" og moment \"额定/最大扭矩: 50 N·m / 300 N·m\" har intet felt i skemaet - der findes intet ledmoment-felt. Noteret her.","储存温度 (opbevaringstemperatur, adskilt fra arbejdstemperatur): -20℃~60℃. Skemaets temp_min/temp_maks er arbejdstemperatur (工作温度); opbevaringstemperaturen har intet eget felt.","En engelsk pressemeddelelse (GlobeNewswire, 2026-06-07, \"Astrall Dynamics Unveils Integrated Quadruped Firefighting Robot Hypertron-T01 at INTERSCHUTZ 2026\") naevner i WebSearch-uddrag IP67 (mod IP66 paa den kinesiske produktside) samt en integreret 20L/s brandkanon med 60 m raekkevidde. Denne kilde kunne IKKE hentes direkte (WebFetch og curl gav begge timeout mod globenewswire.com efter flere forsoeg) og er derfor IKKE brugt til noget feltvaerdi - kun noteret her som en ueftereproevet selvmodsigelse (IP66 vs. IP67), der boer afklares naeste gang siden er tilgaengelig.","INGEN billede:-blok. Billedkandidater fundet men ikke bedoemt med oejne i dette spor - se fund/FUND-kand2.md."]'::jsonb),
  ('bhairav-robotics-shvana', 'Shvana', 'Bhairav Robotics', 'Indien', 'Kakinada, Andhra Pradesh', 'annonceret', null, null, '["STOPPROEVE (firbenet): BESTAAET, med et direkte og eksplicit producentcitat - ikke kun en afledning: \"Bhairav Robotics unveils Bharat''s first armed quadruped ''Shvana (श्वान)''\". Kilde: https://bhairavrobotics.com/shvana-robot/, hentet 2026-08-24 (raa HTML gemt, verificeret - se noten om sidens fulde indhold nedenfor). Samme ord (\"quadruped\") staar ogsaa paa forsiden: \"Armed Quadruped UGV Made in India\", https://bhairavrobotics.com/, hentet 2026-08-24.","STOPPROEVE (reelt produkt, ikke legetoej/hobbykit): BESTAAET paa firma- og formaalsniveau, men med forbehold om PRODUKTIONSSTATUS (se naeste note). Siden beskriver udelukkende militaere og industrielle anvendelser (Defence & Homeland Security, Industrial Environments) - ingen forbruger-, legetoejs- eller hobbysprog noget sted. Firmaet er et registreret indisk selskab med et team af ingenioerer med 25+ aars erfaring i forsvarsindustrien (\"MohanRaj Gangadharan ... 25+ years of experience in design and manufacturing of numerous products for defense industry\"; \"Ramakrishna Commuri ... 25+ years of experience... building drones for armed forces\"), https://bhairavrobotics.com/, hentet 2026-08-24. IKKE brugt som feltkilde, kun som kontekst for stopproeven: en ekstern soegning (Dealroom) fandt at Zen Technologies Limited (indisk forsvarsboers-selskab) i 2025 tog en ejerandel paa 45,33% i Bhairav Robotics - bekraefter et reelt, kapitaliseret selskab, men er presseformidlet/tredjepart og indgaar derfor IKKE i noget felt (L21/L33).","STATUS-VURDERING, IKKE ENTYDIG FRA PRODUCENTEN SELV: Shvana-siden praesenterer robotten med et konkret \"Features\"-specark (samme opbygning som et saelgende produkt), men bruger intetsteds ord som \"available now\", \"in production\", \"order\" eller lignende - eneste handlingsopfordring er \"For more details, email info@bhairavrobotics.com\". Ingen kundecase, ingen leveret enhed naevnt (i modsaetning til Keybotic Keypers case study). Saettes derfor til status: annonceret, ikke i_produktion - samme forsigtige laesning som fund/FUND-kandglobal.md''s egen vurdering (\"status for serieproduktion uklar fra siden selv\").","VAEGT ER EKSPLICIT UDEN NYTTELAST: \"Weight: 25 kg (minus payload)\" - grundvaegten er 25 kg UDEN den paafoerte nyttelast. En eventuel totalvaegt med fuld 10 kg nyttelast (op til 35 kg) er ALDRIG oplyst af producenten og er derfor ikke udregnet eller skrevet nogen steder i denne post (regel 1 - vi gaetter ikke et tal, producenten ikke selv har skrevet).","NYTTELAST PLACERET SOM GAAENDE, IKKE STAAENDE: siden skelner ikke selv mellem gaaende/staaende nyttelast - der staar kun ét tal, \"Payload: 10 kg\". Placeret under nyttelast_gaaende, fordi al anvendelsestekst handler om at baere/goere noget UNDER bevaegelse (\"Shvana can carry can also walk in the field areas/shopfloor along the designated path to carry out required tasks\"), ikke om en staaende last. nyttelast_staaende staar derfor ikke_oplyst, ikke 0 - samme fortolkningsprincip som brugt i data/robots/yufan-lingmao-cyvet.yaml.","KAMERAER BEVIDST IKKE SAT TIL EN VAERDI: siden skriver kvalitativt at Shvana er \"packed with a suite of sensors that act like eyes and ears\" og naevner \"Vision based detection and recognition\" som en evne - men navngiver INTET kameratype, -antal eller -model som STANDARDUDSTYR. \"high resolution RGB/thermal cameras\" naevnes eksplicit kun som ET EKSEMPEL PAA EN NYTTELAST, Shvana KAN baere (\"A few payloads Shvana can carry include robotic arm, high resolution RGB/thermal cameras and specialized sensors\") - altsaa tilbehoer, ikke bekraeftet indbygget udstyr. De to udsagn modsiger ikke hinanden, men entydiggoer heller ikke, om der er indbyggede kameraer. Sat til ikke_oplyst frem for at gaette, hvilken af de to der gaelder (samme princip som lidar-haandteringen i data/robots/genisom-gangben-l2.yaml).","COMPUTE BEVIDST IKKE SAT TIL EN VAERDI: \"Thanks to... onboard computational power, Shvana can quickly adapt\" naevner \"onboard computational power\" uden noget chip-navn, kerneantal eller TOPS-tal. Teksten baerer ingen maalbar oplysning ud over at der findes en computer ombord - ikke_oplyst er derfor mere aerligt end at gengive en indholdsloes saetning som et \"felt\".","KOMMUNIKATION (LTE/RF) HAR INTET SKEMAFELT: \"Communication: LTE, RF\" er robottens egen fjernstyrings-/dataforbindelse, ikke fysiske dataporte til tilbehoer (jf. samme afgraensning som Keybotic Keypers WiFi/Ethernet-afsnit, se data/robots/keybotic-keyper.yaml). Noteret her, ikke brugt til at udfylde dataporte.","MONTERINGSINTERFACE BEVIDST SAT TIL IKKE_OPLYST: producenten naevner \"payloads Shvana can carry include robotic arm, high resolution RGB/thermal cameras and specialized sensors\" - en KATEGORILISTE, men ingen monteringsstandard, boltmoenster, spaending eller lastkapacitet for selve grafnsefladen (i modsaetning til fx Cyvet, hvor siden eksplicit oplyser \"20kg industrial payload platform\"). At genbruge nyttelast-teksten som monteringsinterface ville kun gentage nyttelast_gaaende uden ny oplysning - derfor ikke_oplyst.","INGEN DIMENSIONER, IP-KLASSE, TEMPERATUR, BATTERI-Wh, LADETID, DOCKINGSTATION, HOT-SWAP, ROS2, SDK-SPROG, HAELDNING, FORHINDRINGSHOEJDE ELLER PRIS FUNDET NOGEN STEDER PAA PRODUCENTENS SITE (shvana-robot/, forside, careers, kontakt-side delvist utilgaengelig). Alle disse felter staar ikke_oplyst uden yderligere note, da der intet var at citere - hverken tal, kvalitativ tekst eller modsigelse.","BILLEDE: ingen billede:-blok i denne post - separat spor. Kandidat-URL''er fra producentens egen Shvana-side, fuld-maskine produktfotos: https://bhairavrobotics.com/wp-content/uploads/sites/197/2025/08/Shvana-page-pic1.png og .../Shvana-page-pic4.png - ikke bedoemt med oejne i dette spor."]'::jsonb),
  ('boston-dynamics-spot', 'Spot', 'Boston Dynamics', 'USA', 'Waltham, Massachusetts', 'i_produktion', null, null, '["Majoritetsejet af Hyundai Motor Group (Sydkorea). Noteret fordi producentland bliver tvetydigt.","To producentkilder: produktside (K1) og producentens eget datablad (K2, maerket Updated: 05/22/2024). De er uenige om laengde og vaegt."]'::jsonb),
  ('cvte-maxhub-x7', 'MAXHUB X7', 'CVTE', 'Kina', 'Guangzhou', 'i_produktion', 2025, null, '["STOPPROEVE (firbenet): Producentens EGEN produktside hedder ordret \"四足机器人 X7\" (\"Quadruped Robot X7\") og staar i CVTE''s produktnavigation under 机器人 > 四足机器人 (/product/quadrupedrobot). Nyhedsartiklen fra samme domaene skriver: \"视源股份自主研发的高性能工业级四足机器人MAXHUB X7首次亮相\" (CVTE''s selvudviklede hoejtydende industrielle FIRBENEDE robot MAXHUB X7 debuterer). Kilder: https://www.cvte.com/product/quadrupedrobot og https://www.cvte.com/news/detail/161afb60-856a-11f0-bd5d-fb86232a40db, begge hentet 2026-08-24.","OPGAVEBREVET BAD OM AT STARTE VED CVTE''S EGNE KANALER, DA MESSERAPPORTEN (fund/FUND-messe.md) ALDRIG FIK FAT I DEM - det lykkedes her: cvte.com har baade en dedikeret produktside (/product/quadrupedrobot) og flere nyhedsartikler om X7, ingen af dem set af messesporet.","ARTIKLENS DATO MODSIGER MESSERAPPORTENS ANTAGELSE OM WRC 2026: CVTE''s egen nyhedsartikel om X7''s debut er dateret 2025-08-08, og handler eksplicit om \"2025世界机器人大会\" (World Robot Conference 2025), IKKE 2026. X7 debuterede altsaa for et aar siden, ikke ved den aktuelle WRC. Produktet har siden vaeret i felten: samme domaene har en separat artikel (\"21000公里！小C家''机器狗''年度总结曝光\", cvte.com/news/detail/b215d840-e9d4-11f0-9573-c1812bef4fc9) om en 21.000 km kumuleret driftsdistance og en vundet \"最佳越障突破奖\" (bedste forhindringsgennembrudspris) ved et Guangzhou Tower-arrangement - lagt til grund for status i_produktion, men disse to tal (21.000 km, prisnavn) er begivenheds-/PR-tal, ikke specifikationer, og indgaar derfor IKKE i felter.","SVAG SPECIFIKATIONSTAETHED ER MAALT, IKKE ANTAGET: CVTE''s produktside er en marketing-highlights-side (\"产品亮点\") med retoriske overskrifter og fodnote-forbehold, IKKE en teknisk specifikationstabel som Astrall Dynamics'' eller Unitrees produktsider. Der findes intet fundet CVTE-datablad med maal, vaegt, nyttelast, hastighed eller DoF. maxhub.com selv (det globale MAXHUB-displaymaerke) har INGEN robotprodukter overhovedet - X7 ligger udelukkende under moderselskabet CVTE/视源股份''s egen produktnavigation, ikke under maxhub.com.","Producentens egne fodnoter paa \"产品亮点\"-siden svaekker flere af tallene med vilje: \"*续航时间: 在特定实验室环境(气温25°C、平坦硬质路面等)下持续行走测试所得，实际使用时间因产品配置、环境温度、路面状况、运行速度等因素而异\" (laboratorietal, reel brug varierer); \"*稳定穿越35°陡坡等地形...基于自适应步态算法与电驱动关节的实验室测试结果\"; \"*-20℃至55℃作业：指电池及核心元器件在该温度区间的正常工作范围，极端温度下性能可能部分受影响\". Disse forbehold er gengivet paa de enkelte felters advarsel.","MAXHUB X7''s SOESTERPRODUKT \"商用清洁机器人\" (kommerciel rengoeringsrobot, en ANDEN maskine, ikke firbenet) er den, der ifoelge nyhedsartiklen er solgt til Europa/Sydoestasien/Japan (\"进入欧洲、东南亚及日本市场\"). Det gaelder IKKE X7 - ingen EU-relevante felter er udfyldt for X7 paa dette grundlag.","INGEN billede:-blok. Billedkandidater fundet men ikke bedoemt med oejne i dette spor - se fund/FUND-kand2.md."]'::jsonb),
  ('deep-robotics-lite3', 'Jueying Lite3', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, ARRAY['Basic', 'Venture', 'Pro', 'LIDAR']::text[], '["Fire varianter i faneblade paa samme produktside. Nyttelasten falder, naar udstyret stiger: 5 - 4,5 - 4 - 2,5 kg. Producenten traekker sensorvaegten fra nyttelasten. Paa det felt, der filtreres mest paa, er de fire varianter fire forskellige robotter med en spredning paa faktor 2.","Ingen hastighed, ingen IP-klasse, ingen driftstemperatur, ingen batterikapacitet og ingen frihedsgrader paa nogen variant, paa noget sprog."]'::jsonb),
  ('deep-robotics-lynx-m20', 'Lynx M20', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["M20-siden har tre faneblade: M20, M20 Pro og M20S. Kortlaegningen er laest i sidens egen JavaScript, ikke gaettet.","Den eneste post i hele indsamlingen, hvor producenten selv trykker BEGGE trinhoejder med hver sin etiket: 80 cm enkelt trin mod 25 cm kontinuerlig trappe. Forholdet er 3,2 gange. Det er den bedste eksterne bekraeftelse paa, at de to felter skal vaere adskilt."]'::jsonb),
  ('deep-robotics-lynx-m20-pro', 'Lynx M20 Pro', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["M20-siden har tre faneblade: M20, M20 Pro og M20S. Kortlaegningen er laest i sidens egen JavaScript, ikke gaettet.","Den eneste post i hele indsamlingen, hvor producenten selv trykker BEGGE trinhoejder med hver sin etiket: 80 cm enkelt trin mod 25 cm kontinuerlig trappe. Forholdet er 3,2 gange. Det er den bedste eksterne bekraeftelse paa, at de to felter skal vaere adskilt."]'::jsonb),
  ('deep-robotics-lynx-m20s', 'Lynx M20S', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["Tredje faneblad paa M20-siden. Samme maal og vaegt som M20, men markant hoejere tal paa naesten alt andet - det er en anden robot, ikke en udstyrsvariant.","Indsamlingens taetteste post (18 af 31 felter). Den bryder robotdata-skillens advarselstaerskel paa 55 %, men alle 18 felter staar i producentens egen tabel paa producentens eget domaene. Det er taersklen, der skal justeres, ikke posten."]'::jsonb),
  ('deep-robotics-lynx-s10', 'Lynx S10', 'DEEP Robotics', 'Kina', 'Hangzhou', 'annonceret', null, null, '["Lanceringsside, ikke et datablad. Ingen specifikationstabel paa noget af sprogene. Alle fem tal staar i loebende broedtekst - de er svaerere at datere og lettere at aendre uden spor end tal i en tabel."]'::jsonb),
  ('deep-robotics-mini', 'Jueying Mini', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (deep-robotics-mini-3.png) var et LiDAR-punktskybillede, ikke et foto af robotten - fejlklassificeret som fabrikantfoto ved indsamlingen. De fire oevrige arkivkandidater (mini-1, -2, -4, -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt; billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig.","AEldre side, stadig online, afkoblet fra baade den engelske og den kinesiske navigation. Status kan ikke udfyldes fra kilden - i_produktion er et valg, ikke en aflaesning.","Batterifeltet er indsamlingens tydeligste gevinst ved at laese kilden paa originalsproget: den engelske side har en enhedsfejl, den kinesiske har det rigtige tal."]'::jsonb),
  ('deep-robotics-x20', 'Jueying X20', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["Producentens fulde navn: Hangzhou Yunshenchu Technology. Serier: Jueying og Lynx.","STATUS KAN IKKE UDFYLDES FRA KILDEN. Produktsiden lever paa begge sprog, men er afkoblet fra navigationen: linket er udkommenteret i baade header og footer paa EN og CN. Kun det kinesiske forsidegitter linker den stadig. Producenten har ikke erklaeret modellen udgaaet. i_produktion er derfor et valg, ikke en aflaesning.","Producentens eget forbehold, EN: All parameters are laboratory data, operating in real environment may have differences. CN: officielle testdata. De to formuleringer er ikke lige staerke."]'::jsonb),
  ('deep-robotics-x30', 'Jueying X30', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["Kinesisk og engelsk side er enige om samtlige tal. Eneste forskel: EN tilfoejer (battery included) til vaegten.","X30 oplyser INGEN nyttelast - hverken gaaende eller staaende, paa noget sprog. Den aeldre X20 oplyser 20 kg. Producentens flagskib er blevet mindre oplysende end sin forgaenger."]'::jsonb),
  ('deep-robotics-x30-pro', 'Jueying X30 Pro', 'DEEP Robotics', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["Staar som egen kolonne paa X30''s produktside. Afviger fra X30 paa tre felter: vaegt, det midterste maal og portlisten. Alt andet er tegn for tegn ens."]'::jsonb),
  ('genisom-gangben-l1', 'Gangben L1', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet): bestaaet, entydigt. Meta-keywords paa producentens egen produktside: \"具身智能,四足机器人,机器狗,行业级机器人,钢镚L1,...\" (fire ben; 四足机器人 = quadruped robot, 机器狗 = robot dog). Meta-description: \"钢镚L1是智身科技自主研发的首款行业级小型四足机器人\" (Gangben L1 er GENISOM AI''s selvudviklede foerste industriklasse smaa firbenede robot). https://www.genisomai.com/product-robot/L1, hentet 2026-08-24. L1 er en ren gaaende (\"点足\", punktfod) model, ikke en hjul-ben-hybrid.","PRODUKTIONSTAL 15.000+ ENHEDER: EFTERPROEVET SOM PRODUCENTENS EGET, IKKE KUN PRESSENS. Homepage genisomai.com viser billedtekst \"累计量产突破 15,000 台\" (kumuleret produktion har passeret 15.000 enheder) direkte i en heltalsgrafik paa forsiden. Selskabets egen om-os-side gentager det i en tidslinje: \"2026年6月底，完成了第15000台行业级具身智能机器人的量产\" (ved udgangen af juni 2026 blev produktion af den 15.000. industriklasse embodied-AI-robot fuldfoert). Begge citater er hentet direkte fra genisomai.com (hhv. forsiden og /aboutus.html, hentet 2026-08-24), ikke fra pressemateriale. FUND-messe.md''s oprindelige kilde for tallet var Sohu (presse) - denne runde bekraefter, at producenten selv trykker det samme tal paa egen hjemmeside. Tallet DAEKKER HELE GENISOM-KATALOGET (Gangben L1/L1-W/L2 + Tongchui M1), ikke L1 alene - producenten opdeler ikke tallet pr. model.","GANGBEN-SERIEN ER STOERRE END DE TO POSTER I DENNE OMGANG. Fundet paa genisomai.com, men IKKE bygget som selvstaendige poster: 钢镚 L1-W (hjul-ben-variant af L1), 钢镚 L1 Maker (undervisningsudgave af L1), 钢镚 L2-W og 钢镚 L2-W Ultra (hjul-ben-varianter af L2, dokumenteret i L2''s egen tekniske JSON-tabel). Desuden fandtes to selvstaendige produktlinjer hos samme producent, der IKKE hedder \"钢镚\"/Gangben: 铜锤 M1 (Tongchui M1, mellemklasse firbenet robot, egen produktside genisomai.com/product-robot/M1) og 铅球 SP1 (Qiuqiu SP1, eksplosionssikker hjul-ben firbenet robot). Alle er bekraeftet firbenede efter producentens egne ord (WebSearch-uddrag citeret i FUND-kand1b.md), men er UDENFOR denne opgaves navngivne omfang (\"Gangben-serien\") og er ikke efterproevet mod raa HTML paa samme niveau som L1/L2. Angivet her, saa et fravalg ikke forveksles med en forglemmelse.","SENSOR-UOVERENSSTEMMELSE MELLEM MARKEDSFOERINGSTEKST OG SPECIFIKATIONSTABEL, IKKE LOEST STILTIENDE: se samme problem paa genisom-gangben-l2.yaml (L2''s egen side har samme moenster). L1''s egen JSON-specifikationstabel naevner INGEN LiDAR for basismodellen - kun bredvinkelkamera og IMU.","REGELAENDRING (CEO''en, under dette spor): producentens eget materiale ud over produktsiden - PDF-datablade, manualer, udviklerdokumentation - taeller nu ogsaa som gyldig kilde, mod at det maerkes kildetype: sekundaer. Brugt til sdk_sprog nedenfor: github.com/zsibot er GENISOM AI''s egen officielle GitHub-organisation (linket direkte fra genisomai.com/download.html: \"官方 GitHub: https://github.com/zsibot/\"). Repoet \"genisom_L1_sdk\" er eksplicit navngivet \"Official SDK for Genisom L1 Series robots\" og README''en skriver \"基于 C++20 开发\" (udviklet med C++20) - ingen ROS/ROS2-omtale i den README. https://github.com/zsibot/genisom_L1_sdk, hentet 2026-08-24.","ROS2 IKKE SAT FOR L1, BEVIDST. Et andet repo i samme organisation, genisom_roamerx_open (\"Open-source navigation stack for GENISOM-AI robots\"), kraever eksplicit \"ROS2 Humble Hawksbill\" og er \"Based on ROS2 Nav2\". Men L1''s EGEN produktside naevner ikke navigationssystemet \"RoamerX\" - det er en \"新一代\"/naeste-generations-funktion, som kun staar paa L2''s produktside (se genisom-gangben-l2.yaml). Uden den kobling er der ikke grundlag for at saette ros2: ja paa L1 specifikt - feltet staar derfor ikke_oplyst, med denne begrundelse, i stedet for at antage at hele produktfamilien deler samme navigationsstak.","Tredjeparts-WebSearch-sammendrag (ikke direkte efterproevet mod raa HTML) naevner et valgfrit, konfigurerbart sensorsaet for L1 - Intel RealSense dybdekamera, Livox Mid360 LiDAR og NVIDIA Orin NX (op til 100 TOPS) - som IKKE staar i den officielle specifikations-JSON paa produktsiden (den viser kun \"8-kernet CPU\" og bredvinkelkameraet). Ikke medtaget som data, fordi den ikke kunne bekraeftes i raa HTML."]'::jsonb),
  ('genisom-gangben-l1-w', 'Gangben L1-W', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet, hjul-ben-hybrid): bestaaet. Meta-keywords paa L1-W''s egen produktside: \"具身智能,四足机器人,机器狗,行业级机器人,钢镚L1,铜锤M1,轮足机器人,...\" (四足机器人 = quadruped robot). Meta-description: \"钢镚L1-W是智身科技推出的首款行业级轮式四足机器人\" (Gangben L1-W er GENISOM AI''s foerste industriklasse hjul-firbenede robot). Sidens egen overskrift: \"钢镚 L1-W - 首款小型行业级轮式四足机器人\" (foerste smaa industriklasse hjul-firbenede robot). https://www.genisomai.com/product-robot/L1-W, hentet 2026-08-24. Hjul-ben-hybrid (12 ledmotorer + 4 hjulnavmotorer, jf. \"高性能轮毂电机: 4 个\" i den strukturerede specifikationstabel) - taeller efter opgavens egen regel om at hjul-ben-hybrider er firbenede, samme princip som Unitree B2-W.","IKKE EN DUBLET AF L1/L2: L1-W har egen produktside, eget navn, egne maal (630x430x485mm mod L1''s 630x360x415mm) og en fjerde hjulmotor-gruppe, L1 ikke har. Klart en selvstaendig variant, ikke L1 under et andet navn.","PRODUKTIONSTAL 15.000+ ENHEDER DAEKKER HELE KATALOGET: se genisom-gangben-l1.yaml for den fulde efterproevning - tallet er ikke opdelt pr. model og gentages derfor ikke her.","TO SOEGENDE MODELLER IKKE BYGGET DENNE RUNDE: L1-W''s egen produktside naevner \"钢镚 L1-W EDU\" (NVIDIA Orin NX, op til 100 TOPS, indbygget 3D LiDAR, dybdekamera, GNSS og 5G) som en selvstaendig konfiguration under \"形态百变, 场景无界\" - INGEN egen produktside fundet (kun en tekstboks paa L1-W''s side), ikke efterproevet med samme kildedisciplin. Desuden findes tre navngivne undermodeller \"ZSL-1 Air/Pro/Max\" i en model-vaelger nederst paa siden uden synlige separate specifikationer i denne HTML - heller ikke bygget."]'::jsonb),
  ('genisom-gangben-l2', 'Gangben L2', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet): bestaaet, entydigt. Meta-keywords paa producentens egen produktside: \"具身智能,四足机器人,机器狗,行业级机器人,钢镚L2,...\". Meta-description: \"钢镚L2是智身科技自主研发的新一代行业级小型四足机器人\" (Gangben L2 er GENISOM AI''s selvudviklede naeste-generations industriklasse smaa firbenede robot). https://www.genisomai.com/product-robot/L2, hentet 2026-08-24. Basismodellen (\"点足运动版\"/punktfod-bevaegelsesudgave) er ren gaaende, ikke hjul-ben.","PRODUKTSIDEN VISER TRE VARIANTER I ÉN STRUKTURERET JSON-BLOK: 钢镚 L2 (点足运动版, ren gaaende - denne post), 钢镚 L2-W (轮足运动版, hjul-ben) og 钢镚 L2-W Ultra (轮足环视版, hjul-ben med udvidet sensorpakke). Kun basisudgaven L2 er bygget som selvstaendig post i denne omgang - samme afgraensning som L1 (se genisom-gangben-l1.yaml''s noter om Gangben-seriens fulde omfang). L2-W og L2-W Ultra har egne komplette parametersaet i samme kilde-JSON og kan bygges som selvstaendige poster senere uden ny research.","PRODUKTIONSTAL 15.000+ ENHEDER: se genisom-gangben-l1.yaml for den fulde efterproevning (producentens eget tal, bekraeftet paa baade forside og /aboutus.html, daekker HELE kataloget - ikke L2 alene).","REGELAENDRING (CEO''en, under dette spor): producentens GitHub-organisation (github.com/zsibot, linket fra genisomai.com/download.html) taeller nu som gyldig kilde - mod sekundaer-maerkning. UNDERSOEGT FOR ros2/sdk_sprog, MEN IKKE BRUGT: se advarslen paa ros2-feltet nedenfor for den fulde begrundelse. Kort fortalt: L2''s egen produktside naevner \"新一代 RoamerX 智能导航系统\", og repoet github.com/zsibot/genisom_roamerx_open kraever ROS2 Humble - men repoets eget README skriver \"Hardware Deployment: TODO\", altsaa at koblingen til et faktisk saelgende produkt IKKE er dokumenteret af producenten selv. Sat til ikke_oplyst i stedet for et gaet, der ikke kan skelnes fra en maaling (regel 1). Se genisom-gangben-l1.yaml for et modeksempel, hvor samme regelaendring GAV et brugbart resultat (sdk_sprog: C++, fordi det repo eksplicit er navngivet den officielle L1-SDK, uden et ''TODO'' paa produktkoblingen).","SENSOR-UOVERENSSTEMMELSE, IKKE LOEST STILTIENDE: L2''s markedsfoeringstekst (samme side) skriver \"支持自动建图与路径规划，结合激光雷达与GNSS实现厘米级定位\" (understoetter automatisk kortlaegning og ruteplanlaegning, kombineret med LiDAR og GNSS for centimeterpraecis positionering) - hvilket antyder LiDAR. Men den STRUKTUREREDE specifikationstabel (samme sides window.techParamsData) lister KUN IMU og \"双目相机\" (stereokamera) under \"传感器\" for basismodellen L2 - INGEN lidar-raekke. En lidar-raekke (\"3D激光雷达: 工业级96线激光雷达*2\") findes KUN under L2-W Ultra-varianten i samme JSON. Feltet lidar er derfor sat til ikke_oplyst for basismodellen, ikke udledt af markedsteksten - de to kilder paa samme side modsiger hinanden, og det rettes ikke stiltiende.","BATTERI-Wh: to tal paa samme side, ikke indbyrdes modstridende, men heller ikke krydsbekraeftet af os. Et fremhaevet \"kapacitetskort\" paa siden skriver \"756Wh 大容量电池\" (756Wh stor-kapacitetsbatteri) - brugt som feltets vaerdi. Tilbehoerslisten i den strukturerede specifikationstabel skriver separat \"电池: 15000mAh\" uden spaending. Vi udregner IKKE Wh af mAh (regel 9) - de to tal er blot noteret som fundet paa samme side uden modsigelse."]'::jsonb),
  ('genisom-gangben-l2-w', 'Gangben L2-W', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet, hjul-ben-hybrid): bestaaet. L2-siden markerer denne variant \"轮足运动版\" (hjul-fod bevaegelsesudgave) i techParamsData - samme princip som Unitree B2-W/MOVENEW T1/Gangben L1-W.","INGEN SELVSTAENDIG URL: L2-W har intet eget navigationslink paa genisomai.com - den findes udelukkende som et fane-skift i den strukturerede specifikationstabel paa L2''s egen side (https://www.genisomai.com/product-robot/L2, techParamsData.datas[1], classname \"钢镚 L2-W\", id 1249). Alle feltvaerdier nedenfor er hentet fra netop denne JSON-blok, IKKE fra L2 (id 63, basisudgaven) eller L2-W Ultra (id 1250).","MARKETINGKORTETS TAL (70cm forhindringshoejde, 756Wh batteri, 86 TOPS) ER BEVIDST IKKE BRUGT HER: L2-sidens fremhaevede hero-marketingkort (\"70cm 垂直越障高度\", \"756Wh 大容量电池\", \"高达 86 TOPS 算力平台\") staar EN gang for hele siden, foer fanebladene, og er ikke gentaget i L2-W''s egen JSON-blok. De matcher L2 (basisudgavens) egne tal noejagtigt - men uden en eksplicit gentagelse i L2-W''s egen datablok kan de ikke sikkert tilskrives netop denne variant. forhindring_enkelt, batteri_wh og compute''s TOPS-tal staar derfor ikke_oplyst/uden TOPS-tal her, i modsaetning til den eksisterende L2-post, som bruger dem for basisudgaven."]'::jsonb),
  ('genisom-gangben-l2-w-ultra', 'Gangben L2-W Ultra', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet, hjul-ben-hybrid): bestaaet. L2-siden markerer denne variant \"轮足环视版\" (hjul-fod rundtomsyn-udgave) i techParamsData - samme hjul-ben-hybridtype som L2-W, med et udvidet 360°-sensorsaet oveni.","INGEN SELVSTAENDIG URL: samme forbehold som L2-W - findes udelukkende som fane-skift paa L2''s egen side (https://www.genisomai.com/product-robot/L2, techParamsData.datas[2], classname \"钢镚 L2-W Ultra\", id 1250).","MARKETINGKORTETS TAL (70cm forhindringshoejde, 756Wh batteri) ER BEVIDST IKKE BRUGT HER: samme forbehold som L2-W - hero-marketingkortets tal staar en gang for hele siden og er ikke gentaget i L2-W Ultra''s egen datablok, derfor ikke tilskrevet denne variant specifikt.","L2-W ULTRA HAR EGEN LIDAR-SPECIFIKATION, SOM L2/L2-W IKKE HAR: sensor-sektionen for netop denne variant navngiver \"3D激光雷达: 工业级96线激光雷达*2\" (industriel 96-linjers LiDAR, 2 stk.) - eneste GENISOM-post i dette spor med et konkret LiDAR-linjetal."]'::jsonb),
  ('genisom-qiuqiu-sp1', 'Qiuqiu SP1', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet, hjul-ben-hybrid): bestaaet, entydigt. Meta-keywords paa SP1''s egen produktside: \"防爆巡检机器人,四足机器人,机器狗,防爆机器人,防爆机器狗\" (四足机器人 = quadruped robot, 机器狗 = robot dog). Sidens egen produktkort naevner eksplicit tre bevaegelsesformer: \"匍匐通行\" (kravlende gennemgang), \"轮式行进\" (hjuldrevet fremdrift paa fladt terraen) og \"足式越障\" (benbaseret forhindringsovervindelse, \"稳健攀爬楼梯、跨越台阶及复杂障碍路面\" - stabil trappeklatring, trinoverskridelse og komplekst forhindringsterraen). https://www.genisomai.com/product-robot/sp1, hentet 2026-08-24. Hjul-ben-hybrid - taeller efter opgavens egen regel om at hjul-ben-hybrider er firbenede.","EKSPLOSIONSKLASSE, IKKE ET SKEMAFELT: sidens hero-badge skriver \"Ex d IIC T6 Gb\" (\"全链路隔爆屏障\" - fuld-kaede eksplosionsbarriere, godkendt til zone 1/2 eksplosive gasmiljoeer). Meta-descriptionen skriver en let afvigende streng \"Ex IIC T6 Gb\" (uden \"d\") - hero-badgets mere praecise \"Ex d IIC T6 Gb\" er brugt her som citat i denne note. Skemaet har intet eksplosionssikringsfelt, saa oplysningen kan ikke lande i felter-blokken - noteret her, saa den ikke gaar tabt.","LIDAR-FELTET SAT TIL IKKE_OPLYST PAA GRUND AF ET TVETYDIGT ORD, IKKE FORDI INTET BLEV FUNDET: SP1''s marketingtekst skriver \"感知雷达封装于隔爆视窗之后，保障精准感知\" (opfattelsesradar/-lidar indkapslet bag et eksplosionssikkert vindue, sikrer praecis opfattelse). Ordet \"雷达\" betyder generisk \"radar\" og bruges ikke her sammen med \"激光\" (som ellers klart betyder LiDAR paa L2-W Ultra''s side: \"3D激光雷达\"). Uden det praecise ord er det en gaetning at kalde det LiDAR specifikt - regel 1. Feltet staar derfor ikke_oplyst.","KOMMUNIKATION OG LADEMETODE, IKKE KORTLAGT TIL ET FELT: strukturerede tabel oplyser \"通讯方式: WIFI/4G/5G\" og \"充电方式: 无线/有线\" (lademetode: traadloes/kabelforbundet) - INGEN af de to felter passer praecist til et af de 30 skemafelter (kommunikationsform er ikke et felt; \"lademetode\" er ikke det samme som \"dockingstation\", som specifikt kraever en fysisk ladestation nogen har bekraeftet foelger med). dockingstation staar derfor ikke_oplyst, selvom traadloes ladning antyder en ladepude/-station kan findes - det er ikke eksplicit bekraeftet paa siden.","TYNDESTE KILDE I DENNE RUNDE: SP1''s egen strukturerede specifikationstabel har kun TRE sektioner (基础信息/性能参数/功能列表) mod L1/L2/M1''s fem-seks - INGEN sektion for ledparametre (frihedsgrader, moment) og INGEN sensor-sektion (kamera, IMU, LiDAR). Taetheden er derfor markant lavere end de oevrige fire poster i dette spor, og det er en aegte forskel i, hvad producenten oplyser om denne specifikke model - ikke en indsamlingsfejl."]'::jsonb),
  ('genisom-tongchui-m1', 'Tongchui M1', 'GENISOM AI', 'Kina', 'Beijing / Suzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet): bestaaet, entydigt. Meta-keywords paa M1''s egen produktside: \"具身智能,四足机器人,机器狗,行业级机器人,...\". Meta-description: \"铜锤M1是智身科技推出的中型行业级四足机器人，16个自由度\" (Tongchui M1 er GENISOM AI''s mellemklasse industriklasse firbenede robot, 16 frihedsgrader). Sidens egen overskrift: \"铜锤 M1 - 行业首款轻体型、高负载、全防护四足机器人\" (industriens foerste lette, hoejtbelastede, fuldt beskyttede firbenede robot). https://www.genisomai.com/product-robot/M1, hentet 2026-08-24. Selvstaendig produktlinje - hverken \"钢镚\"(Gangben) eller en dublet af L1/L2.","META-DESCRIPTIONS \"16个自由度\" MODSIGES AF DEN STRUKTUREREDE SPECIFIKATIONSTABEL, IKKE LOEST STILTIENDE: metabeskrivelsen paastaar 16 frihedsgrader, men den strukturerede tabel (samme side) skriver eksplicit \"关节电机数量: 12 个\" - samme moenster som L1/L2 (ledmotor-antal, ikke eksplicit \"frihedsgrader\"). 12 er brugt som feltvaerdi, fordi det staar i den strukturerede tabel; 16-tallet fra metabeskrivelsen er IKKE brugt, og uoverensstemmelsen er noteret her i stedet for at blive rettet stiltiende.","VAEGT-UOVERENSSTEMMELSE PAA SAMME SIDE, IKKE LOEST STILTIENDE: se advarslen paa egenvaegt nedenfor - marketingteksten paastaar \"naesten 1:1 negativt/positivt last-egenvaegt-forhold\" ud fra en \"~30kg\"-vaegt, mens den strukturerede tabel siger 41 kg.","KONKURRENCE- OG MARATHON-PAASTANDE, CITERET MEN IKKE EFTERPROEVET UD OVER PRODUCENTENS EGEN SIDE: \"2026北京亦庄机器人勇士挑战赛，铜锤M1 自主导航项目全场唯一完赛，并斩获四足机器人大类自主导航第一、奖项数第一、总分第一、速度第一\" (2026 Beijing Yizhuang Robot Warrior-udfordringen - M1 var det eneste hold, der gennemfoerte den autonome navigationsdisciplin, og vandt foerstepladsen i autonom navigation, flest priser, hoejeste totalscore og hurtigst i firbenet-kategorien). Samt: \"全球首次由自主跟随机器人陪人类完成马拉松赛事... 铜锤M1作为全球首个自主跟随的机器人\"关门兔\"完成半马陪跑任务\" (foerste gang globalt en autonomt foelgende robot fuldfoerte et marathon sammen med et menneske - M1 fungerede som verdens foerste autonomt foelgende \"sweep hare\" paa en halvmaraton). Ingen af de to hoerer til i de 30 skemafelter - noteret her som producentcitat, ikke som et efterproevet tredjepartsfaktum.","M1 HAR TO YDERLIGERE TIER-VARIANTER PAA SAMME SIDE, IKKE BYGGET: samme techParamsData-JSON som base-M1 rummer ogsaa \"铜锤 M1 Pro\" (tilfoejer UWB-modul, mikrofon/hoejtaler, taleopkald, RTK) og \"铜锤 M1 Ultra\" (tilfoejer 720° panoramasyn med fire fiskeoejekameraer). Begge er nye fund udenfor denne opgaves navngivne omfang (\"Tongchui M1\" i FUND-kand1b.md) - dokumenteret her, saa et fravalg ikke forveksles med en forglemmelse, samme princip som L2-W/L2-W Ultra fik i forrige runde."]'::jsonb),
  ('ghost-robotics-spirit-40', 'Spirit 40', 'Ghost Robotics', 'USA', 'ikke_oplyst', 'udgaaet', null, null, '["PRODUCENTEN OMTALER IKKE LAENGERE MODELLEN. https://www.ghostrobotics.io/spirit-40 svarer HTTP 404, og navigationen paa producentens forside indeholder praecis ET produktlink: /vision-60. Maalt 2026-08-19.","INGEN FELTER INDSAMLET. Der findes specifikationer hos forhandlere og i tredjepartsdatabaser; de er bevidst ikke hentet, fordi de ikke kan dateres mod producenten og ville give posten en falsk friskhed.","Status udgaaet er en katalogbeslutning truffet paa 404-svaret og navigationen, ikke en erklaering fra producenten. Producenten har ikke selv sagt, at modellen er udgaaet."]'::jsonb),
  ('ghost-robotics-vision-60', 'Vision 60', 'Ghost Robotics', 'USA', 'ikke_oplyst', 'i_produktion', null, null, '["HJEMBY ER IKKE OPLYST. FUND-vest skrev Philadelphia; strengen findes 0 gange i producentens forside, produktside og datablad. Sidefoden har kun Get In Touch, og databladet har e-mail og domaene, ingen adresse. Rettet efter KILDEKORT-B F6.","Databladet (SPECSHEET V3.3, 2024) downloades direkte fra produktsiden, men ligger paa producentens Webflow-CDN, ikke paa deres eget domaene. URL''en kan doe."]'::jsonb),
  ('keybotic-keyper', 'Keyper', 'Keybotic', 'Spanien', 'Barcelona', 'i_produktion', null, null, '["STOPPROEVE (firbenet): BESTAAET, entydigt og med to uafhaengige citater fra producentens egen /technology/-side: \"Keyper is an autonomous 4-legged robot designed to conduct industrial inspections\" og, i FAQ-afsnittet samme side, \"Its four legs, agile structure, and robust design allow Keyper to access the same areas a human could get to, including stairs, steps, slopes, and unstable terrains such as gravel -all of them environments in which a wheeled robot could not operate.\" Begge https://keybotic.com/technology/, hentet 2026-08-24.","STOPPROEVE (reelt produkt, ikke legetoej/hobbykit): BESTAAET. Keybotic har vundet 1. praemie i DARPA Robotics Challenge (\"1st Prize DARPA Robotics Challenge\", https://keybotic.com/, hentet 2026-08-24), har en offentliggjort case-story om reel drift hos en international kemivirksomhed (\"Keybotic Automates Inspection Rounds for International Chemical Manufacturer\", maj 2024, samme side) og saelger/udlejer robotten kommercielt via en Robot-as-a-Service-model (\"With our Robot as a Service (RaaS) employment model, you can hire your own Keyper and start automating your inspections now\", https://keybotic.com/technology/). Ingen tegn paa legetoejs- eller undervisningskit-karakter noget sted paa siden.","VIGTIGT FUND, DER OPDATERER fund/FUND-kandglobal.md: den globale scanning konkluderede at Keybotics specside var \"formularlaast\" og at kun presseformidlede tal (Uncrewed Systems, EU-Startups) var tilgaengelige. Det er korrekt for de to sider, der hedder \"Product Brochure\" (https://keybotic.com/product-brochure/) og \"Technical Specifications\" (https://keybotic.com/technical-specifications/) - begge bekraeftet formularlaaste i dette spor, se raa-kilderne. MEN producentens \"Technology\"-side (https://keybotic.com/technology/, IKKE fundet/besoegt i kandglobal-sporet) har et fuldt \"Specifications\"-afsnit direkte paa siden, uden formular. ALLE talfelter i denne post er hentet derfra, IKKE fra pressen - kildetype: primaer, ikke sekundaer.","PRESSETAL BEVIDST IKKE BRUGT: fund/FUND-kandglobal.md citerede en hastighed paa 2 m/s samt 90 min drift og 40 min hurtiglader fra Uncrewed Systems'' artikel, der interviewer virksomheden. L21/L33 tillader kun materiale fra producentens EGET domaene (produktside, PDF, manual, udviklerdok) som sekundaer kilde - forhandlere, databaser, anmeldelser og PRESSEOMTALE er eksplicit stadig ude. Uncrewed Systems og EU-Startups er presseartikler, ikke producentmateriale, og er derfor IKKE brugt som kilde til noget felt i denne post, selvom tallene isoleret set kunne have udfyldt hastighed-feltet. hastighed staar derfor ikke_oplyst, ikke 2 m/s.","LAENGDE < BREDDE: producentens egen specifikationsliste skriver \"Length: 60cm\" og \"Width: 95cm\" - bredden er stoerre end laengden. Det er usaedvanligt for en firbenet robot (laengde naese-til-hale er normalt den stoerste af de to vandrette maal), men staar saadan ordret paa siden og er IKKE rettet stiltiende (regel 9). Mulig forklaring, IKKE bekraeftet af producenten: \"Width\" kan daekke benenes spredning i staaende positur snarere end kroppens egen bredde - men det er en gaetning fra os, ikke et citat, og indgaar derfor kun som advarsel, ikke som rettelse.","DRIFTSTID UDEN ENTYDIG LASTBETINGELSE: siden skriver kun \"90/120 min battery run time\" uden at maerke, hvilket af de to tal der gaelder med/uden last (i modsaetning til fx Genisom L2''s eksplicitte \"5.5H（空载） 3.5H（满载）\"). Sat som interval min 90/maks 120 med ved_last: ikke_oplyst, jf. regel 8 - vi gaetter ikke, hvilket tal der hoerer til hvilken last.","PRIS: ROBOT-AS-A-SERVICE, INGEN FAST PRIS. FAQ: \"How much does it cost to hire a Keyper? With our Robot as a Service (RaaS) employment model, you can hire your own Keyper and start automating your inspections with no initial investment - the final costs will be adjusted based on each customer''s specific needs with different software applications. Of course, purchase options are also available.\" Der findes intet listetal at indsaette - feltet staar ikke_oplyst, ikke 0 eller nej, fordi producenten aktivt saelger/udlejer robotten, blot uden offentliggjort prisliste.","FORBINDELSE (WiFi/Ethernet/4G LTE) HAR INTET SKEMAFELT: \"Both WiFi and Ethernet connections are available. Latest bands of 2.4GHz, 5Ghz (160Mhz) and WiFi 6 802.11ax standards supported as well as 1000Base-T for Ethernet connections. Mobile 4G LTE optional.\" Dette er traadloes netvaerksforbindelse mellem robot og operatoer/sky, ikke fysiske dataporte til tilbehoer (som Genisom L2''s USB3.0/M12-stik) - derfor IKKE brugt til at udfylde dataporte-feltet, kun noteret her. Samme afgraensning som forbindelsesfeltet i skema-D9''s aabne punkter.","INSPECTION HEAD ER ET UNDERMODUL, IKKE HELE ROBOTTENS FRIHEDSGRADER: \"Pan range: -150º/150º\" og \"Tilt range: -55º/45º\" staar under overskriften \"Inspection Head\" (et separat 4kg hoved-modul med zoom-/termisk kamera, ultralydsmikrofon, projektoer og hoejttalere) og beskriver KUN dette moduls pan/tilt-bevaegelse - ikke robottens samlede antal frihedsgrader/led. frihedsgrader staar derfor ikke_oplyst, ikke 2.","BILLEDE: ingen billede:-blok i denne post - billedrunden er et separat spor (jf. opgavebriefen). Kandidat-URL''er fundet paa producentens egen /technology/-side, fuld-maskine studiofotos: https://keybotic.com/wp-content/uploads/2023/12/keyper-robot-03opt.png og https://keybotic.com/wp-content/uploads/2023/12/keyper-robot-04opt.png - ikke bedoemt med oejne i dette spor."]'::jsonb),
  ('mab-honey-badger-4', 'Honey Badger 4.0', 'MAB Robotics', 'Polen', 'Poznan', 'udgaaet', null, null, '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (mab-honey-badger-4-1.png) var logoet for et forskningsinstitut (\"Instituto Cajal\", roed stjerne), ikke et foto af robotten - fejlklassificeret som fabrikantfoto ved indsamlingen. De fire oevrige arkivkandidater (badger-4-2 til -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt; billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig.","PRODUCENTEN ERKLAERER SELV MODELLEN UDGAAET, ordret (inklusive producentens egen stavefejl): With the launch of the new version, sales of the Honey Badger 4.0 have officialy come to an end. Og: Don''t worry, we''ll support your existing HB4.0 robot during the warranty period.","Generationsskiftet gaar den forkerte vej paa to felter: 5.0 er tungere (17 mod 12 kg) og har lavere taethedsklasse (IP66 mod up to IP67), mens nyttelasten stiger (5 mod 4 kg) og driftstemperaturen udvides (0-45 mod 0-40 C)."]'::jsonb),
  ('mab-honey-badger-5', 'Honey Badger 5.0', 'MAB Robotics', 'Polen', 'Poznan', 'i_produktion', null, null, '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (mab-honey-badger-5-1.png) var byte-identisk med Honey Badger 4.0''s fejlbillede: logoet for et forskningsinstitut (\"Instituto Cajal\", roed stjerne), ikke et foto af robotten. Hele arkivmappen deler filsaet med Honey Badger 4.0 (samme fem sha256-summer); de fire oevrige kandidater (badger-5-2 til -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt. Billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig.","EU-PRODUCENT - den eneste i hele indsamlingen. MAB Robotics Sp. z o.o., ul. Za Cytadela 108, Poznan. VAT PL7822870297.","EU-KOLONNENS MODEKSEMPEL. Den eneste EU-producent i indsamlingen oplyser INTET om CE - og bredere: nul traef paa CE, conformity, declaration, certif, EN ISO, RoHS, ATEX, UKCA og FCC i 1,48 MB HTML, negativt OG positivt kontrolleret. Ikke fordi maskinen ikke har CE (en polsk maskine solgt i EU skal have det), men fordi CE er saa selvfoelgeligt for en EU-producent, at ingen skriver det. CE oplyst = nej betyder derfor ikke det samme for en polsk og en amerikansk producent. Kolonnen maa vise oplyst / ikke oplyst, aldrig har CE / har ikke CE.","Afloeser Honey Badger 4.0. Generationsskiftet gaar den forkerte vej paa to felter: 5.0 er tungere (17 mod 12 kg) og har lavere taethedsklasse (IP66 mod up to IP67) end 4.0."]'::jsonb),
  ('magiclab-magicdog-edu', 'MagicDog EDU', 'MagicLab', 'Kina', 'Wujiang/Suzhou', 'i_produktion', null, null, '["TO PRODUCENTSITES, DER MODSIGER HINANDEN. magiclab.top og det nye magiclabglobal.com er begge i luften, begge producentens egne, og de er ikke enige om vaegt, forhindringshoejde, frihedsgrader, driftstid og hastighed. Kilden her er magiclab.top; det globale sites afvigende tal staar i advarslerne. Hvilket site der er primaerkilde, er ikke indsamlerens beslutning.","EDU og PRO deler 41 af 43 tabelraekker. Den eneste specifikationsforskel er SDK-adgang: EDU har SDK-adgang, PRO har ikke. Maalt celle for celle: 43 datalinjer, 41 identiske, 2 forskellige (navneraekken og SDK-raekken)."]'::jsonb),
  ('magiclab-magicdog-pro', 'MagicDog PRO', 'MagicLab', 'Kina', 'Wujiang/Suzhou', 'i_produktion', null, null, '["TO PRODUCENTSITES, DER MODSIGER HINANDEN. magiclab.top og det nye magiclabglobal.com er begge i luften, begge producentens egne, og de er ikke enige om vaegt, forhindringshoejde, frihedsgrader, driftstid og hastighed. Kilden her er magiclab.top; det globale sites afvigende tal staar i advarslerne. Hvilket site der er primaerkilde, er ikke indsamlerens beslutning.","PRO og EDU deler 41 af 43 tabelraekker. Den eneste specifikationsforskel er SDK-adgang - og fortegnet er kontraintuitivt: EDU har SDK''et, PRO har det ikke."]'::jsonb),
  ('magiclab-magicdog-w', 'MagicDog-W', 'MagicLab', 'Kina', 'Wujiang/Suzhou', 'i_produktion', null, null, '["TO PRODUCENTSITES, DER MODSIGER HINANDEN - og her vender operatorerne. magiclab.top skriver hastighed 0-3 m/s og haeldning <= 40 grader; magiclabglobal.com skriver >= 3.0 m/s og >= 40 grader for samme robot, samme sprog, samme dag. Det ene er et loft, det andet et gulv. Kilden her er magiclab.top; det globale sites tal staar i advarslerne."]'::jsonb),
  ('magiclab-magicdog-y1', 'MagicDog Y1', 'MagicLab', 'Kina', 'Wujiang/Suzhou', 'i_produktion', null, null, '["Eneste MagicLab-model, hvor alle tre producentkilder (magiclab.top EN, magiclab.top CN og magiclabglobal.com) er indbyrdes konsistente. EN og CN er enige om hvert eneste tal.","DOKUMENTERET SAMMENFALD MED UNITREE B2, uden forklaring. Sensorstrengen er samme konstruktion med samme antal og samme forbehold; batteriet oplyses i samme form med samme 45 Ah; driftstidsintervallet 4-6 t er identisk; og lastbetingelsen >4 t ved 20 kg er identisk ned til operatoren. Men Y1''s hastighed er LAVERE (6 m/s mod B2''s > 6 m/s), maalene er blandede, og paa det eneste sammenlignelige trinfelt oplyser B2 et tal og Y1 intet. Vi paastaar ingenting om aarsagen."]'::jsonb),
  ('microrobotech-movenew-p1', 'MOVENEW P1', 'MicroRoboTech', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet): bestaaet. Meta-keywords paa P1''s egen produktside: \"quadruped robot, wheeled legged robot, ... high-payload legged robot\". Meta-description: \"All-terrain quadruped robot for industrial inspection, fire response, and public safety missions.\" (https://www.micbotics.com/list_12/98.html, hentet 2026-08-24). Hjul-ben-hybrid (''efficient wheeled cruising with superior legged obstacle-crossing capabilities'' i banner-teksten) - taeller som firbenet efter opgavens egen regel.","Se microrobotech-movenew-t1.yaml for producentens dokumenterede navneskifte MicroRoboTech -> Micbot (samme rebrand-noter gaelder her, gentages ikke).","Load Dimensions 595 x 419 x 129 mm (lastrummets maal) og Foldet maal 1150 x 800 x 200 mm er begge oplyst, men har intet skemafelt.","REGELAENDRING (CEO''en, under dette spor): se microrobotech-movenew-t1.yaml for den fulde undersoegelse af producentens support-side under den nye regel om PDF/manual-kilder. Kort: P1 har ogsaa en rigtig PDF (\"MOVENEW P1 Product Datasheet\", https://www.micbotics.com/public/upload/file/20260416/1776307542577931.pdf, 7,2 MB, hentet 2026-08-24), men den kunne af samme grund (intet poppler/pdftoppm, WebFetch 403, ingen laesbar tekst i de dekomprimerede indholdsstroemme) ikke laeses - ingen data herfra i posten. \"P1 SDK Development Guide\" og \"P1 Operation Guide\" har tomme download-links paa hentetidspunktet.","Tabellens raekkefoelge er forvirrende: \"Max Climbing Ability: 800 mm\" staar lige foer \"Step Negotiation: 45°\" og \"Slope Capability: >45°\" - dvs. to raekker med samme talvaerdi (45°) under to forskellige etiketter, og en meget stor 800 mm-vaerdi under en etikette (\"Climbing Ability\"), man normalt ville forvente var en vinkel. Ikke rettet stiltiende - se advarsler paa forhindring_enkelt og haeldning."]'::jsonb),
  ('microrobotech-movenew-t1', 'MOVENEW T1', 'MicroRoboTech', 'Kina', 'Hangzhou', 'i_produktion', null, null, '["STOPPROEVE (firbenet): bestaaet. Producentens egen produktside skriver i meta-keywords \"Micbot, quadruped robot, ...\" og i meta-description \"Micbot''s quadruped robot features... (70kg dynamic load, 200kg static load)...\" (https://www.micbotics.com/list_13/96.html, hentet 2026-08-24). T1 er en hjul-ben-hybrid (\"wheeled quadruped\"/\"轮式四足机器人\") - opgaven definerer hjul-ben-hybrider som firbenede, saa den taeller.","PRODUCENTEN HAR SKIFTET NAVN/DOMAENE. Domaenet CEO''ens opgave og pressen bruger (microrobotech.com) omdirigerer 301 til micbotics.com. Hele det nuvaerende site bruger brandnavnet \"Micbot\"/\"MICBOT\" (meta-keywords, sidens titel-tags \"...-MICBOT\", navigationslogo) - IKKE \"MicroRoboTech\". Det juridiske firmanavn er fortsat 杭州具微科技有限公司 (Hangzhou Juwei Technology), som 36Kr''s projektside oversaetter til \"MicroRoboTech\" (https://pitchhub.36kr.com/project/3401143382263687, hentet 2026-08-24). Producent-feltet her bevarer CEO''ens navngivning \"MicroRoboTech\", men det forbrugervendte brand at lede efter i fremtiden er \"Micbot\".","Datasheet-tabellen er identisk paa engelsk (micbotics.com) og kinesisk (micbotics.cn) site - alle 25+ raekker krydstjekket ordret, 0 afvigelser. Den engelske version er derfor brugt direkte som kilde uden oversaettelsesrisiko for selve tallene.","Foldet maal 1025 x 750 x 150 mm er oplyst men har intet skemafelt (skemaet har kun staaende maal).","\"Total Battery Weight: 40~50kg\" / kinesisk \"整机电机重量\" er en tvetydig etikette (blander \"整机重量\", helmaskinevaegt, med \"电池\", batteri). Placeret som egenvaegt ud fra sammenhaengen (staar under \"Mechanical Parameters\" sammen med maalene, ikke under \"Electrical Parameters\"), men ordlyden er ikke entydig - se advarsel paa feltet.","Ingen pris fundet paa nogen af de to sprogversioner - kun \"Buy Now\"/\"Get Solutions\"-kontaktknapper, intet trykt tal.","REGELAENDRING (CEO''en, under dette spor): producentens PDF-datablade/manualer taeller nu ogsaa som kilde. Producentens support-side (https://www.micbotics.com/support/, hentet 2026-08-24) har en rigtig, downloadbar PDF: \"MOVNEWT1 Product Datasheet\" (https://www.micbotics.com/public/upload/file/20260416/1776308031204027.pdf, 13,2 MB). Den blev hentet, men KUNNE IKKE LAESES med de vaerktoejer, der var til raadighed i denne session: Read-vaerktoejets PDF-understoettelse kraever pdftoppm/poppler-utils (ikke installeret paa maskinen), WebFetch gav HTTP 403 paa filen, og et forsoeg paa at trakke tekst direkte ud af PDF''ens komprimerede indholdsstrømme (Python + zlib) fandt ingen laesbare tekstoperatorer - filen er formentlig bygget som billeder/vektorgrafik uden en tekstlagbar tekst. INGEN data herfra er brugt i posten. \"T1 SDK Development Guide\", \"T1 Operation Guide\" og \"Micbot Reinforcement Learning/Perception SDK Developer Guide\" staar ogsaa paa support-siden, men alle fire har TOMME download-links (href=\"\") paa hentetidspunktet - ikke publicerede endnu, intet at hente."]'::jsonb),
  ('pudu-d5', 'PUDU D5', 'Pudu Robotics', 'Kina', 'Shenzhen', 'i_produktion', null, null, '["STOPPROEVE (firbenet): produktsiden i webbutikken haedrer selv titlen \"PUDU D5 Series Quadruped Robot | PUDU Official Store\" og undertitlen \"Industry-Grade Autonomous Quadruped Robot\" (H1 paa begge sider). Ingen tvivl om benantal - modsat Lenovo Daystar GS og Direct Drive TITA er der intet i producentens egen tekst, der peger paa andet end fire ben.","D5 og D5-W er SAMME produktside med en variantvaelger (Shopify-variant, samme handle \"pudu-d5\"). De to er alligevel skrevet som to filer her, i tråd med praksis for Unitree B2/B2-W, A2/A2-W, AS2/AS2-W og Go2/Go2-W.","Maksimalt ledmoment (\"Maximum Joint Torque\": 165 Nm / 121.7 lb·ft) og enkelt-opladning-raekkevidde (\"Single-charge range extends to 14 kilometers\", PR Newswire) har intet felt i skemaet og er derfor kun noteret her - de taeller ikke i specifikationstaetheden.","Vigtig uoverensstemmelse fundet ved felt-for-felt-efterproevning: Den generelle markedsfoeringstekst (samme ordlyd paa officiel side og webbutik) skriver \"Easily handles 25 cm steps, 30° climbs, and 45° descents\" - men den variant-specifikke sammenligningstabel paa webbutikken skriver noget andet for D5 alene: \"D5: 25° ascent, 45° descent\" og \"Maximum Step Height D5: 30 cm\". Markedsfoeringstekstens 30°/25cm er faktisk D5-W''s tabelvaerdier (30° ascent, 25 cm step), ikke D5''s. Felterne haeldning og trappetrin_kontinuerlig herunder bruger tabellen, IKKE markedsfoeringsteksten - se advarsel paa hvert felt.","Fodnote 5 paa den officielle produktside: \"PUDU D5 Series is shipped with dual high-precision 96-line LiDAR as the standard configuration. For specialized applications requiring enhanced perception, a dual 192-line LiDAR upgrade is available upon request.\" Den fremhaevede markedsfoeringstekst (\"Dual 192-line* spherical LiDARs\") beskriver altsaa en betalt opgradering, ikke standardkonfigurationen.","Raa HTML-bevis: media/_kilder/raa-kand1a-2026-08-24/pudu-d5-storeside-2026-08-24.html (butik, indeholder Shopify-produkt-JSON med pris og variant-tabel), pudu-d5-officielside-2026-08-24.html (pudurobotics.com/en/products/d5, indeholder fodnoterne 1-5), pudu-d5-prnewswire-2026-08-24.html (pressemeddelelse med lastbetinget driftstid)."]'::jsonb),
  ('pudu-d5-w', 'PUDU D5-W', 'Pudu Robotics', 'Kina', 'Shenzhen', 'i_produktion', null, null, '["STOPPROEVE (firbenet, hjul-ben-hybrid taeller jf. opgavens definition): webbutikkens beskrivelse skriver \"Choose between legged and wheel-legged configurations to match different terrain and mobility requirements\" - D5-W er den hjul-ben-hybride variant af samme firbenede platform som D5 (\"Industry-Grade Autonomous Quadruped Robot\"). Ingen tvivl om benantal i producentens egen tekst.","D5 og D5-W er SAMME produktside med en variantvaelger (Shopify, samme handle \"pudu-d5\"). Skrevet som to filer alligevel, i tråd med praksis for Unitree B2/B2-W, A2/A2-W, AS2/AS2-W og Go2/Go2-W. Feltet forgaenger er IKKE brugt her, fordi D5-W ikke er en efterfoelger i tid - kun den anden konfiguration paa samme side (Shopify-billedet for D5-W-varianten er tidsstemplet 2026-03-09, D5 selv 2026-02-04, men det er et billed-uploadtidspunkt, ikke en modeludgivelsesdato).","Se pudu-d5.yaml''s noter for den fulde redegoerelse af uoverensstemmelsen mellem den generelle markedsfoeringstekst (\"25 cm steps, 30° climbs, 45° descents\") og den variant-specifikke sammenligningstabel. For D5-W stemmer markedsfoeringsteksten faktisk overens med tabellens D5-W-raekke (30° ascent, 25 cm step) - modsat D5, hvor de IKKE stemmer overens.","Raa HTML-bevis: media/_kilder/raa-kand1a-2026-08-24/pudu-d5-storeside-2026-08-24.html (samme fil som pudu-d5.yaml - begge varianter staar paa denne ene side)."]'::jsonb),
  ('rainbow-robotics-rbq-10', 'RBQ-10', 'Rainbow Robotics', 'Sydkorea', 'Sejong-si', 'i_produktion', null, null, '["HJEMBYEN ER SEJONG-SI, IKKE DAEJEON. FUND-vest skrev Daejeon; strengen findes 0 gange i seks gemte producentfiler. Producentens egen sidefod skriver (30141) 8, Jipyeongjungang 3-ro, Jipyeon-dong, Sejong-si, Republic of Korea, tlf. +82-44-860-9600. Postnummer 30141 og omraadenummer 044 er begge Sejong. Firmaet udsprang af KAIST i Daejeon, men det er ikke, hvad kilden siger. Rettet efter KILDEKORT-B F5.","RAINBOW ROBOTICS UDGIVER HELE BRUGERMANUALEN OFFENTLIGT som en statisk side - inklusive batteridata, ledmomenter, IMU-specifikationer og monteringsinterface. Ingen formular, intet login. Det er derfor posten er indsamlingens taetteste vestlige/asiatiske post, og det giver en test, kataloget kan bruge: publicerer producenten sin brugermanual aabent, ja/nej."]'::jsonb),
  ('raion-robotics-raibo2', 'RAIBO2', 'Raion Robotics', 'Sydkorea', 'Daejeon', 'i_produktion', null, null, '["SPOERGSMAALET VAR, OM DEN OVERHOVEDET ER ET PRODUKT. SVARET ER JA. RAIBO2 er udviklet i KAIST RaiLab (prof. Jemin Hwangbo) og kommercialiseret af udspringervirksomheden Raion Robotics Inc. (라이온로보틱스), Daejeon, med kontor i Seoul. Produktsiden https://raionrobotics.com/en/product/Raibo2 svarede HTTP 200 den 2026-08-21 og har en salgssektion: For product purchases, demo requests, quotations, PoC projects, and business partnerships, contact our sales team. Posten er derfor oprettet - men under Raion Robotics, ikke under KAIST.","PRODUCENTEN OFFENTLIGGOER INGEN SPECIFIKATIONSTABEL FOR ROBOTTEN. Produktsiden har praecis én tabel, og den hoerer til AKTUATOREN: Peak Torque 100 Nm, Rated Voltage 48 V, Max Speed 195.8 rpm, Rated Current 14.1 A, Weight 1.8 kg. FAELDEN ER Weight 1.8 kg - det er én motormodul, ikke robotten. Ingen af de fem tal er foert ind som robotdata.","DE TRE TAL, DER ER FOERT IND, ER SEKUNDAERE OG MAERKET SOM SAADAN. De staar hos KAIST RaiLab, laboratoriet der byggede robotten, ikke hos den virksomhed der saelger den: 42 kg, op til 6 m/s, op til 8 timers uafbrudt drift. De er maerket kildetype sekundaer, saa det senere kan besluttes, om de overhovedet maa taelle med (robotdata-skillens regel 3). Uden dem ville posten vaere helt tom for tal, og en tom post ville skjule, at oplysningerne findes - bare ikke hos saelgeren.","SAMMENLIGN MED WEILAN E300: to poster med naesten nul oplyste felter, af to helt forskellige grunde. Weilan HAR oplyst og har taget det ned. Raion Robotics har aldrig oplyst noget om robotten, kun om dens motor. En katalogvisning, der viser begge som 0 %, taber den forskel.","MARATHONEN ER MARKEDSFOERING, IKKE EN SPECIFIKATION. Producenten skriver RAIBO2 demonstrates long-duration mobility through a public marathon course. Distancen og tiden staar ikke paa producentens side og er ikke hentet fra pressen."]'::jsonb),
  ('rivr-one', 'RIVR ONE', 'RIVR', 'Schweiz', null, 'i_produktion', null, null, '["Tidligere Swiss-Mile. RIVR Technologies AG, udspring fra ETH Zuerich. Hjul-ben-hybrid.","Robotten saelges tilsyneladende ikke som produkt, men som leveringstjeneste - produktsiden er skrevet til logistikkoebere, ikke til ingenioerer. Kun 3 af 31 felter er oplyst: ingen vaegt, ingen maal, ingen IP-klasse, ingen batteristoerrelse, ingen frihedsgrader. Negativsoegt paa tre sider for IP-klasse, kg, mm/cm, Wh og DoF - eneste traef er de 30 kg nedenfor.","SKEMAPROBLEM: RIVR oplyser RAEKKEVIDDE i km (over 30 km pr. opladning), ikke driftstid i timer. Skemaet har driftstid som felt og raekkevidde som beregnet felt; her er det omvendt. Med over 30 km og op til 14 km/t kunne man regne baglaens til ca. 2,1 timer - DET GOER VI IKKE. Det ville vaere et fabrikeret tal med to usikre operatorer ganget sammen.","RIVR TWO er navngivet i navigationen uden nogen specifikationer. Ingen post oprettet."]'::jsonb),
  ('unitree-a1', 'A1', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, null, '["A1-siden er en ren marketingside uden parametertabel. Det er ikke en fejl i indsamlingen - siden har ingen tabel. Konsekvensen er den laveste taethed i hele Unitree-materialet."]'::jsonb),
  ('unitree-a2', 'A2', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, ARRAY['A2', 'A2-PRO']::text[], '["Produktsiden er en varianttabel med to kolonner. Alle tal er ens for de to varianter undtagen IP-klasse og LiDAR-antal; forskellene staar paa de paagaeldende felter."]'::jsonb),
  ('unitree-a2-w', 'A2-W', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, ARRAY['A2-W', 'A2-W PRO']::text[], '["Hjulbenet udgave af A2. Alt der ikke afviger, er ordret identisk med A2''s side."]'::jsonb),
  ('unitree-aliengo', 'AlienGo', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, null, null),
  ('unitree-as2', 'As2', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, ARRAY['AIR', 'PRO', 'X', 'EDU']::text[], '["Varianttabel med fire kolonner. Kolonnerne er forskellige maskiner - se varianter-blokkene paa de enkelte felter."]'::jsonb),
  ('unitree-as2-w', 'As2-W', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, ARRAY['X', 'EDU']::text[], '["Hjulbenet udgave af As2. De to varianter adskiller sig kun paa ladestation og udvidelsesdok.","Siden modsiger sig selv fire steder om raekkevidde og forhindringshoejde. Parametertabellen er brugt som vaerdi; noegletalskortets tal er foert som advarsel."]'::jsonb),
  ('unitree-b1', 'B1', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, null, null),
  ('unitree-b2', 'B2', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, null, '["Billedport 24. aug 2026: billede fjernet. `fil:`-feltet pegede paa unitree-b2.jpg, som ikke findes paa disk - den faktiske fil var unitree-b2.png (bekraeftet med gyldige PNG-magicbytes og MANIFEST-match til unitree-b2-2.png, unitree.com/b2). Denne sessions billedlaesekvote blev opbrugt foer billedets indhold naaede at blive set - det er derfor ALDRIG blevet visuelt godkendt, kun sporet som en filstiskaeg. Billedet er slettet frem for gættet godkendt, jf. reglen om at et uefterproevet billede er lige saa risikabelt som et forkert. Skal ses og domsfaeldes paa ny naar kvoten er tilgaengelig."]'::jsonb),
  ('unitree-b2-w', 'B2-W', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, null, '["Hjulbenet udgave af B2."]'::jsonb),
  ('unitree-go1', 'Go1', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, ARRAY['Air', 'Pro', 'Edu']::text[], null),
  ('unitree-go2', 'Go2', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, ARRAY['AIR', 'PRO', 'X', 'EDU']::text[], '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (unitree-go2-1.png) var et skaermbillede af Unitrees fjernbetjenings-app paa en telefon - et LiDAR-punktskykort med kamerafeed og betjeningsknapper, ikke et foto af robotten. De fire oevrige arkivkandidater (go2-2 til -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt; billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig."]'::jsonb),
  ('unitree-go2-w', 'Go2-W', 'Unitree Robotics', 'Kina', null, 'i_produktion', null, null, '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (unitree-go2-w-1.jpg) viste et stort antal Go2-robotter opstillet i formation paa et stadion, hver med et roedt loeve-dans-kostumehoved paa ryggen, som skjuler selve produktets sensorhoved. Ikke en enkelt, tydelig maskine. De fire oevrige arkivkandidater (go2-w-2 til -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt; billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig."]'::jsonb),
  ('unitree-laikago', 'Laikago', 'Unitree Robotics', 'Kina', null, 'udgaaet', 2017, null, '["MODELLEN ER TAGET AF PRODUCENTENS SITE. Maalt 2026-08-21: https://www.unitree.com/laikago svarer HTTP 404 (gemt, 4.605 bytes), det samme goer /LaikaGo og /cn/laikago. Producentens forside blev hentet samme dag og gennemsoegt: 0 forekomster af strengen laikago, og navigationens 23 produktlinks (A1, A2, As2, aliengo, b1, b2, g1, go1, go2, h1, H2, R1, L2, z1, Dex-serien m.fl.) indeholder ikke modellen. STATUS UDGAAET ER EN KATALOGBESLUTNING PAA DE TO MAALINGER, ikke en erklaering fra Unitree - de har ikke selv sagt, at modellen er udgaaet.","PRODUCENTEN BEKRAEFTER, AT MODELLEN HAR EKSISTERET. Unitrees About-side, tidslinjen for 2017: In September 2017, the reconstructed quadruped robot Laikago came out (taken from the space dog Laika). Derfra kommer foerste_udgivelse 2017. Samme tidslinje naevner Laikago Pro under 2019 i en salgstalsopgoerelse - der findes altsaa mindst to varianter, men ingen af dem har en side.","NUL FELTER INDSAMLET, OG DET ER MED VILJE. Der findes specifikationer for Laikago i tredjepartsdatabaser og hos forhandlere. De er ikke hentet, fordi de ikke kan dateres mod producenten og ville give posten en falsk friskhed. Samme afgoerelse som paa Spirit 40.","HVORFOR POSTEN ALLIGEVEL FINDES: en oversigt, der kun viser de modeller producenten stadig markedsfoerer, fortaeller ikke en indkoeber, at Unitree har bygget firbenede robotter siden 2017, og hvilke der ikke laengere findes. Posten er en daekningsoplysning, ikke en katalogpost."]'::jsonb),
  ('weilan-alphadog-c500', 'AlphaDog C500', 'WEILAN', 'Kina', 'Nanjing', 'i_produktion', null, null, '["WEILAN Co., Ltd., ICP-nummer Su-ICP-Bei-19029747-1 (registreret i Jiangsu). Producentens etiket for varianten er C500 Standard developer version.","SPROGSKIFTEREN PAA WEILANS ENGELSKE SIDER ER BRUDT: menupunktet for kinesisk peger paa en URL, der svarer 404. Det gaelder alle tre proevede sider. Der findes ingen kinesisk primaerkilde at krydstjekke imod paa weilan.com.","Alle tal her er laest direkte i den gemte raafil, ikke afskrevet fra et referat.","PRISERNE 16.900 CNY og 86.900 CNY, som cirkulerer om Weilan-modeller, er IKKE overfoert til nogen model og maa ikke blive det. Weilans egen ordreside oplyser ingen priser overhovedet.","Producentens eget forbehold nederst paa siden: Some specifications or performance parameters can only be realized under specific conditions, og Due to standards and regulations, some features may not be available in all countries or regions."]'::jsonb),
  ('weilan-alphadog-c501', 'AlphaDog C501', 'WEILAN', 'Kina', 'Nanjing', 'i_produktion', null, null, '["WEILAN Co., Ltd., ICP-nummer Su-ICP-Bei-19029747-1 (registreret i Jiangsu). Producentens etiket for varianten er C501 Ultimate developer version.","SPROGSKIFTEREN PAA WEILANS ENGELSKE SIDER ER BRUDT: menupunktet for kinesisk peger paa en URL, der svarer 404. Det gaelder alle tre proevede sider. Der findes ingen kinesisk primaerkilde at krydstjekke imod paa weilan.com.","Alle tal her er laest direkte i den gemte raafil, ikke afskrevet fra et referat.","PRISERNE 16.900 CNY og 86.900 CNY, som cirkulerer om Weilan-modeller, er IKKE overfoert til nogen model og maa ikke blive det. Weilans egen ordreside oplyser ingen priser overhovedet.","Producentens eget forbehold nederst paa siden: Some specifications or performance parameters can only be realized under specific conditions, og Due to standards and regulations, some features may not be available in all countries or regions."]'::jsonb),
  ('weilan-alphadog-e300', 'AlphaDog E300', 'WEILAN', 'Kina', 'Nanjing', 'i_produktion', null, null, '["NUL PUBLICEREDE SPECIFIKATIONER. Den synlige del af produktsiden bestaar udelukkende af navigation, sidehoved og sidefod. Modelnavnene E300 og E400L er ikke synlige paa siden overhovedet; de staar paa producentens katalogside sammen med underteksten Enterprise Version Available.","SPECIFIKATIONERNE FINDES I FILEN, MEN ER TAGET NED. De ligger inde i en HTML-KOMMENTAR - byte 19.561 til 53.141, 33.580 bytes. Maalt: sidens krop er 73.121 tegn med kommentarer og 37.734 uden, altsaa 48 % af kroppen kommenteret ud. Inde i kommentaren ligger et komplet specifikationsark for begge modeller.","INTET AF DET ER FOERT IND SOM DATA, OG DET BOER INGEN GOERE. Kontrolleret: siden indeholder ingen innerHTML, ingen COMMENT_NODE og ingen kode, der genindsaetter blokken. En browser viser intet af det. At hente tal ud af en tilbagetrukket blok ville vaere at udgive noget, producenten har taget ned, med producentens navn paa.","Forskellen betyder noget for en indkoeber: det er ikke en producent, der aldrig har oplyst noget. Det er en producent, der HAR oplyst det og derefter skjult det.","DESIGNSPOERGSMAALET, DENNE POST STILLER: hvordan ser en post ud, hvor samtlige felter er ikke_oplyst? Ser den oedelagt ud, har vi bygget forkert. Weilans INDUSTRImodeller - dem en driftschef ville overveje - har 0 % taethed, mens deres legetoejsmodel har 35 %."]'::jsonb),
  ('weilan-alphadog-e400l', 'AlphaDog E400L', 'WEILAN', 'Kina', 'Nanjing', 'i_produktion', null, null, '["NUL PUBLICEREDE SPECIFIKATIONER. Den synlige del af produktsiden bestaar udelukkende af navigation, sidehoved og sidefod. Modelnavnene E300 og E400L er ikke synlige paa siden overhovedet; de staar paa producentens katalogside sammen med underteksten Enterprise Version Available.","SPECIFIKATIONERNE FINDES I FILEN, MEN ER TAGET NED. De ligger inde i en HTML-KOMMENTAR - byte 19.561 til 53.141, 33.580 bytes. Maalt: sidens krop er 73.121 tegn med kommentarer og 37.734 uden, altsaa 48 % af kroppen kommenteret ud. Inde i kommentaren ligger et komplet specifikationsark for begge modeller.","INTET AF DET ER FOERT IND SOM DATA, OG DET BOER INGEN GOERE. Kontrolleret: siden indeholder ingen innerHTML, ingen COMMENT_NODE og ingen kode, der genindsaetter blokken. En browser viser intet af det. At hente tal ud af en tilbagetrukket blok ville vaere at udgive noget, producenten har taget ned, med producentens navn paa.","Forskellen betyder noget for en indkoeber: det er ikke en producent, der aldrig har oplyst noget. Det er en producent, der HAR oplyst det og derefter skjult det.","DESIGNSPOERGSMAALET, DENNE POST STILLER: hvordan ser en post ud, hvor samtlige felter er ikke_oplyst? Ser den oedelagt ud, har vi bygget forkert. Weilans INDUSTRImodeller - dem en driftschef ville overveje - har 0 % taethed, mens deres legetoejsmodel har 35 %."]'::jsonb),
  ('weilan-babyalpha', 'BabyAlpha', 'WEILAN', 'Kina', 'Nanjing', 'i_produktion', null, null, '["INGEN SPECIFIKATIONSTABEL. Siden er ren markedsfoering: ingen vaegt, ingen maal, ingen hastighed, ingen driftstid, ingen batterital. Nul udfyldte felter.","Sensorerne naevnes i prosa uden modeller og uden antal: wide-angle vision, active infrared vision, 360-degree lidar, multi-time-of-flight (TOF) radar, microphone array, multipoint touch sensor, temperature and humidity sensor, 6DF inertial measurement unit (IMU) sensor, joint torque sensor, displacement sensor og 6D pose estimation. 360-degree lidar er type uden model og taeller ikke under D4.","Siden har en BUY NOW-knap, men INGEN PRIS.","KLASSEMARKERING MANGLER I SKEMAET. BabyAlpha er en hjemme-/selskabsrobot, ikke et arbejdsredskab. Den staar ikke paa CEO ens udelukkelsesliste (Petoi, MangDang, Hiwonder, Yahboom, Elephant Robotics, Sony aibo, Tombot), og er derfor konverteret - men om den hoerer i kataloget er et aabent spoergsmaal.","Weilan har tre nul-poster (E300, E400L, BabyAlpha) og en post paa 35 % (AlphaDog C500/C501). Den eneste model, der oplyser noget, er udviklerversionen af legetoejet."]'::jsonb),
  ('xiaomi-cyberdog-1', 'CyberDog', 'Xiaomi', 'Kina', null, 'i_produktion', 2021, null, '["SAMME FAELDE SOM CYBERDOG 2, SAMME LOESNING. Specifikationssiden leverer et tomt indholdselement; hele arket ligger som ren tekst i den JavaScript-bundle, siden selv beder browseren hente: https://cdn.cnbj1.fds.api.mi-img.com/mi.com-assets/shop/pro/js/product/cyberdog/specs.5406502c.js (gemt 2026-08-21, HTTP 200, 84.338 bytes, sha256 begynder med 601acc43). Primaerkilde: producentens egen server, producentens eget indhold.","BUNDLENS FILNAVN ER INDHOLDS-HASHET. Retter Xiaomi et tal, skifter filnavnet. Vedligeholdsrutinen skal hente HTML''en foerst og laese bundle-URL''en ud af den.","STATUS ER EN KATALOGBESLUTNING PAA MAALT LIGHED, IKKE EN ERKLAERING FRA PRODUCENTEN. Seks signaler blev sammenlignet mellem CyberDog 1 og CyberDog 2 paa mi.com: HTTP-status paa produktsiden (200 mod 200), koebsknappen 立即购买 (2 forekomster mod 2), laeg-i-kurv-knappen 加入购物车 (0 forekomster mod 0), udsolgt-markering 已售罄 (0 mod 0), price-feltet i sidens produkt-JSON (0 mod 0) og is_enable (false mod false). Alle seks er ens. Der findes altsaa INGEN maalbar forskel paa producentens side mellem den model, vi foerer som i produktion, og den her. Det eneste argument for udgaaet er, at der findes en efterfoelger med et hoejere generationsnummer - og det er vores slutning, ikke Xiaomis ord.","INGEN LIDAR I SENSORLISTEN. Producenten opremser tolv sensorer, og en LiDAR er ikke blandt dem. Det er IKKE foert som nej, fordi listen ikke er erklaeret udtoemmende. Til sammenligning navngiver CyberDog 2 en YDLIDAR TG30. Se advarslen paa lidar-feltet.","DYBDEKAMERAET ER ET ANDET END PAA CYBERDOG 2: her Intel RealSense D450, der D430."]'::jsonb),
  ('xiaomi-cyberdog-2', 'CyberDog 2', 'Xiaomi', 'Kina', null, 'i_produktion', null, null, '["SPECIFIKATIONERNE ER TEKST, IKKE BILLEDER - men de staar ikke i sidens HTML. Parametersidens indholdselement er tomt ved levering (75 bytes, kun en indlaesningssnurre); hele specifikationsarket ligger som ren tekst i den JavaScript-bundle, siden selv beder browseren hente: https://cdn.cnbj1.fds.api.mi-img.com/mi.com-assets/shop/pro/js/product/cyberdog2/specs.74df51bf.js (gemt, 200, 109.869 bytes). Det regnes som primaerkilde: producentens egen server, producentens eget indhold, og den tekst en besoegende faktisk faar vist.","VEDLIGEHOLDSFORBEHOLD 1: bundlens filnavn er indholds-hashet. Retter Xiaomi et tal, skifter filnavnet, og en gemt bundle-URL peger paa noget, der ikke findes. Vedligeholdsrutinen skal hente HTML''en foerst og laese bundle-URL''en ud af den - ikke gemme den som konstant.","VEDLIGEHOLDSFORBEHOLD 2: en validator, der kun ser sidens HTML, vil rapportere posten som TOM.","mi.com bruger en BLOKERINGSliste, ikke en tilladelsesliste: curl, tom user-agent, libwww-perl og Go-http-client faar alle 200; wget, Scrapy og Java faar 403 (fra Akamai, ikke fra Xiaomi). En hentelogik bygget paa antagelsen om at alle vaerktoejer blokeres, ville vaere bygget paa en fejl.","DENNE POST HAR SOM DEN ENESTE I HELE INDSAMLINGEN baade LiDAR-MODEL, FRIHEDSGRADER, ROS 2 og BATTERI I Wh - fire af de seks felter, der havde nul daekning paa alle tre referencerobotter i DATAMODEL.md."]'::jsonb),
  ('yobotics-e-dog', 'e-Dog', 'Shandong Youbaote Intelligent Robot', 'Kina', 'Shandong', 'i_produktion', null, null, '["AABENT PUNKT: producentens overskrift siger e-Dog, men beskrivelsen lige under handler om Y15. Overskriften er brugt som modelnavn.","E-DOG OPLYSER TRE NYTTELASTTAL, IKKE TO - og skemaet har kun to felter: maks. STATISK last 8 kg, maks. DYNAMISK last 5 kg, og dynamisk last I DRIFT 3 kg. Det tredje tal (arbejdslast) har ingen plads i skemaet og staar kun i advarslen paa nyttelast_gaaende. Det er en skemamangel, ikke en indsamlingsmangel."]'::jsonb),
  ('yobotics-y10', 'Y10', 'Shandong Youbaote Intelligent Robot', 'Kina', 'Shandong', 'i_produktion', null, null, '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (yobotics-y10-2.jpg) var et familiebanner: seks forskellige Yobotics-modeller opstillet i raekke, med indbraendt kinesisk marketingtekst (\"智能灵巧 轻松驾驭多场景\" / \"优宝特四足机器人系列\") - hverken en enkelt maskine eller Y10 specifikt identificerbar. De fire oevrige arkivkandidater (y10-1, -3, -4, -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt; billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig.","AABENT PUNKT: producentens overskrift siger Y10, men beskrivelsen lige under handler om Y5. Overskriften er brugt som modelnavn. Posten kan ikke laases, foer producenten er spurgt.","Yobotics er domaenenavnet; producentens eget engelske navn er Shandong Youbaote Intelligent Robot Co., Ltd."]'::jsonb),
  ('yobotics-y20', 'Y20', 'Shandong Youbaote Intelligent Robot', 'Kina', 'Shandong', 'i_produktion', null, null, '["Billedport 24. aug 2026: billede fjernet. Det tidligere billede (yobotics-y20-2.jpg, byte-identisk med det fjernede Y10-billede) var et familiebanner: seks forskellige Yobotics-modeller opstillet i raekke, med indbraendt kinesisk marketingtekst - hverken en enkelt maskine eller Y20 specifikt identificerbar. De fire oevrige arkivkandidater (y20-1, -3, -4, -5) kunne ikke efterproeves foer denne sessions billedlaesekvote blev opbrugt; billedet er derfor slettet, ikke byttet. Skal gennemses paa ny naar kvoten er tilgaengelig.","NAVNET. Producentens egen om-side skriver det kinesiske firmanavn med tegnet for fremragende (2 traef), ikke med tegnet for ven (0 traef) - samme udtale, forskelligt tegn, forskelligt firmanavn. Deres egen engelske gengivelse er Shandong Youbaote Intelligent Robot Co., Ltd. YOBOTICS ER DOMAENENAVNET, ikke firmaets eget engelske navn. Kataloget boer skrive begge og ikke lade et domaene blive til et firmanavn.","AABENT PUNKT, IKKE LOEST: overskrifterne og beskrivelserne paa producentens egen side er uenige om modelnavnene. Overskriften Y20 staar over en beskrivelse, der handler om Y30 (og Y10 over en Y5-beskrivelse, e-Dog over en Y15-beskrivelse). Tre ud af tre stemmer ikke. Overskriften er brugt som modelnavn. Posten kan ikke laases, foer nogen har spurgt producenten, hvilket navn der gaelder.","Specifikationerne staar i tabeller paa den engelske side, men selve tabellerne er paa kinesisk. Markup''en baerer x:str-attributter - tabellerne er indsat fra Excel."]'::jsonb),
  ('yufan-lingmao-cyvet', 'Lingmao Cyvet (灵猫·Cyvet)', 'Yufan Intelligent', 'Kina', 'Hangzhou', 'annonceret', null, null, '["STOPPROEVE (firbenet): Producentens egen navigation kalder produktet \"四足机器人\" (firbenet/quadruped-robot), link /embodied-ai/robot. Produktsiden skriver selv om bevaegelsen: \"无论是疾速奔跑、灵活转身，还是复杂的仿生步态，每一个指令都能精准执行\" (\"Uanset om det er lynhurtigt loeb, adroit vending eller kompleks biomimetisk gangart, udfoeres hver kommando praecist\"). Kilde: https://www.uniubi.com/embodied-ai/robot, hentet 2026-08-24.","Produktnavnet staar ordret \"灵猫•Cyvet\" paa koebssiden (shop/buy?product=air) - \"Cyvet\" er altsaa en del af det officielle produktnavn, ikke kun en presseoversaettelse. Firmaets engelske juridiske navn i copyright-linjen er \"Universal Ubiquitous AI Co., Ltd.\", brandmaerket paa sitet er \"UNIUBI AI\", og domaenet er uniubi.com (omdirigeret fra det aeldre uni-ubi.com). Kinesisk navn 宇泛智能/杭州宇泛智能科技 = samme selskab, jf. baike.baidu.com/item/杭州宇泛智能科技有限公司.","VIGTIG FORBEHOLD FRA PRODUCENTEN SELV: koebssidens bundtekst skriver ordret: \"本页参数基于当前工程样机测试结果与版本规划整理，部分功能及性能数据仍在持续开发和优化中。实际量产配置、性能表现及交付内容以订单确认信息和实际发货版本为准.\" (parametrene paa denne side er baseret paa test af det nuvaerende ingenioer-praeproduktionseksemplar og planlagte versioner; nogle funktioner og ydelsestal er stadig under udvikling; det faktiske masseproduktionsudstyr afgoeres af ordrebekraeftelsen). Derfor status: annonceret, ikke i_produktion - specifikationerne er selv markeret som proevemaskine-tal, ikke et endeligt produkt.","Feltet 关节峰值扭旋/额定扭矩 (led-drejningsmoment) har intet felt i skemaet. Noteret her: peak 60 N·m, nominel ca. 18 N·m pr. led (kilde som frihedsgrader nedenfor).","工作最大功率 (maks. arbejdseffekt) 3500 W har intet felt i skemaet - noteret her, ikke i felter.","INGEN billede:-blok. Billedkandidater fundet men ikke bedoemt med oejne i dette spor - se fund/FUND-kand2.md."]'::jsonb);
