  ((select id from robotter where slug = 'astrall-dynamics-hypertron-t01'), 'driftstid', 'interval', null, null, 4, 8, null, null, null, 't', null, null, null, 'https://www.astralldynamics.com/project-Hypertron-T01.html', '2026-08-24'::date, null, '"续航时间 4~8小时 (有负载/空载)" (belastet/ubelastet). Siden knytter IKKE de 4 timer eksplicit til en bestemt kg-vaerdi - vi gaetter ikke, at det er de 80 kg fra 工作负载-feltet, saa ved_last staar ikke_oplyst i stedet for at opfinde koblingen.', null, null, null, 'ikke_oplyst', null, null),
