  ((select id from robotter where slug = 'astrall-dynamics-hypertron-t01'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.astralldynamics.com/project-Hypertron-T01.html', '2026-08-24'::date, null, 'Under 消防应急-fanen: "全自主 高精度自主导航、全自主充电" (fuldautonom: hoejpraecisions-selvnavigation, fuldautonom opladning). Ordet "docking"/"充电桩" staar ikke ordret - "全自主充电" er tolket som en ladestation/dockingfunktion. Staar i produktsidens brancheafsnit, ikke i selve 产品参数-tabellen.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'astrall-dynamics-hypertron-t01'), 'lidar', 'tekst', null, null, null, null, '2x mekanisk LiDAR, 192 linjer, raekkevidde ca. 30m ± 10%, punktsky op til 1.720.000 pts/s (dobbelt-echo) / 860.000 pts/s (enkelt-echo), synsfelt 360°x90°, 10 Hz opdatering', null, null, null, null, null, null, 'https://www.astralldynamics.com/project-Hypertron-T01.html', '2026-08-24'::date, null, '"激光雷达 数量/检测距离: 2 台 / 30m ± 10%; 扫描线数/点云密度: 192线 / 1,720,000pts/s（双回波模式），860,000pts/s（单回波模式）; 视角/帧率: 360°*90° / 10 Hz".', null, null, null, null, null, null),
