  ((select id from robotter where slug = 'astrall-dynamics-hypertron-t01'), 'autonominiveau', 'tekst', null, null, null, null, '"我们利用高精度激光雷达构建实时构建高程图，使机器狗能''读懂''地形，从而在复杂环境中实现厘米级自主导航、稳定越障与自适应运动" (centimeter-praecis autonom navigation, stabil forhindringsforcering og adaptiv bevaegelse via realtids hoejdekort fra LiDAR). Sprogets sproglige klasse (SAE/ISO-niveau) er ikke oplyst - kun en kvalitativ beskrivelse.', null, null, null, null, null, null, 'https://www.astralldynamics.com/project-Hypertron-T01.html', '2026-08-24'::date, null, null, null, null, null, null, null, null),
