  ((select id from robotter where slug = 'boston-dynamics-spot'), 'ladetid', 'tal', null, 60, null, null, null, null, null, 'min', null, null, null, 'https://bostondynamics.com/products/spot/', '2026-08-19'::date, null, 'Databladets egen ladertabel siger noget andet: ved 25 C 50 min til 80 % og 2 t til 100 %; ved 35 C 2,5 t / 3,5 t. De 60 min er ikke betinget paa produktsiden.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'boston-dynamics-spot'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://bostondynamics.com/wp-content/uploads/2020/10/spot-specifications.pdf', '2026-08-19'::date, null, 'Spot Dock, fuldt specificeret: 1140 x 414 x 403 mm, 22,9 kg, ind 90-277 VAC, ud 58 V ved 12 A, 0-35 C, cTUVus Certified to UL 1564 og CSA C22.2 No. 107.2. Dockens Gigabit Ethernet passthrough hoerer her, ikke i robottens dataporte.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'boston-dynamics-spot'), 'lidar', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'boston-dynamics-spot'), 'kameraer', 'tekst', null, null, null, null, 'stereokameraer (antal og model ikke oplyst); vandret synsfelt 360 grader', null, null, null, null, null, null, 'https://bostondynamics.com/wp-content/uploads/2020/10/spot-specifications.pdf', '2026-08-19'::date, null, 'Strengen built-in stereo cameras staar KUN i databladet (marketingprosa, ikke specifikationstabel); Horizontal Field of View 360 staar paa produktsiden. FUND-vest tilskrev begge produktsiden - rettet her (KILDEKORT-A FEJL 2). Terrain sensing: 360 grader, raekkevidde 4 m, lys > 2 lux.', null, null, null, null, null, null),
