  ((select id from robotter where slug = 'boston-dynamics-spot'), 'sdk_sprog', 'liste', null, null, null, null, null, null, ARRAY['Python']::text[], null, null, null, null, 'https://bostondynamics.com/wp-content/uploads/2020/10/spot-specifications.pdf', '2026-08-19'::date, null, 'Producenten skriver Flexible API and Python SDK.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'boston-dynamics-spot'), 'autonominiveau', 'tekst', null, null, null, null, 'Manual & Autonomous Operation; Object Avoidance; Stair & Complex Terrain Navigation; autonome missioner startet fra dock', null, null, null, null, null, null, 'https://bostondynamics.com/wp-content/uploads/2020/10/spot-specifications.pdf', '2026-08-19'::date, null, 'Kvalitativt, ikke et niveau paa en skala. De tre citerede strenge findes KUN i databladet - produktsiden stoetter substansen i andre ord (KILDEKORT-A FEJL 3).', null, null, null, null, null, null),
