  ((select id from robotter where slug = 'boston-dynamics-spot'), 'stroem_ud', 'tekst', null, null, 35, 58.8, 'ureguleret DC 35-58,8 V, 150 W pr. port', null, null, 'V', null, null, null, 'https://bostondynamics.com/products/spot/', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'boston-dynamics-spot'), 'dataporte', 'liste', null, null, null, null, null, null, ARRAY['DB25 x2', 'Ethernet', 'WiFi 2,4/5 GHz b/g/n']::text[], null, null, null, null, 'https://bostondynamics.com/products/spot/', '2026-08-19'::date, null, 'FUND-vest skrev Gigabit Ethernet her. Rettet: strengen Gigabit findes ikke paa produktsiden, og i databladet staar den i Spot Dockens afsnit som passthrough to robot (KILDEKORT-A FEJL 1). Robottens egen CONNECTIVITY er WiFi + Ethernet uden hastighed.', null, null, null, null, null, null),
