  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'hastighed', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'haeldning', 'tal', null, 35, null, null, null, null, null, '°', null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, '"稳定穿越35°陡坡" med fodnote: "基于自适应步态算法与电驱动关节的实验室测试结果，实际地形性能受环境复杂度影响" (laboratorietestresultat; reel terraenydelse paavirkes af omgivelsernes kompleksitet).', null, null, null, null, null, null),
