  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'ip_klasse', 'tekst', null, null, null, null, 'IP66', null, null, null, null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, '"IP66级防水防尘".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'temp_min', 'tal', null, -20, null, null, null, null, null, '°C', null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, '"-20°C至55°C宽温作业" med fodnote: "指电池及核心元器件在该温度区间的正常工作范围，极端温度下性能可能部分受影响" (gaelder batteri og koernekomponenters normale arbejdsomraade).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'temp_maks', 'tal', null, 55, null, null, null, null, null, '°C', null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'batteri_wh', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'driftstid', 'tal', null, 8, null, null, null, null, null, 't', null, null, '>', 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, 'Producenten oplyser TRE punkter i én saetning: "40kg负载＞5H，20kg负载＞8H，空载＞11H". Skemaet har kun ét driftstidsfelt, saa mellempunktet (20kg > 8H) er valgt som primaer vaerdi; de to andre (40kg > 5H, 0kg/space > 11H) staar her. Fodnote: "在特定实验室环境(气温25°C、平坦硬质路面等)下持续行走测试所得，实际使用时间因产品配置、环境温度、路面状况、运行速度等因素而异" (laboratorietal ved 25°C paa fladt hardt underlag).', null, null, null, null, 20, 'kg'),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'hot_swap', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'ladetid', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, '"高度自主 定时启停、自主导航与回充" (hoej autonomi: tidsstyret start/stop, selvnavigation og selvopladning). Nyhedsartiklen (samme domaene) uddyber: "能够自主规划路径、定时启动任务、完成后自动返航充电" (kan selv planlaegge rute, tidsstyre opgavestart og koere hjem for selv at oplade efter fuldfoert opgave). Ordet "docking station"/"充电桩" staar ikke ordret nogen af stederne - "自主...回充"/"自动返航充电" er tolket som en automatisk opladningsfacilitet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'lidar', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.cvte.com/news/detail/161afb60-856a-11f0-bd5d-fb86232a40db', '2026-08-24'::date, null, 'Nyhedsartiklen: "深度融合激光雷达、里程计、IMU、UWB、GNSS、视觉相机等多种传感器" (dyb fusion af LiDAR, odometri, IMU, UWB, GNSS, visuelt kamera m.fl.). LiDAR naevnes kun som sensor-TYPE i en opremsning - intet antal, ingen model. Taeller ikke som udfyldt under D4''s foreloebige regel.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'kameraer', 'tekst', null, null, null, null, '可见光+红外双光云台 (dobbeltspektret synligt lys + infraroedt drejetaarn-kamera), model ikke oplyst', null, null, null, null, null, null, 'https://www.cvte.com/news/detail/161afb60-856a-11f0-bd5d-fb86232a40db', '2026-08-24'::date, null, '"X7搭载可见光+红外双光云台、气体传感器、机械臂甚至灭火装置".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'compute', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'ros2', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'sdk_sprog', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'autonominiveau', 'tekst', null, null, null, null, '"精准定位 百米长廊、空旷场地不迷路" (praecis positionering: farer ikke vild i 100-meter-korridorer eller aabne omraader). Nyhedsartiklen uddyber: "全栈自研的智能导航系统，通过多模态融合建图定位算法、感知算法和规划算法等技术，确保其在空旷场景、无特征长走廊、暗光/无光环境下仍能保持高定位精度" (fuldt selvudviklet navigationssystem, hoej positioneringspraecision i aabne omraader, traeklose lange korridorer og moerke/lysloese omgivelser). Fodnote paa produktsiden: "基于多维感知算法在特定场景（如超100米长廊、空旷区域）的实现效果，实际避障能力受环境动态变化影响" (specifikt scenarie-testet resultat; reel undvigeevne paavirkes af dynamiske aendringer). Ingen SAE/ISO-autonomiklasse oplyst.', null, null, null, null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'monteringsinterface', 'tekst', null, null, null, null, '"百变形态随心扩展 支持双光云台、气体传感器、机械臂等" (modulaer/udskiftelig montering af dobbeltspektret kamera, gassensor, robotarm m.fl.). Standardiseret monteringsflade/-maal eller hurtigskift-mekanisme ikke oplyst.', null, null, null, null, null, null, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, null, null, null, null, null, null, null),
