  ((select id from robotter where slug = 'deep-robotics-x30-pro'), 'dataporte', 'liste', null, null, null, null, null, null, ARRAY['USB 2.0', 'USB 3.0', 'Ethernet', 'WiFi']::text[], null, null, null, null, 'https://deeprobotics.cn/en/index/product3.html', '2026-08-19'::date, null, null, null, null, null, null, null, null),
