  ((select id from robotter where slug = 'genisom-gangben-l1'), 'egenvaegt', 'tal', null, 15, null, null, null, null, null, 'kg', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"整机重量（含电池）: 15 kg" - eksplicit "含电池" (inkl. batteri). RETTET VED SELV-TJEK: raekken har INTET "约" (cirka)-tegn foran vaegten, i modsaetning til maalene lige ovenover i samme tabel, som ER markeret "约". Foerste udkast af denne post satte fejlagtigt operator "~" paa vaegten ud fra en antagelse om, at hele sektionen delte samme cirka-markering - rettet efter genlaesning af raa-JSON''en.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'laengde', 'tal', null, 630, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"站立尺寸（长 x 宽 x 高）约 630 x 360 x 415 mm" - akserne ER maerket eksplicit af producenten (长=laengde, 宽=bredde, 高=hoejde), i modsaetning til MicroRoboTechs to poster.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'bredde', 'tal', null, 360, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'hoejde', 'tal', null, 415, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, 'Krybende maal ("趴地尺寸") er ~670 x 425 x 145 mm; skemaet har intet felt til den tilstand.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"关节电机数量: 12个" (antal ledmotorer), ikke eksplicit "frihedsgrader"/"自由度". Samme fortolkning som Unitree Go2 i denne samling.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'nyttelast_gaaende', 'tal', null, 8, null, null, null, null, null, 'kg', null, null, '~', 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"最大载荷 ≈ 8 kg（极限 ~10 kg）" - graensevaerdi op til ca. 10 kg oplyst separat.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'nyttelast_staaende', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'hastighed', 'tal', null, 3.7, null, null, null, null, null, 'm/s', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"最大速度: 3.7 m/s". En separat "极限速度" (graensehastighed) paa 5 m/s er ogsaa oplyst - ikke brugt som hovedvaerdi, fordi "最大速度" er den etiket, der svarer til "normal maksimal hastighed" i resten af samlingen.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'haeldning', 'tal', null, 30, null, null, null, null, null, '°', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"最大爬坡角度: 标准环境 30°，极限可达 40°" (standardmiljoe 30°, graense op til 40°). Standardvaerdien er brugt; graensevaerdien 40° er noteret her, ikke skrevet ind som feltets vaerdi.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'forhindring_enkelt', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
