  ((select id from robotter where slug = 'genisom-gangben-l1'), 'ip_klasse', 'tekst', null, null, null, null, 'IP54', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'temp_min', 'tal', null, 0, null, null, null, null, null, '°C', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'temp_maks', 'tal', null, 40, null, null, null, null, null, '°C', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'batteri_wh', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, 'Tilbehoersliste oplyser "电池": "标称容量 5 Ah，额定容量 4.6 Ah，电压 43.2 V" (nominel kapacitet 5 Ah, maerkekapacitet 4,6 Ah, spaending 43,2 V). Wh er IKKE trykt direkte, og vi udregner ikke Wh af Ah x V (regel 9 - MagicLab-posten er beviset paa, at producentens eget udregnede Wh-tal ikke altid stemmer med Ah x V).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'driftstid', 'interval', null, null, 1, 2, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"续航时间: 1-2 h", ingen lastbetingelse oplyst. Raekkevidde "续航里程: 6 km" er ogsaa oplyst; skemaet har intet raekkeviddefelt.', null, null, null, 'ikke_oplyst', null, null),
