  ((select id from robotter where slug = 'genisom-gangben-l1'), 'ladetid', 'tal', null, 1, null, null, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"充电时长: 1 h".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, 'Tilbehoersliste: "充电座: 标配" (ladesokkel, standardudstyr). Bekraefter en fysisk ladestation foelger med som standard, MEN bekraefter IKKE autonom hjemkoersel/selvgenopladning - det ord staar ikke paa L1''s side (modsat L2''s eksplicitte "自主回充功能").', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'lidar', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'kameraer', 'tekst', null, null, null, null, 'Bredvinkelkamera, 8 MP (800万像素), DFOV 122° / HFOV 111° / VFOV 70°', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'compute', 'tekst', null, null, null, null, '8-kernet CPU', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, '"基础算力: 8 核高性能 CPU". "工作最大功率: 3500W" er ogsaa oplyst i samme sektion; skemaet har intet effektfelt. Se ogsaa top-noten om et ubekraeftet, muligvis konfigurerbart RealSense/Livox/Orin-sensorsaet naevnt i tredjepartskilder, men ikke i denne officielle tabel.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'ros2', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'sdk_sprog', 'liste', null, null, null, null, null, null, ARRAY['C++']::text[], null, null, null, null, 'https://github.com/zsibot/genisom_L1_sdk', '2026-08-24'::date, 'sekundaer', 'Kilde er producentens egen GitHub-organisation (zsibot = GENISOM AI), repoet "genisom_L1_sdk", eksplicit navngivet officiel L1-SDK. README: "基于 C++20 开发" (C++20). Ikke produktsiden selv, derfor kildetype: sekundaer efter den nye regel.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'autonominiveau', 'tekst', null, null, null, null, 'AI强化学习运控 (标配, AI-forstaerkningslaering bevaegelsesstyring); 目标识别与追踪 (maalgenkendelse og -sporing); OTA升级; 二次开发支持 (understoetter videreudvikling)', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, 'Kvalitativ liste fra producentens funktionsafsnit, ikke et niveau paa en skala.', null, null, null, null, null, null),
