  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'egenvaegt', 'tal', null, 22, null, null, null, null, null, 'kg', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"整机重量（含电池）: 22 kg" - eksplicit "含电池" (inkl. batteri). Raekken har intet "约" (cirka)-tegn.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'laengde', 'tal', null, 630, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"站立尺寸（长x宽x高）约 630 × 430 × 485 mm".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'bredde', 'tal', null, 430, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'hoejde', 'tal', null, 485, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, 'Krybende maal ("趴地尺寸") er ~690 x 540 x 165 mm; skemaet har intet felt til den tilstand.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"关节电机数量: 12 个" (antal ledmotorer). Derudover 4 hjulnavmotorer ("高性能轮毂电机: 4 个"), som ikke taeller med i dette DoF-tal - skemaet har intet separat hjulmotorfelt.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'nyttelast_gaaende', 'tal', null, 10, null, null, null, null, null, 'kg', null, null, '~', 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"最大载荷 ≈ 10 kg（极限 ~12 kg）" - graensevaerdi op til ca. 12 kg oplyst separat.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'nyttelast_staaende', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'hastighed', 'tal', null, 3.7, null, null, null, null, null, 'm/s', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"最大速度: 3.7 m/s". En separat "极限速度" (graensehastighed) paa 5.5 m/s er ogsaa oplyst (marketingkortet skriver ">5.5m/s 极限奔跑速度") - ikke brugt som hovedvaerdi, samme princip som L1/L2.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'haeldning', 'tal', null, 30, null, null, null, null, null, '°', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"最大爬坡角度: 标准环境 30°，极限可达 40°" (standardmiljoe 30°, graense op til 40°). Standardvaerdien er brugt, samme princip som L1.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'forhindring_enkelt', 'tal', null, 65, null, null, null, null, null, 'cm', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"65cm 最大越障高度" fra sidens marketingkort - adskilt fra trappetrin_kontinuerlig, som staar med et andet, lavere tal i den strukturerede specifikationstabel. Samme to-felts-moenster som L2/deep-robotics-x30/B2.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'trappetrin_kontinuerlig', 'tal', null, 16, null, null, null, null, null, 'cm', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, 'Etiket "连续攀爬楼梯高度" (kontinuerlig trappeklatrehoejde) i den strukturerede specifikationstabel.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'ip_klasse', 'tekst', null, null, null, null, 'IP54', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'temp_min', 'tal', null, 0, null, null, null, null, null, '°C', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'temp_maks', 'tal', null, 40, null, null, null, null, null, '°C', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'batteri_wh', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, 'Tilbehoersliste oplyser "电池": "标称容量 5 Ah，额定容量 4.6 Ah，电压 43.2 V" (nominel kapacitet 5 Ah, maerkekapacitet 4,6 Ah, spaending 43,2 V) - samme tal som L1. Wh er IKKE trykt direkte, og vi udregner ikke Wh af Ah x V (regel 9).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'driftstid', 'interval', null, null, 1, 2, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"续航时间: 1-2h", ingen lastbetingelse oplyst - samme tal som L1. Raekkevidde "续航里程: 9km" er ogsaa oplyst (lavere end L1''s 6km-tal er IKKE - L1-W''s 9km er hoejere; skemaet har intet raekkeviddefelt).', null, null, null, 'ikke_oplyst', null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'hot_swap', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'ladetid', 'tal', null, 1, null, null, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"充电时长: 1h".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, 'Tilbehoersliste: "充电座: 标配" (ladesokkel, standardudstyr). Bekraefter en fysisk ladestation foelger med som standard, MEN bekraefter ikke autonom hjemkoersel/selvgenopladning.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'lidar', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'kameraer', 'tekst', null, null, null, null, 'Bredvinkelkamera, 8 MP (800万像素), DFOV 122° / HFOV 111° / VFOV 70°', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, 'Samme kameraspecifikation som L1 - kun IMU og bredvinkelkameraet staar i den strukturerede sensor-sektion, ingen lidar-raekke.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'compute', 'tekst', null, null, null, null, '8-kernet CPU', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"基础算力: 8 核高性能 CPU". "工作最大功率: 3500W" er ogsaa oplyst i samme sektion; skemaet har intet effektfelt.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'ros2', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'sdk_sprog', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'autonominiveau', 'tekst', null, null, null, null, 'AI强化学习运控 (标配); 目标识别与追踪; 基础动作 (站立/卧倒/阻尼/俯仰身形/高低身形/水平转身); 特技动作 (向前跳/向上跳/双腿站立/后空翻/打招呼等); 二次开发支持; OTA升级; 实时图像传输', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, 'Kvalitativ liste fra producentens funktionsafsnit, ikke et niveau paa en skala.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'monteringsinterface', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'stroem_ud', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'dataporte', 'liste', null, null, null, null, null, null, ARRAY['Ethernet', 'USB 3.0/2.0', '24V/12V stroem']::text[], null, null, null, null, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, '"开放 Ethernet、USB 3.0/2.0、24V/12V 电源等 7 大标准硬件接口" - producenten haevder 7 interfacetyper i alt, men "等" ("osv.") goer listen ikke-udtoemmende; kun disse tre kategorier er navngivet eksplicit.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'pris', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), 'ce_oplyst', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'egenvaegt', 'tal', null, 21, null, null, null, null, null, 'kg', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"整机重量（含电池）: 21 kg" - eksplicit "含电池" (inkl. batteri). Raekken har INTET "约" (cirka)-tegn, i modsaetning til maalene lige ovenover i samme tabel (samme moenster som genisom-gangben-l1.yaml, rettet ved selv-tjek der - kontrolleret her fra start efter samme fejl).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'laengde', 'tal', null, 720, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"站立尺寸（长 x 宽 x 高）约 720 x 390 x 480 mm" - akserne er eksplicit maerket af producenten.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'bredde', 'tal', null, 390, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'hoejde', 'tal', null, 480, null, null, null, null, null, 'mm', null, null, '~', 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, 'Krybende maal ("趴地尺寸") er ~780 x 460 x 190 mm; skemaet har intet felt til den tilstand.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"关节电机数量: 12个" (antal ledmotorer), ikke eksplicit "frihedsgrader". Samme fortolkning som L1 og Unitree Go2.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'nyttelast_gaaende', 'tal', null, 16, null, null, null, null, null, 'kg', null, null, '~', 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"最大载荷 ≈ 16 kg".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'nyttelast_staaende', 'tal', null, 150, null, null, null, null, null, 'kg', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"极限静态150kg" i specifikationstabellen, bekraeftet af samme tal i markedsfoeringsteksten ("最大静态载荷可达150kg") - to steder paa samme side, enige.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'hastighed', 'tal', null, 3.2, null, null, null, null, null, 'm/s', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"最大速度: 3.2 m/s". En separat "极限速度" (graensehastighed) paa 5 m/s er ogsaa oplyst - ikke brugt som hovedvaerdi, samme princip som L1.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'haeldning', 'tal', null, 40, null, null, null, null, null, '°', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"最大爬坡角度: 40°", bekraeftet af homepage-kapacitetskortet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'forhindring_enkelt', 'tal', null, 70, null, null, null, null, null, 'cm', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, 'Etiket "70cm 垂直越障高度" (70cm lodret forhindringshoejde) fra sidens kapacitetskort - adskilt fra trappetrin_kontinuerlig, som staar med et andet, lavere tal i den strukturerede specifikationstabel. Samme to-felts-moenster som deep-robotics-x30/B2.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'trappetrin_kontinuerlig', 'tal', null, 22, null, null, null, null, null, 'cm', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, 'Etiket "连续攀爬楼梯高度" (kontinuerlig trappeklatrehoejde) i den strukturerede specifikationstabel - lavere end det enkeltstaaende forhindringstal (70 cm), som forventet for de to forskellige maal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'ip_klasse', 'tekst', null, null, null, null, 'IP66', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'temp_min', 'tal', null, -20, null, null, null, null, null, '°C', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'temp_maks', 'tal', null, 55, null, null, null, null, null, '°C', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'batteri_wh', 'tal', null, 756, null, null, null, null, null, 'Wh', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"756Wh 大容量电池" fra sidens kapacitetskort. Se top-noten om det separate "15000mAh"-tal i tilbehoerslisten - ikke brugt til at udregne Wh, kun noteret som fundet uden modsigelse.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'driftstid', 'interval', null, null, 3.5, 5.5, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"续航时间: 5.5H（空载） 3.5H（满载）" (5,5 t tomgang / 3,5 t fuld last). Kvalitativ lastbetingelse (tom/fuld), intet kg-tal for "fuld last" - derfor ved_last: ikke_oplyst, ikke et masse-kort. Raekkevidde "续航里程: 20KM（空载） 12KM（满载）" er ogsaa oplyst; skemaet har intet raekkeviddefelt.', null, null, null, 'ikke_oplyst', null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'hot_swap', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'ladetid', 'tal', null, 1.5, null, null, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"充电时长: 1.5 h".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, 'Tilbehoersliste har TO raekker: "充电座: 标配" (ladesokkel, standardudstyr - samme som L1 har) OG separat "充电桩（包含自主回充功能）: 选配" (ladestation inkl. autonom genopladningsfunktion, TILVALG). L2 har altsaa baade en standard-ladesokkel OG en betalt opgradering til autonom hjemkoersel - dockingstation: ja daekker minimum den foerste; den autonome genopladningsfunktion specifikt er kun bekraeftet som tilvalg, ikke standard.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'lidar', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'kameraer', 'tekst', null, null, null, null, 'Stereokamera, 2 x 2,07 MP (双目相机)', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'compute', 'tekst', null, null, null, null, '8-kernet CPU, op til 86 TOPS', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"基础算力: 8 核高性能 CPU" fra den strukturerede specifikationstabel, kombineret med homepage-kapacitetskortets "高达 86 TOPS 算力平台" (op til 86 TOPS-regnekraftplatform) - begge fra genisomai.com, ikke krydsbekraeftet mod hinanden ud over at staa paa samme domaene.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'ros2', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://github.com/zsibot/genisom_roamerx_open', '2026-08-24'::date, null, 'UNDERSOEGT OG BEVIDST IKKE SAT TIL JA, EFTER SELV-TJEK FANGEDE FOR SVAGT BEVIS. L2''s egen produktside naevner "新一代 RoamerX 智能导航系统" som en navngiven feature, og producentens GitHub-repo "genisom_roamerx_open" kraever eksplicit "ROS2 Humble Hawksbill". Foerste udkast af denne post satte ros2: ja paa den kobling. Ved genlaesning af repoets EGEN README staar der dog under et afsnit "Hardware Deployment": "TODO" - producenten skriver selv, at koblingen mellem dette open source-repo og et fysisk, saelgende produkt IKKE er dokumenteret endnu. Et navnesammenfald (''RoamerX'') plus et repo, der selv siger ''TODO'' til hardware-udrulning, er en gaetning, ikke en maaling - regel 1. Rettet til ikke_oplyst.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2'), 'sdk_sprog', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
