  ((select id from robotter where slug = 'genisom-gangben-l2'), 'dataporte', 'liste', null, null, null, null, null, null, ARRAY['USB3.0 x2', 'M12 17PIN x1', 'M12 18PIN x1', '4G-kortplads x1']::text[], null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"功能拓展接口: 5个航插：2个USB3.0,1个M12 17PIN,1个M12 18PIN,1个4G卡槽" (5 flystik i alt: 2 x USB3.0 + 1 x M12 17PIN + 1 x M12 18PIN + 1 x 4G-kortplads = 5 - alle fem er navngivet i kilden, ingen uspecificerede).', null, null, null, null, null, null),
