  ((select id from robotter where slug = 'genisom-gangben-l2-w'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"关节电机数量: 12 个" (antal ledmotorer), ikke eksplicit "frihedsgrader". Samme fortolkning som L1/L2/M1.', null, null, null, null, null, null),
