  ((select id from robotter where slug = 'genisom-gangben-l2-w'), 'nyttelast_staaende', 'tal', null, 150, null, null, null, null, null, 'kg', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"极限静态150kg" staar inde i "最大载荷"-raekken i L2-W''s egen datablok. Modsat basisudgaven L2 er dette IKKE krydsbekraeftet af en separat marketingtekstlinje for netop L2-W - kun denne ene forekomst.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w'), 'hastighed', 'tal', null, 3.7, null, null, null, null, null, 'm/s', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"最大速度: 3.7 m/s" i L2-W''s egen datablok - hoejere end basisudgavens 3.2 m/s, som forventet for en hjuldrevet variant. En separat "极限速度" (graensehastighed) paa 5 m/s er ogsaa oplyst - ikke brugt som hovedvaerdi.', null, null, null, null, null, null),
