  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'ladetid', 'tal', null, 1.5, null, null, null, null, null, 't', null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, 'Tilbehoersliste har TO raekker: "充电座: 标配" (standardudstyr) OG separat "充电桩（包含自主回充功能）: 选配" (tilvalgt). Samme to-niveau-moenster som L2/L2-W.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'lidar', 'tekst', null, null, null, null, '2x industriel 96-linjers 3D LiDAR', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"3D激光雷达: 工业级96线激光雷达*2" - eneste GENISOM-post i dette spor med et konkret LiDAR-linjetal. RTK-positioneringsmodul ("RTK定位模块: 支持") er ogsaa oplyst i samme sensor-sektion; skemaet har intet dedikeret RTK-felt, saa det er gentaget under autonominiveau nedenfor.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'kameraer', 'tekst', null, null, null, null, 'Front-dobbeltkamera + rundtomsyn-fiskeoejearray, 2 x 2,07 MP', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"相机类型: 前向双目+周视鱼眼阵列" og "相机像索: 207万*2". Pixel-tallet (207万*2) staar kun ved siden af "前向双目" (front-dobbeltkameraet) i raastrengen - fiskeoeje-arrayets eget pixeltal er IKKE separat oplyst, saa 2,07 MP boer laeses som daekkende dobbeltkameraet, ikke noedvendigvis hele arrayet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'compute', 'tekst', null, null, null, null, '8-kernet CPU + 6-kernet CPU, 80 TOPS', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"基础算力: 8核高性能CPU+ 6核高性能CPU（80TOPS）" - to CPU''er, laveste TOPS-tal (80) af de tre GENISOM-modeller, der oplyser TOPS (L2 86, M1 100, denne 80) - formentlig fordi den ekstra sensorbelastning (dobbelt LiDAR, RTK) deler regnekraften.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'ros2', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'sdk_sprog', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'autonominiveau', 'tekst', null, null, null, null, 'AI强化学习运控 (标配); UWB (支持); 自主跟随 (支持, GLUE 全向自主跟随); 智能避障 (激光+视觉 融合避障); 目标追踪 (支持); 二次开发支持; OTA升级; 自主导航 (支持); 实时图像传输 (支持); RTK定位模块 (支持); 特技动作 (倒立/双腿站立/托马斯/后空翻); 基础动作 (站立/卧倒/匍匐前进/向前跳/向上跳/爬高台/锁定动作)', null, null, null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, 'Kvalitativ liste fra denne variants egen funktionsliste - rigere end L2/L2-W''s, tilfoejer autonom navigation som standard (ikke tilvalg), maalsporing, RTK og laser+vision-fusionsundvigelse.', null, null, null, null, null, null),
