  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), 'dataporte', 'liste', null, null, null, null, null, null, ARRAY['USB3.0 x2', 'M12 17PIN x1', 'M12 18PIN x1', '5G-kortplads x1']::text[], null, null, null, null, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, '"功能拓展接口: 5个航插：2个USB3.0,1个M12 17PIN,1个M12 18PIN,1个5G卡槽" - BEMAERK: 5G-kortplads, ikke 4G som paa L2/L2-W. Genlaest og bekraeftet forskellig fra de to andre varianter.', null, null, null, null, null, null),
