  ((select id from robotter where slug = 'genisom-qiuqiu-sp1'), 'forhindring_enkelt', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-qiuqiu-sp1'), 'trappetrin_kontinuerlig', 'tal', null, 23, null, null, null, null, null, 'cm', null, null, null, 'https://www.genisomai.com/product-robot/sp1', '2026-08-24'::date, null, '"攀爬能力: 23cm连续台阶" (23cm kontinuerlig trappeklatring). Intet separat enkelt-forhindringstal fundet paa siden - derfor er forhindring_enkelt ikke_oplyst i stedet for at genbruge dette tal.', null, null, null, null, null, null),
