  ((select id from robotter where slug = 'genisom-qiuqiu-sp1'), 'batteri_wh', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'genisom-qiuqiu-sp1'), 'driftstid', 'tal', null, 4, null, null, null, null, null, 't', null, null, '>=', 'https://www.genisomai.com/product-robot/sp1', '2026-08-24'::date, null, '"续航时间: ≥4 h" i den strukturerede tabel. Marketingkortet knytter samme tal til "满载" (fuld last): "4 h 满载续航 持续作业" - men INTET kg-tal staar direkte paa denne raekke. Et separat "50 kg 持续行走负载"-tal findes andetsteds paa siden, men er ikke eksplicit bundet til denne udholdenhedsangivelse - derfor ved_last: ikke_oplyst, jf. regel 8 og samme forsigtighed som L2/M1''s driftstidsfelter.', null, null, null, 'ikke_oplyst', null, null),
