  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Producenten skriver det ordret: 3 Degrees of Freedom per leg, 12-Motor back-drivable drive-train. Robotten er desuden capable of inverted operation.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'nyttelast_gaaende', 'tal', null, 10, null, null, null, null, null, 'kg', 'lb', 22, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Producenten skriver payload weight uden at skelne gaaende/staaende. Placeringen er en slutning. Der findes en User-selectable payload compensation mode.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'nyttelast_staaende', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'hastighed', 'tal', null, 2.4, null, null, null, null, null, 'm/s', 'mph', 4.9, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'TO FEJL I ET FELT, begge paa producentens egen side. (1) Punktlisten oeverst paa produktsiden skriver up to 2.5 meters/second (5.6 miles/hour); specifikationstabellen laengere nede paa SAMME side skriver 2.4 m/s som sprint. (2) Parret 2.4m/s (4.9 mph) gaar ikke op: 2,4 m/s = 5,37 mph, og 4,9 mph = 2,19 m/s. Alle andre par paa linjen er rigtige (0,9 = 2,01; 1,2 = 2,68; 3,0 = 6,71). Kun sprintparret er forkert, og fejlen staar i baade produktside og datablad. Standardgang er 0,9 m/s (2 mph), hurtiggang 1,2 m/s. Fejlen kraever en procenttolerance i validatoren, ikke kun en stoerrelsesordenstest.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'haeldning', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'climbs steep hills - uden tal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'forhindring_enkelt', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Footstep planning over curbs and grated surfaces - uden tal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'trappetrin_kontinuerlig', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Perception aided stair climbing - uden tal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'ip_klasse', 'tekst', null, null, null, null, 'IP67', null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Databladet uddyber: submerged in up to 1 meter of water for up to 30 minutes.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'temp_min', 'tal', null, -40, null, null, null, null, null, '°C', '°F', -40, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Producentens forbehold staar ved siden af tallet: Cold start not possible below -20 C. Charging rate decreases above 40 C, no charging below 0 C. Det NEDRE driftstal er altsaa ikke et koldstartstal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'temp_maks', 'tal', null, 55, null, null, null, null, null, '°C', '°F', 131, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'batteri_wh', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Ingen Wh nogen steder - hverken paa produktsiden eller i databladet. Det beregnede felt Wh pr. driftstime kan ikke regnes for denne robot.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'driftstid', 'tal', null, 3.15, null, null, null, null, null, 't', null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, '3.15 hours of continuous walking at 0.9 m/s. Ingen lastbetingelse, men en HASTIGHEDSBETINGELSE - den eneste i indsamlingen. Skemaet har ikke plads til den. Producenten oplyser ogsaa 21 timers standby og 10 km raekkevidde (terrain and payload dependent); produktsidens punktliste skriver samme tal som 3+ hours.', null, null, null, 'ikke_oplyst', null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'hot_swap', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Producenten skriver Quick-swap sub-assemblies within minutes (legs, battery, front & rear sensor heads). Within minutes er ikke hot-swap i drift. Foert som DELVIST, ikke som ja.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'ladetid', 'tal', null, 3, null, null, null, null, null, 't', null, null, '~', 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Standard battery charge time approx. 3 hours.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Wireless Charge Kit - wireless charging station for persistent 24x7 operation. FUND-vest skrev, at feltet kun stod i databladet; strengen staar ogsaa ordret paa produktsiden (KILDEKORT-B F1). Kilden er derfor produktsiden.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'lidar', 'tilstand_med_herkomst', 'nej', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Afsnittet Integrated Sensors indeholder ingen LiDAR. LiDAR findes som NYTTELAST (Security Payload), og Mission Control beskriver 3D lidar-based SLAM. Basisrobotten har den ikke - det er et nej paa basisspecifikationen, ikke et hul.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'kameraer', 'tekst', null, null, null, null, '5x RGB (1080p); 4x Intel RealSense D435 dybdesensor; dual antenna RTK GPS', null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'En af faa poster i hele indsamlingen med en kameramodel (D435).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'compute', 'tekst', null, null, null, null, 'NVIDIA Xavier, 32 GB RAM, 16-kanals GMSL2, 2 TB NVMe SSD', null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'ros2', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'C/C++, ROS, ROS2, MAVLink Compatible, Zeno, ATAK, JSON Mission. FUND-vest kildeangav feltet kun til databladet; strengen staar ogsaa i produktsidens DOM (KILDEKORT-B F2).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'sdk_sprog', 'liste', null, null, null, null, null, null, ARRAY['C/C++', 'ROS', 'ROS2']::text[], null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'API-niveauer: Low-level, High-Level, Mission Control. Simulator: Bullet Physics-based, Windows, Linux, Mac. Ogsaa denne staar paa produktsiden, ikke kun i databladet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'autonominiveau', 'tekst', null, null, null, null, 'Perception Aided Mobility; Record-Playback; Mission Control; kollisionsundgaaelse for og bag', null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Tre navngivne niveauer - den mest brugbare autonomibeskrivelse i hele indsamlingen.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'monteringsinterface', 'tekst', null, null, null, null, 'T-slots, M5 gevindhuller eller 1913 MIL-STD-skinner, med valgfrie kropspaneler', null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, null, null, null, null, null, null, null),
