  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'dataporte', 'liste', null, null, null, null, null, null, ARRAY['3x Ethernet', '1x USB 3.1', '6x GMSL2']::text[], null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Radio: 2,4 og 5,8 GHz WiFi samt 4G/LTE; GigE-switch.', null, null, null, null, null, null),
