  ((select id from robotter where slug = 'ghost-robotics-vision-60'), 'ce_oplyst', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, 'Feltet paa databladet hedder Export Control | HC og svarer US ECCN: EAR-99 | 8479.50.00.00 Industrial Robots (No ITAR restrictions). Producenten svarer paa et AMERIKANSK eksportspoergsmaal, ikke paa et europaeisk markedsadgangsspoergsmaal. Ingen CE naevnt.', null, null, null, null, null, null),
