  ((select id from robotter where slug = 'keybotic-keyper'), 'lidar', 'tekst', null, null, null, null, '3D LiDAR, 32 kanaler, 360° horisontalt / 90° vertikalt synsfelt, raekkevidde 35 m, praecision op til 1 cm, Class 1 oejensikker laser (IEC/EN 60825-1:2014), boelgelaengde 865 nm', null, null, null, null, null, null, 'https://keybotic.com/technology/', '2026-08-24'::date, null, '"Lidar model: 32 channels" - producenten navngiver selv modellen som kanalantallet, intet separat maerke/modelnummer oplyst. Oevrige tal ("Horizontal field of view: 360º", "Vertical field of view: 90º", "Range: 35m", "Precision: Up to 1cm", "Laser Product Class: Class 1 eye-safe per IEC/EN 60825-1: 2014", "Laser Wavelength: 865 nm") staar alle i samme Specifications-afsnit.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'keybotic-keyper'), 'kameraer', 'tekst', null, null, null, null, '5 kameraer (front top+bund, venstre, hoejre, bagud), dybderaekkevidde 10 m, RGB-billede 640×320@15FPS, dybdebillede 640×320@15FPS, 86° horisontalt dybdesynsfelt. Separat "Inspection Head"-modul (4 kg): zoomkamera, termisk kamera, ultralydsmikrofon, projektoer, hoejttalere', null, null, null, null, null, null, 'https://keybotic.com/technology/', '2026-08-24'::date, null, '"With 5 cameras -on the front (top and bottom), on the left, right, and back- Keyper has a depth range of 10m... RGB Image: 640×320 @ 15FPS, Depth Image: 640×320 @ 15FPS, Depth field of view: 86º horizontal" plus separat afsnit "Inspection Head - Weighting only 4kg... Zoom Camera, Thermal Camera, Ultrasonic Microphone, Spotlight, Speakers".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'keybotic-keyper'), 'compute', 'tekst', null, null, null, null, 'Intel Core 1260P CPU (4P+8E kerner, 16 traade), 16 GB RAM (op til 64 GB), 1 TB M.2-drev', null, null, null, null, null, null, 'https://keybotic.com/technology/', '2026-08-24'::date, null, '"CPU Model: Intel 1260P, CPU Cores: 4P + 8E, CPU Threads: 16, Memory: 16GB RAM (up to 64GB), Storage: 1TB M2 drive" under overskriften "Computing".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'keybotic-keyper'), 'ros2', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'keybotic-keyper'), 'sdk_sprog', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'keybotic-keyper'), 'autonominiveau', 'tekst', null, null, null, null, 'Fuldt autonom navigation og 3D-kortlaegning uden GPS eller internet ("can operate without a GPS even in unknown territories, as it maps constantly the environment in 3D to geolocalize itself"); fortsaetter opgaven uden internetforbindelse, men kan ikke sende realtidsalarmer offline; reagerer paa aendringer i omgivelserne og traeffer selv beslutninger om rute og handling; kan koordinere opgaver med andre Keyper-robotter; kan ogsaa teleopereres via realtidsbilleder', null, null, null, null, null, null, 'https://keybotic.com/technology/', '2026-08-24'::date, null, 'Sammensat af flere afsnit paa samme side: "Decision Making and Task Planning" ("Reacts to environmental changes and decides on actions and best routes... Coordinates and distributes missions with other Keypers") og FAQ ("Yes, Keyper can operate without a GPS...", "Keyper will still operate without an internet connection, continuing its mission normally..."). Ingen eksplicit navngivet autonominiveau-skala.', null, null, null, null, null, null),
