  ((select id from robotter where slug = 'keybotic-keyper'), 'pris', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://keybotic.com/technology/', '2026-08-24'::date, null, '"How much does it cost to hire a Keyper? With our Robot as a Service (RaaS) employment model, you can hire your own Keyper and start automating your inspections with no initial investment - the final costs will be adjusted based on each customer''s specific needs... Of course, purchase options are also available." Ingen listepris oplyst - se topnote.', null, null, null, null, null, null),
