  ((select id from robotter where slug = 'mab-honey-badger-5'), 'pris', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'mab-honey-badger-5'), 'ce_oplyst', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.mabrobotics.pl/honey-badger-5', '2026-08-19'::date, null, 'Negativkontrolleret med ordgraense: 0 traef paa CE i 1,48 MB HTML. Positiv kontrol paa ANYbotics-siden med samme udtryk gav 1 traef (FCC, CE and Anatel compliant), saa soegemetoden virker. Se noten om, hvorfor et nej her ikke betyder det samme som et nej hos en amerikansk producent.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'egenvaegt', 'tal', null, 15.8, null, null, null, null, null, 'kg', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'UDEN BATTERI (Net Weight, Excluding Battery) - unikt i indsamlingen; alle andre modeller, ogsaa MagicLabs egne MagicDog-W og Y1, oplyser vaegt MED batteri. Uden den markering bliver nyttelast delt med egenvaegt systematisk forkert, og forkert i den flatterende retning. Det globale site oplyser 17 kg med batteri for samme robot; de to tal er forenelige, hvis batteriet vejer ca. 1,2 kg, men det er en udledning og skrives ikke ind som data.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'laengde', 'tal', null, 670, null, null, null, null, null, 'mm', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'bredde', 'tal', null, 350, null, null, null, null, null, 'mm', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'hoejde', 'tal', null, 560, null, null, null, null, null, 'mm', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Liggende (Lying Down) 720 x 440 x 290 mm. Skemaet har ingen felter til foldemaal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'frihedsgrader', 'tal', null, 13, null, null, null, null, null, 'DoF', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Producenten skriver Degrees of Freedom (DOF) 13 og separat Aluminum Alloy Precision Joint Motor 12. Det globale site skriver samme tal som 12 + 1 (head DOF) - altsaa 12 i benene plus hovedet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'nyttelast_gaaende', 'tal', null, 5, null, null, null, null, null, 'kg', null, null, '~', 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Producenten skriver ca. 5 kg (maks. ca. 10 kg) med tegnet U+2248 og fuldbredde-parenteser. Der skelnes ikke mellem gaaende og staaende last.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'nyttelast_staaende', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'hastighed', 'tal', null, 3, null, null, null, null, null, 'm/s', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Etiket Maximum Speed. Det globale site skriver samme tal som Movement Speed 0-3.0m/s, altsaa et interval frem for et maksimum.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'haeldning', 'tal', null, 40, null, null, null, null, null, '°', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'forhindring_enkelt', 'tal', null, 15, null, null, null, null, null, 'cm', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Etiket Maximum Obstacle Height. Det globale site skriver Max Obstacle Step Height Approx. 18cm (lab data) for samme robot - 20 % hoejere, og med en laboratoriemarkering det aeldre site ikke har.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'trappetrin_kontinuerlig', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'ip_klasse', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'temp_min', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'temp_maks', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'batteri_wh', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Producenten trykker 29.6V 8200mAh 240.7W Fast Release. W er EFFEKT, ikke energi. Fejlen findes paa begge sprog - den er ikke et oversaettelsesuheld, men producentens egen. Selv laest velvilligt som 240,7 Wh passer det ikke: 29,6 V x 8,2 Ah = 242,7 Wh. Vi retter ikke, og vi regner ikke Wh ud af mAh og volt.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'driftstid', 'interval', null, null, 1.5, 3, null, null, null, 't', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Det globale site skriver i stedet Approx. 2.5 hours of continuous movement.', null, null, null, 'ikke_oplyst', null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'hot_swap', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'ladetid', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Battery Charging Dock markeret med udfyldt cirkel. Tabellen bruger udfyldt cirkel = ja og aaben cirkel = nej, og har INGEN tredje tilstand for ikke oplyst. En scraper, der kun leder efter den udfyldte cirkel, registrerer et nej som en manglende oplysning.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'lidar', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, '2D LiDAR - type uden model, taeller ikke under D4.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'kameraer', 'tekst', null, null, null, null, 'dobbeltkamera + dybdekamera + 4K HD-kamera + fiskeoejekamera + ultralydssensor', null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'compute', 'tekst', null, null, null, null, '8-kernet CPU', null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'ros2', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://support.magiclab.top/docs/dog/about', '2026-08-19'::date, null, 'Producentens egen udviklerdokumentation for MagicDog HAR ROS2 (ROS2 API, ROS2 SDK-vejledning, ros2_reference), og EDU er den variant, der har SDK-adgang. Feltet er alligevel IKKE udfyldt, fordi D1 - om producentens udviklerdokumentation maa taelle som kilde - er aaben. Vender D1, er feltet udfyldt. Dokumentationen er desuden kun paa kinesisk, saa kilden kan ikke laeses af en dansk laeser.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'sdk_sprog', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'SDK Support er markeret med udfyldt cirkel = JA paa EDU og aaben cirkel = nej paa PRO. Det er den eneste specifikationsforskel mellem de to modeller, og fortegnet er kontraintuitivt: det er EDU, der har SDK''et. Feltet spoerger om SPROGENE, og dem naevner produktsiden ikke - derfor ikke_oplyst her, mod PRO''s dokumenterede nej. Udviklerdokumentationen (D1 aaben) oplyser C++ og Python.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), 'autonominiveau', 'tekst', null, null, null, null, 'Smart Obstacle Avoidance; Patrol Mode; Smart Following', null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Alle tre markeret ja. Kvalitativt, ikke et niveau paa en skala.', null, null, null, null, null, null),
