  ((select id from robotter where slug = 'magiclab-magicdog-pro'), 'frihedsgrader', 'tal', null, 13, null, null, null, null, null, 'DoF', null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'Producenten skriver Degrees of Freedom (DOF) 13 og separat Aluminum Alloy Precision Joint Motor 12. Det globale site skriver samme tal som 12 + 1 (head DOF) - altsaa 12 i benene plus hovedet.', null, null, null, null, null, null),
