  ((select id from robotter where slug = 'magiclab-magicdog-pro'), 'sdk_sprog', 'tilstand_med_herkomst', 'nej', null, null, null, null, null, null, null, null, null, null, 'https://www.magiclab.top/en/dog', '2026-08-19'::date, null, 'SDK Support er markeret med aaben cirkel = NEJ paa PRO. EDU-varianten har udfyldt cirkel = ja. Det er den eneste specifikationsforskel mellem de to modeller, og fortegnet er kontraintuitivt.', null, null, null, null, null, null),
