  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'forhindring_enkelt', 'tal', null, 60, null, null, null, null, null, 'cm', null, null, '>=', 'https://www.magiclab.top/en/dog-y', '2026-08-19'::date, null, 'Producentens etiket er Maximum Climbing Height (CN: maks. klatrehoejde). HVERKEN EN ELLER CN siger, om det er et enkelt trin eller en kontinuerlig trappe - her hjaelper den kinesiske side ikke, i modsaetning til Lite3. Placeringen i forhindring_enkelt er en tolkning, valgt saa tallet IKKE kan forurene den sammenligning, der skal bruge det kontinuerlige felt.', null, null, null, null, null, null),
