  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'temp_maks', 'tal', null, 55, null, null, null, null, null, '°C', null, null, null, 'https://www.magiclab.top/en/dog-y', '2026-08-19'::date, null, 'Staar i broedtekst, ikke i tabellen.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'batteri_wh', 'tal', null, 2400, null, null, null, null, null, 'Wh', null, null, null, 'https://www.magiclab.top/en/dog-y', '2026-08-19'::date, null, 'Producenten trykker 45Ah (2400Wh), Voltage 54V. 45 x 54 = 2430 Wh, ikke 2400 - en afvigelse paa 30 Wh (1,2 %). Vi gengiver det trykte tal og noterer uoverensstemmelsen. Bemaerk: hverken Y1''s eller Unitree B2''s Wh-tal passer til deres eget Ah x V. Validatoren boer krydstjekke Wh mod Ah x V, naar begge er trykt - og et brud maa markeres, ikke rettes.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'driftstid', 'tal', null, 4, null, null, null, null, null, 't', null, null, '>', 'https://www.magiclab.top/en/dog-y', '2026-08-19'::date, null, 'Producenten skriver 4-6h ( >4 h continuous walking with 20 kg load ). Her bruges tallet med lastbetingelse. Ordret identisk med Unitree B2''s formulering, ned til operatoren.', null, null, null, null, 20, 'kg'),
