  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'kameraer', 'tekst', null, null, null, null, 'dybdekameraer x2 + optiske kameraer x2', null, null, null, null, null, null, 'https://www.magiclab.top/en/dog-y', '2026-08-19'::date, null, 'Producenten tilfoejer configurations may vary. Hele strengen (3D LiDAR x1 + Depth Cameras x2 + Optical Cameras x2 + forbehold) er samme konstruktion som Unitree B2''s.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'compute', 'tekst', null, null, null, null, '8-kernet CPU + hoejtydende beregningsmodul (157 TOPS)', null, null, null, null, null, null, 'https://www.magiclab.top/en/dog-y', '2026-08-19'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'ros2', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://support.magiclab.top/docs/y1/about', '2026-08-19'::date, null, 'NEGATIVT RESULTAT, maalt og ikke fornemmet: Y1-guidens navigation har 25 ruter (C++ API 7 tjenester, Python API 7 tjenester, 5 eksempler, SLAM-navigation, FAQ m.m.) og INGEN af dem er ROS2 - modsat MagicDog og MagicDog-W, som begge har det. Statuskoden er ikke bevis: /docs/y1/ros2_sdk svarer 200, men det goer enhver sti under /docs/<produkt>/ ogsaa. Feltet staar som ikke_oplyst frem for nej, fordi fravaeret er vores optaelling, ikke producentens udsagn.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'magiclab-magicdog-y1'), 'sdk_sprog', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://support.magiclab.top/docs/y1/about', '2026-08-19'::date, null, 'Udviklerdokumentationen oplyser C++ og Python. Ikke udfyldt, fordi D1 er aaben. Dokumentationen er kun paa kinesisk.', null, null, null, null, null, null),
