  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'nyttelast_staaende', 'tal', null, 400, null, null, null, null, null, 'kg', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Etiket "Max Standing Load".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'hastighed', 'tal', null, 3, null, null, null, null, null, 'm/s', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'haeldning', 'tal', null, 45, null, null, null, null, null, '°', null, null, '>', 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Etiket "Slope Capability: >45°". En anden raekke, "Step Negotiation", viser ogsaa 45° uden ">" - muligvis samme oplysning gentaget under to etiketter, muligvis en skabelonfejl hos producenten. Kun "Slope Capability"-raekken er brugt her, fordi den har den klareste etikette og operator.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'forhindring_enkelt', 'tal', null, 800, null, null, null, null, null, 'mm', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Etiket "Max Climbing Ability: 800 mm". Usaedvanligt stort tal for en enkelt forhindring (dobbelt saa hoejt som T1''s 400mm-klasse forhindring) - ikke efterproevet mod et andet felt, og kunne vaere en skrivefejl hos producenten (fx forvekslet med rampe-/last-relateret maal). Gemt ordret, ikke rettet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'trappetrin_kontinuerlig', 'tal', null, 25, null, null, null, null, null, 'cm', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Etiket "Stair Climbing Capability: Max step height 25cm".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'ip_klasse', 'tekst', null, null, null, null, 'IP67', null, null, null, null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Kilden tilfoejer "(Wheel Protection Rating IP68)" - hjulene har en anden, hoejere klasse end helmaskinen. Kun helmaskinens IP67 er brugt i feltet.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'temp_min', 'tal', null, -40, null, null, null, null, null, '°C', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'temp_maks', 'tal', null, 55, null, null, null, null, null, '°C', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'batteri_wh', 'tal', null, 3200, null, null, null, null, null, 'Wh', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, '"Hot-swappable 3.2kWh NMC battery (Supply voltage: 72V)".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'driftstid', 'interval', null, null, 8, 12, null, null, null, 't', null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, '"No-load continuous operating time: <=12h" og "Full-load continuous operating time: <=8h". To lastbetingelser (ingen last / fuld last) uden et konkret kg-tal for "fuld last" - kan derfor ikke skrives som et masse-kort i ved_last, kun som tilstanden ikke_oplyst. "Max Walking Load: 200kg" staar i tabellen, men producenten forbinder den IKKE eksplicit til "fuld last"-raekken, saa forbindelsen er ikke lavet her.', null, null, null, 'ikke_oplyst', null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'hot_swap', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Ordet "Hot-swappable" staar direkte i batteri-raekken.', null, null, null, null, null, null),
