  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'dockingstation', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'lidar', 'tekst', null, null, null, null, '96-line automotive-grade LiDAR (understoetter op til 3 enheder)', null, null, null, null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Etiket "Automotive-grade LiDAR: 96-line LiDAR 1 (supports installation of up to 3 units)". Linjetal oplyst - taeller derfor med under D4 (type MED model/specifikation), i modsaetning til T1''s.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'kameraer', 'tekst', null, null, null, null, 'HD Depth Camera (support for installation), Ultrasonic Radar (support for installation)', null, null, null, null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Begge raekker siger "Support for installation", IKKE at udstyret er standard monteret. Gemt som producentens egen formulering, ikke omsat til "ja, kamera monteret".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'compute', 'tekst', null, null, null, null, 'Understoetter op til 2000 TOPS', null, null, null, null, null, null, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, 'Raa tekst: "Supports 2000 tops". Ordet "Supports" antyder maksimal understoettet regnekraft ved tilvalgt modul, ikke noedvendigvis indbygget som standard - modsat T1, hvor "Jetson Orin NX Super+RK3588" er navngivet som det faktiske kernemodul.', null, null, null, null, null, null),
