  ((select id from robotter where slug = 'microrobotech-movenew-p1'), 'ce_oplyst', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'egenvaegt', 'interval', null, null, 40, 50, null, null, null, 'kg', null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'Etiket "Total Battery Weight" (kinesisk "整机电池重量") - ordret "helmaskine-batteri-vaegt", en sammenblandet etikette. Placeret som egenvaegt (med batteri), fordi raekken staar under "Mechanical Parameters" ved siden af maalene, ikke under "Electrical Parameters". Ikke en tastefejl fra vores side - producentens egen etikette er tvetydig.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'laengde', 'tal', null, 800, null, null, null, null, null, 'mm', null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, '"Standing Dimensions: 800mm x 600mm x 540mm" - producenten maerker ikke akserne. Braekkefoelgen laengde x bredde x hoejde er antaget efter saedvane, ikke bekraeftet af kilden (samme usikkerhed som deep-robotics-x30).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'bredde', 'tal', null, 600, null, null, null, null, null, 'mm', null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'USIKKER TILDELING - se laengde. Akserne er ikke maerket i kilden.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'hoejde', 'tal', null, 540, null, null, null, null, null, 'mm', null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'USIKKER TILDELING - se laengde. Foldet maal er 1025 x 750 x 150 mm; skemaet har intet foldefelt.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'frihedsgrader', 'tal', null, 16, null, null, null, null, null, 'DoF', null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'Producenten skriver "High-Performance Motors: 16 units", ikke "Degrees of Freedom". T1 er en hjul-ben-hybrid, saa de 16 motorer daekker formentlig baade ben-led og hjulnav - ikke noedvendigvis 16 rene bevaegelsesfrihedsgrader. Samme fortolkning som Go2''s motor-optaelling.', null, null, null, null, null, null),
