  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'driftstid', 'tal', null, 12, null, null, null, null, null, 't', null, null, '<=', 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'Etiket "Max Endurance Time: <=12h". Ingen lastbetingelse oplyst - kan derfor ikke sammenlignes direkte med en driftstid, der ER lastmaerket.', null, null, null, 'ikke_oplyst', null, null),
