  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'Raekken hedder "Charging Station: Fast Charge" (kinesisk: label "充电桩", vaerdi "快充"). Bekraefter en ladestation findes, MEN bekraefter IKKE autonom hjemkoersel/selvopladning - i modsaetning til GENISOM L2''s eksplicitte "包含自主回充功能" (inkl. autonom genopladningsfunktion). Fortolket som "ja, der findes en ladestation", ikke som "ja, med selvkoerende genopladning".', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'lidar', 'tekst', null, null, null, null, 'Onboard LiDAR (model ikke oplyst)', null, null, null, null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'Kilden markerer kun "Onboard LiDAR" med en udfyldt cirkel (til stede), uden model eller linjetal. Type uden model - taeller ikke under D4, naar den indstilling er valgt.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'microrobotech-movenew-t1'), 'kameraer', 'tekst', null, null, null, null, 'HD Depth Camera, 360° Panoramic Vision, Ultrasonic Radar', null, null, null, null, null, null, 'https://www.micbotics.com/list_13/96.html', '2026-08-24'::date, null, 'Ultrasonic Radar er strengt taget ikke et kamera, men skemaet har intet selvstaendigt radar-felt under sensorik - listet her for ikke at miste oplysningen.', null, null, null, null, null, null),
