  ((select id from robotter where slug = 'pudu-d5'), 'egenvaegt', 'tal', null, 61, null, null, null, null, null, 'kg', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Producentens etiket er "Weight (with Battery)" - inkl. batteri.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'laengde', 'tal', null, 900, null, null, null, null, null, 'mm', 'in', 35.4, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'USIKKER TILDELING. Producenten trykker "Standing Dimensions: 900 x 543 x 572 mm (35.4 x 21.4 x 22.5 in)" uden at maerke akserne enkeltvis. Foerste tal er her antaget som laengde, som i moenstret fra deep-robotics-x30.yaml. Ikke bekraeftet ud fra kilden.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'bredde', 'tal', null, 543, null, null, null, null, null, 'mm', 'in', 21.4, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'USIKKER TILDELING - se laengde. Andet tal i den utakserede trippel antaget som bredde.', null, null, null, null, null, null),
