  ((select id from robotter where slug = 'pudu-d5'), 'frihedsgrader', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'nyttelast_gaaende', 'interval', null, null, 20, 30, null, null, null, 'kg', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Producentens etiket er "Continuous Walking Payload: 20-30 kg (44-66 lbs)" - interval bevaret. PR Newswires overskrift "30kg Payload" bruger kun intervallets oevre graense.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'nyttelast_staaende', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'hastighed', 'tal', null, 5, null, null, null, null, null, 'm/s', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Fra generel markedsfoeringstekst "Cruises at up to 5 m/s", gaeldende for D5-serien bredt. Sammenligningstabellen har ingen selvstaendig hastighedsraekke pr. variant.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'haeldning', 'tal', null, 25, null, null, null, null, null, '°', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Fra den variant-specifikke sammenligningstabel: "D5: 25 ascent, 45 descent". Kun ascent (stigning) er brugt her; nedstigning er 45 grader for begge varianter, og skemaet har intet separat nedstigningsfelt. Se topnoten om uoverensstemmelsen med den generelle markedsfoeringstekst (30 grader), som er D5-W''s tal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'forhindring_enkelt', 'tal', null, 80, null, null, null, null, null, 'cm', 'in', 31.5, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Producentens etiket er "Climbing Capability: Up to 80 cm", identisk for D5 og D5-W. Tildelt forhindring_enkelt (regel 7) fordi producenten selv adskiller dette fra det lavere "Maximum Step Height"-felt (se trappetrin_kontinuerlig) - men ingen af de to etiketter bruger selv ordene "enkelt" eller "kontinuerlig", saa tildelingen er vores fortolkning.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'trappetrin_kontinuerlig', 'tal', null, 30, null, null, null, null, null, 'cm', 'in', 11.8, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Producentens etiket er "Maximum Step Height: D5: 30 cm (11.8 in)", lavere end "Climbing Capability" (80 cm, se forhindring_enkelt). Den generelle markedsfoeringstekst skriver i stedet 25 cm - det er D5-W''s tabelvaerdi, ikke D5''s. Se topnoten.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'ip_klasse', 'tekst', null, null, null, null, 'IP67', null, null, null, null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'temp_min', 'tal', null, -20, null, null, null, null, null, '°C', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'temp_maks', 'tal', null, 55, null, null, null, null, null, '°C', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, 'Separat producentfelt "Cold-Start Capability: Below -10°C" - en skarpere graense for opstart end drift. Skemaet har intet cold-start-felt; noteret her fordi -10°C ellers kunne forveksles med temp_min (-20°C).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'batteri_wh', 'tal', null, 1000, null, null, null, null, null, 'Wh', null, null, null, 'https://store.pudurobotics.com/products/pudu-d5', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'driftstid', 'tal', null, 2, null, null, null, null, null, 't', null, null, '>', 'https://www.prnewswire.com/news-releases/pudu-robotics-unveils-pudu-d5-series-industry-grade-autonomous-quadruped-robots-designed-for-complex-real-world-operations-302630095.html', '2026-08-24'::date, null, 'Pressemeddelelsen skriver "stable 30-kilogram payloads with over two hours of continuous runtime at full load" - eneste tal med eksplicit lastbetingelse (regel 8), derfor brugt frem for webbutikkens tabelvaerdi "Operating Time: 2 - 2.5 hours" (uden lastbetingelse, samme kilde som ovenstaaende felter).', null, null, null, null, 30, 'kg'),
  ((select id from robotter where slug = 'pudu-d5'), 'hot_swap', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
