  ((select id from robotter where slug = 'pudu-d5'), 'dockingstation', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.pudurobotics.com/en/products/d5', '2026-08-24'::date, null, '"Charging Station" listet som tilbehoer under "Modular Expansion". Fodnote 3: "Accessories such as the inspection kit and charging dock are optional and sold separately." - saelges saerskilt, ikke inkluderet i grundprisen.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'lidar', 'tekst', null, null, null, null, '96-linjers LiDAR x2 (standardkonfiguration); opgraderbar til 192-linjers LiDAR x2 mod tillaeg', null, null, null, null, null, null, 'https://www.pudurobotics.com/en/products/d5', '2026-08-24'::date, null, 'Fodnote 5: "PUDU D5 Series is shipped with dual high-precision 96-line LiDAR as the standard configuration. For specialized applications requiring enhanced perception, a dual 192-line LiDAR upgrade is available upon request." Den fremhaevede markedsfoeringstekst naevner kun 192-linjers-tallet og udelader dette forbehold.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'pudu-d5'), 'kameraer', 'tekst', null, null, null, null, '4x fiskeoejekameraer (120 graders synsfelt)', null, null, null, null, null, null, 'https://www.prnewswire.com/news-releases/pudu-robotics-unveils-pudu-d5-series-industry-grade-autonomous-quadruped-robots-designed-for-complex-real-world-operations-302630095.html', '2026-08-24'::date, null, 'PR-teksten: "Four 120° fisheye cameras". Webbutikkens sammenligningstabel skriver kortere "Dual 3D LiDAR + Four Fisheye Cameras" for samme felt uden vinkeltal.', null, null, null, null, null, null),
