  ((select id from robotter where slug = 'pudu-d5'), 'autonominiveau', 'tekst', null, null, null, null, 'Understoetter kontinuerlig, uovervaaget drift; udfoerer komplette selvstaendige arbejdsgange inkl. afgang, patrulje, forhindringshaandtering og retur-til-opladning.', null, null, null, null, null, null, 'https://www.prnewswire.com/news-releases/pudu-robotics-unveils-pudu-d5-series-industry-grade-autonomous-quadruped-robots-designed-for-complex-real-world-operations-302630095.html', '2026-08-24'::date, null, 'Kvalitativ, oversat fra: "the D5 handles complete autonomous workflows including departure, patrol, obstacle handling, and return-to-charge", i sammenhaeng med "supporting continuous, unsupervised operation even in dynamic environments". Intet numerisk autonominiveau (fx SAE-lignende skala) oplyst.', null, null, null, null, null, null),
