  ((select id from robotter where slug = 'rainbow-robotics-rbq-10'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://rainbowrobotics.github.io/RBQ/', '2026-08-19'::date, null, 'UDLEDT, IKKE OPLYST SOM SPECIFIKATION. Strengen 12 joints findes kun i SDK-afsnittene (LegJointInfo, Joint position and velocity (12 joints), Claim ownership of all 12 joints) - en API-beskrivelse. Soegning paa degrees of freedom giver 0 traef i hele manualen. Opdelingen 3 pr. ben foelger af hardware-tabellens tre ledtyper. Tallet er hoejst sandsynligt rigtigt, men producenten oplyser det ikke som specifikation (KILDEKORT-B F7). Ledspecifikation: nominelt moment 40/40/50 Nm, maks. 104/104/140 Nm, maks. vinkelhastighed 14,4/14,4/11,15 rad/s.', null, null, null, null, null, null),
