  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'hoejde', 'tal', null, 400, null, null, null, null, null, 'mm', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'Maal i LIGGENDE stilling (趴下) oplyses ogsaa: 807 x 406 x 206 mm. Det er en anden tilstand end sammenfoldet og er ikke sammenligneligt med Unitrees foldemaal. Skemaet har ingen felter til foldemaal.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'frihedsgrader', 'tal', null, 12, null, null, null, null, null, 'DoF', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'Producenten skriver 整机12，单腿3 - 12 i alt, 3 pr. ben.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'nyttelast_gaaende', 'tal', null, 3, null, null, null, null, null, 'kg', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'Producentens etiket er 最大负载 - maks. last, udelt, uden skelnen mellem gaaende og staaende. Placeringen i det gaaende felt er en slutning, praecis som paa CyberDog 2.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'nyttelast_staaende', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'hastighed', 'tal', null, 3.2, null, null, null, null, null, 'm/s', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'Producenten skriver MAX 3.2m/s. Fodnoten paa samme side: det laboratoriemaalte maksimum er 3,2 m/s, mens den maksimale SIKRE ganghastighed er 1,6 m/s. To tal paa samme side, halvdelen af hinanden. Det trykte hovedtal er 3,2.', null, null, null, null, null, null),
