  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'temp_min', 'tal', null, 0, null, null, null, null, null, '°C', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, '0 grader er en oplyst nedre graense, ikke et manglende tal. For udendoers dansk vinterdrift er den en diskvalifikator.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'temp_maks', 'tal', null, 40, null, null, null, null, null, '°C', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'batteri_wh', 'tal', null, 120.9, null, null, null, null, null, 'Wh', null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'NOMINEL kapacitet: 5,6 Ah / 120,9 Wh ved 21,6 V. Krydstjek: 5,6 x 21,6 = 120,96 - producentens tal gaar op. Producenten oplyser OGSAA en aftalt kapacitet paa 5,2 Ah / 112,3 Wh. De to er 7,1 % fra hinanden, og det er producentens egen forskel, ikke en fejl.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'driftstid', 'tal', null, 1, null, null, null, null, null, 't', null, null, '~', 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'INGEN LASTBETINGELSE, MEN EN TILSTANDSBETINGELSE. Producentens fodnote: den ene time er maalt som en blanding af at ligge ned, rejse sig, vise statiske positurer og gaa stabilt paa normalt underlag. Skemaet har ikke plads til den slags betingelse.', null, null, null, 'ikke_oplyst', null, null),
