  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'dockingstation', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), 'lidar', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, 'INGEN LIDAR NAEVNT. Producentens sensorliste har tolv punkter og ingen af dem er en LiDAR: RealSense D450-dybdekamera, AI-interaktionskamera, binokulaert ultravidvinkelkamera, TOF-sensor, lyssensor, ultralydssensor, inertimaaleenhed, GPS-modul, magnetometer, optisk flowsensor (光流计), 6MIC-ringarray og beroeringssensor. Feltet er ikke foert som nej, fordi producenten ikke erklaerer listen udtoemmende - men fravaeret er selv en oplysning.', null, null, null, null, null, null),
