  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'batteri_wh', 'tal', null, 432, null, null, null, null, null, 'Wh', null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, 'Trykt direkte som "432Wh" og bekraeftet i FAQ som "标配（10000mAh, 432Wh）" - IKKE beregnet af os ud fra mAh og spaending.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'driftstid', 'tal', null, 3.5, null, null, null, null, null, 't', null, null, '~', 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, '"15kg 带负载匀速行走续航约3.5小时". Spec-tabellens headlinetal "续航时间: 最大5.5h" er UDEN last (FAQ: "空载匀速行走续航约5.5小时") - det tal staar her, ikke i vaerdi-feltet, fordi regel 8 kraever en lastbetingelse, og 5,5t-tallet er netop uden last.', null, null, null, null, 15, 'kg'),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'hot_swap', 'bool', null, null, null, null, null, true, null, null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, 'FAQ: "电池支持快拆更换，备用电池可实现不中断轮换作业" (batteriet stoetter hurtig udskiftning; reservebatteri muliggoer uafbrudt rotation).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'ladetid', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'dockingstation', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'lidar', 'tilstand_med_herkomst', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, '"激光雷达 可选配" (LiDAR - tilvalg) - hverken type eller model oplyst, kun at det findes som tilvalg. Taeller ikke som udfyldt under D4''s foreloebige regel.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'kameraer', 'tekst', null, null, null, null, '双目高清可见光相机 (stereo/dobbeltoejet HD synligt-lys-kamera), model ikke oplyst', null, null, null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, 'Spec-tabel: "视觉传感器 双目高清动态相机". FAQ uddyber: "标准配置：双目高清可见光相机、IMU 惯性单元、内置麦克风扬声器、GPS 定位模组、4G 通信模块；可选配激光雷达、360°UWB 定位。"', null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'compute', 'tekst', null, null, null, null, 'Valgfrit tilkoeb: NVIDIA Jetson Orin Nano 8GB (op til 67 TOPS) / Orin NX 8GB (op til 117 TOPS) / Orin NX 16GB (op til 157 TOPS). Standardkonfiguration uden AI-modul ikke specificeret.', null, null, null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, '"端侧算力 Orin Nano 8GB 最高 67 TOPS AI 算力 / Orin NX 8GB 最高 117 TOPS AI 算力 / Orin NX 16GB 最高 157 TOPS AI 算力" - alle tre er mærket 可选配 (tilvalg) paa forsiden.', null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'ros2', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'sdk_sprog', 'liste', null, null, null, null, null, null, ARRAY['C++', 'Python']::text[], null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, 'FAQ: "官方已提供C++、Python标准SDK，支持高级、低级控制接口，开放模型，具备完整二开能力". GitHub: https://github.com/uniubi-ai (naevnt i samme svar, ikke selvstaendigt efterproevet i dette spor).', null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'autonominiveau', 'tekst', null, null, null, null, 'Understoetter stemmedialog, foelge-gang, helhusspatrulje og fjernvisning i hjemmescenarier ("语音对话、跟随行走、全屋巡逻、远程画面查看"); ingen eksplicit SLAM/autonom-navigationsklasse oplyst.', null, null, null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'monteringsinterface', 'tekst', null, null, null, null, '20kg "工业级有效载荷平台，为机械臂、雷达、计算盒与任务模组预留更高的物理冗余" (industriel nyttelastplatform med fysisk reserve til robotarm, radar, computerboks og opgavemoduler). Standardiseret monteringsflade/-maal ikke oplyst.', null, null, null, null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'stroem_ud', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'dataporte', 'bare_tilstand', 'ikke_oplyst', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), 'pris', 'tal', null, 15999, null, null, null, null, null, 'CNY', null, null, null, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, '"售价（含税）¥15,999" (inkl. skat/moms). Samme side: "部分功能及性能数据仍在持续开发和优化中... 涉及最终价格...以正式订单确认信息为准" - prisen er en aktuel listepris, ikke garanteret endelig.', null, null, null, null, null, null),
