insert into anvendelse (robot_id, er_bar_streng, er_ikke_oplyst, vaerdi, citat, kilde, hentet, kildetype, arvet_fra_robot_id, note) values
  ((select id from robotter where slug = 'anybotics-anymal'), false, false, '["inspektion","industri"]'::jsonb, '["ANYmal - Autonomous Robotic Inspection Solution - ANYbotic","Purpose-built for intricate industrial plants."]'::jsonb, 'https://www.anybotics.com/robotics/anymal/', '2026-08-19'::date, null, null, 'Foerste citat er sidens egen titel.'),
  ((select id from robotter where slug = 'anybotics-anymal-x'), false, false, '["inspektion","industri"]'::jsonb, '["ANYmal X - Ex-proof inspection robot - ANYbotics","Complies with CE directives for industrial deployment"]'::jsonb, 'https://www.anybotics.com/robotics/anymal-x/', '2026-08-19'::date, null, null, 'Foerste citat er sidens egen titel. Siden praeciserer branchen: "Automate inspections in Oil & Gas and Chemical operations to increase safety,".'),
  ((select id from robotter where slug = 'astrall-dynamics-hypertron-t01'), false, false, '["industri","forsvar_beredskab","sikkerhed_overvaagning"]'::jsonb, '"电力能源、消防应急、园区厂区、建筑管廊、矿井轨道、石油化工、警务安防、水利水务 (menupunkterne under \"行业应用\" paa forsiden og produktsiden)"'::jsonb, 'https://www.astralldynamics.com/project-Hypertron-T01.html', '2026-08-24'::date, null, null, 'Mapning af de otte menupunkter til de syv tilladte vaerdier: 电力能源 (elkraft/energi), 建筑管廊 (bygge/forsyningstunneler), 矿井轨道 (mine/skinner) og 水利水务 (vandforsyning) er alle industrielle infrastruktursektorer -> industri. 消防应急 (brand/beredskab) -> forsvar_beredskab. 园区厂区 (industripark-/fabriksomraade-patrulje - siden skriver selv "360°全方位监测", helomraade-overvaagning) og 警务安防 (politi/sikkerhed) -> sikkerhed_overvaagning. 石油化工 (petrokemi) -> industri. Ingen af de otte er oversat til logistik, inspektion, forskning_udvikling eller forbruger_uddannelse.'),
  ((select id from robotter where slug = 'bhairav-robotics-shvana'), false, false, '["forsvar_beredskab","industri","inspektion"]'::jsonb, '["Defence & Homeland Security: Shvana can be effectively used by various divisions of armed forces for: Strategic area monitoring | Border patrol & surveillance | Tactical situations | Explosive detection | Search and rescue operations. Shvana also offers the possibility of carrying EW (electronic warfare) payloads, munitions etc., with advanced target tracking software and image recognition capabilities.","Industrial Environments: ... Confined area entry | Hazardous/Corrosive environment inspection | Routine field checks – detecting leaks, abnormal sound, etc | Detecting hotspots | Handling radioactive waste | Fire fighting"]'::jsonb, 'https://bhairavrobotics.com/shvana-robot/', '2026-08-24'::date, null, null, '"Defence & Homeland Security" med bevaebnings-/ammunitionsomtale (''munitions'', ''EW payloads'') -> forsvar_beredskab (IKKE sikkerhed_overvaagning - L22 indfoerte netop den kategori for at skille civil patrulje/overvaagning fra militaerplatforme, og Shvana er eksplicit "Bharat''s first ARMED quadruped" for vaebnede styrker). "Industrial Environments" med "Hazardous/Corrosive environment inspection", "Routine field checks - detecting leaks" m.fl. -> industri + inspektion.'),
  ((select id from robotter where slug = 'boston-dynamics-spot'), false, false, '["industri","inspektion"]'::jsonb, '"Our agile mobile robot for dynamic sensing and industrial inspection"'::jsonb, 'https://bostondynamics.com/products/spot/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, teksten under punktet "Spot". Sidens loesningsmenu deler i "Inspection" og "Safety & Response".'),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), false, false, '["industri","forsvar_beredskab"]'::jsonb, '"适用于工业、电力、救援等场景"'::jsonb, 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, null, '"工业" (industri) og "电力" (elkraft) er begge omsat til industri, da saetningen her ikke selv bruger et inspektionsord (modsat nyhedsartiklen, se noter). "救援" (redning) er omsat til forsvar_beredskab.'),
  ((select id from robotter where slug = 'deep-robotics-lite3'), false, false, '["forbruger_uddannelse","forskning_udvikling"]'::jsonb, '"教育科研"'::jsonb, 'https://www.deeprobotics.cn/robot/index/product1.html', '2026-08-19'::date, null, null, 'Producentens kinesiske produktpanel saetter en etikette paa hver model. Lite3 faar "教育科研" (uddannelse og videnskabelig forskning), X20 og X30 faar "行业应用" (brancheanvendelse). Den ENGELSKE Lite3-side siger intet om anvendelse overhovedet - kategorien findes kun paa den kinesiske.'),
  ((select id from robotter where slug = 'deep-robotics-lynx-m20'), false, false, '["industri","inspektion","forsvar_beredskab","logistik","forskning_udvikling"]'::jsonb, '"The LYNX M20 series represents the world’s first wheeled-legged robot built specifically for challenging terrains and hazardous environments during industrial operation. Featuring lightweight design with extreme-environment endurance, it conquers rugged mountain trails, muddy wetlands and debris-strewn ruins—pioneering embodied intelligence in power inspection, emergency response, logistics, and scientific exploration."'::jsonb, 'https://deeprobotics.cn/en/index/lynx.html', '2026-08-19'::date, null, null, 'FEM kategorier i én saetning. Det er producentens egen opremsning, og de fem staar uden indbyrdes rangering (L27): robotten hoerer til i alle fem, ikke i den foerste.'),
  ((select id from robotter where slug = 'deep-robotics-lynx-m20-pro'), false, false, '["industri","inspektion","forsvar_beredskab","logistik","forskning_udvikling"]'::jsonb, '"The LYNX M20 series represents the world’s first wheeled-legged robot built specifically for challenging terrains and hazardous environments during industrial operation. Featuring lightweight design with extreme-environment endurance, it conquers rugged mountain trails, muddy wetlands and debris-strewn ruins—pioneering embodied intelligence in power inspection, emergency response, logistics, and scientific exploration."'::jsonb, 'https://deeprobotics.cn/en/index/lynx.html', '2026-08-19'::date, null, null, 'Producenten skriver om "The LYNX M20 series", og Pro er en variant i den serie.'),
  ((select id from robotter where slug = 'deep-robotics-lynx-m20s'), false, false, '["industri","inspektion","forsvar_beredskab","logistik","forskning_udvikling"]'::jsonb, '"The LYNX M20 series represents the world’s first wheeled-legged robot built specifically for challenging terrains and hazardous environments during industrial operation. Featuring lightweight design with extreme-environment endurance, it conquers rugged mountain trails, muddy wetlands and debris-strewn ruins—pioneering embodied intelligence in power inspection, emergency response, logistics, and scientific exploration."'::jsonb, 'https://deeprobotics.cn/en/index/lynx.html', '2026-08-19'::date, null, null, 'Producenten skriver om "The LYNX M20 series", og M20S er en variant i den serie.'),
  ((select id from robotter where slug = 'deep-robotics-lynx-s10'), false, false, '["inspektion","sikkerhed_overvaagning","forsvar_beredskab","forbruger_uddannelse","forskning_udvikling"]'::jsonb, '"It provides a highly efficient and reliable professional platform for intelligent lightweight tasks in industries such as power inspection, security patrol, emergency firefighting, and education & scientific research."'::jsonb, 'https://deeprobotics.cn/en/index/lynxs10.html', '2026-08-19'::date, null, null, 'L22: "security patrol" er omsat til sikkerhed_overvaagning. "emergency firefighting" er forsvar_beredskab. De fem kategorier er producentens egen opremsning i én saetning og staar uden indbyrdes rangering (L27).'),
  ((select id from robotter where slug = 'deep-robotics-mini'), false, true, null, null, 'https://deeprobotics.cn/en/index/product2.html', '2026-08-19'::date, null, null, 'GENNEMLAEST, INTET FUNDET. Mini staar heller ikke i producentens kinesiske produktpanel, hvor Lite3, X20 og X30 hver faar en anvendelsesetikette. Sidens egen tekst handler om teknologi ("deep learning", "visual perception"), ikke om hvem robotten er til.'),
  ((select id from robotter where slug = 'deep-robotics-x20'), false, false, '["industri","inspektion"]'::jsonb, '"The X20 quadruped robot solution is for industrial patrol inspection under extreme working conditions."'::jsonb, 'https://deeprobotics.cn/en/index/product.html', '2026-08-19'::date, null, null, 'Sidens titel siger det samme: "X20: The Ultimate Quadruped Bot series for Industrial Use". Producentens kinesiske produktpanel etiketterer X20 "行业应用".'),
  ((select id from robotter where slug = 'deep-robotics-x30'), false, false, '["industri","inspektion","sikkerhed_overvaagning"]'::jsonb, '"X30 quadruped robot, a flagship product designed to meet core industry needs in multiple fields including inspection, investigation, security, surveying and mapping."'::jsonb, 'https://deeprobotics.cn/en/index/product3.html', '2026-08-19'::date, null, null, 'L22: "security" er omsat til sikkerhed_overvaagning. "surveying and mapping" har det tilladte saet stadig ingen kategori for og er ikke omsat.'),
  ((select id from robotter where slug = 'deep-robotics-x30-pro'), false, false, '["industri","inspektion","sikkerhed_overvaagning"]'::jsonb, '"X30 quadruped robot, a flagship product designed to meet core industry needs in multiple fields including inspection, investigation, security, surveying and mapping."'::jsonb, 'https://deeprobotics.cn/en/index/product3.html', '2026-08-19'::date, null, (select id from robotter where slug = 'deep-robotics-x30'), 'ARVET (L23). X30 Pro har ingen egen produktside; den staar som en variant paa X30-siden, og saetningen er skrevet om "X30 quadruped robot" - ikke om serien. At Pro''en er daekket, er derfor vores kobling, ikke producentens ord. L22: "security" er omsat til sikkerhed_overvaagning.'),
  ((select id from robotter where slug = 'genisom-gangben-l1'), false, false, '["inspektion","forsvar_beredskab","sikkerhed_overvaagning","forskning_udvikling"]'::jsonb, '"钢镚L1是智身科技自主研发的首款行业级小型四足机器人...广泛应用于电力巡检、应急救援、安防巡逻、科研教育等场景。"'::jsonb, 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, 'Egen oversaettelse: "Gangben L1 er GENISOM AI''s selvudviklede foerste industriklasse smaa firbenede robot... anvendes bredt inden for elkraftinspektion, redningsberedskab, sikkerhedspatrulje, forskning og uddannelse." 电力巡检 -> inspektion; 应急救援 -> forsvar_beredskab; 安防巡逻 -> sikkerhed_overvaagning; 科研教育 -> forskning_udvikling (uddannelsesdelen af 科研教育 har intet praecist svar i vaerdisaettet ud over forbruger_uddannelse, som ikke er brugt her, da konteksten er faglig forskning, ikke forbrugerprodukt).'),
  ((select id from robotter where slug = 'genisom-gangben-l1-w'), false, false, '["forsvar_beredskab","forskning_udvikling","sikkerhed_overvaagning"]'::jsonb, '["侦查搜救","应急消防","科研教育","安防巡逻"]'::jsonb, 'https://www.genisomai.com/product-robot/L1-W', '2026-08-24'::date, null, null, 'Fra sektionen "下一个应用场景，它已提前就位" (naeste anvendelsesscenarie, allerede klar) paa L1-W''s egen produktside - fire selvstaendige citater, ikke arvet fra L1. Egen oversaettelse: 侦查搜救 (rekognoscering/eftersoegning-redning) -> forsvar_beredskab; 应急消防 (akut brandbekaempelse) -> forsvar_beredskab (samme kategori som 侦查搜救, to citater); 科研教育 -> forskning_udvikling; 安防巡逻 -> sikkerhed_overvaagning.'),
  ((select id from robotter where slug = 'genisom-gangben-l2'), false, false, '["sikkerhed_overvaagning","forskning_udvikling","logistik"]'::jsonb, '["安防巡逻","科研教育","短途配送"]'::jsonb, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, 'Fra siden "下一个应用场景，它已提前就位" (naeste anvendelsesscenarie, allerede klar). 安防巡逻 -> sikkerhed_overvaagning; 科研教育 -> forskning_udvikling; 短途配送 (kort-distance levering) -> logistik.'),
  ((select id from robotter where slug = 'genisom-gangben-l2-w'), false, false, '["sikkerhed_overvaagning","forsvar_beredskab","forskning_udvikling","logistik"]'::jsonb, '["安防巡逻","应急消防","科研教育","短途配送"]'::jsonb, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, 'Fra sektionen "下一个应用场景，它已提前就位" paa L2''s produktside. Teksten staar EN gang paa siden, FOER variant-fanebladet (L2/L2-W/L2-W Ultra) i den strukturerede specifikationstabel - den daekker hele Gangben L2-familien som helhed, ikke kun basisudgaven. Citeret selvstaendigt fra samme URL, IKKE via arvet_fra: det er den samme primaerkilde for alle tre varianter, ikke en slutning om en anden robot (arvet_fra ville forudsaette, at L2-W''s EGEN side var tavs og laante L2''s citat - det er den ikke, teksten staar paa netop den side, L2-W ogsaa bor paa). Egen oversaettelse: 安防巡逻 -> sikkerhed_overvaagning; 应急消防 (akut brandbekaempelse) -> forsvar_beredskab; 科研教育 -> forskning_udvikling; 短途配送 (kort-distance levering) -> logistik. BEMAERK: dette citat har FIRE led (inkl. 应急消防), mens genisom-gangben-l2.yaml''s eksisterende citat kun har tre (mangler 应急消防) - en uafhaengig genlaesning af samme raa HTML for denne post. Den eksisterende L2-post er IKKE rettet, jf. opgavens instruks om ikke at roere de to eksisterende poster.'),
  ((select id from robotter where slug = 'genisom-gangben-l2-w-ultra'), false, false, '["sikkerhed_overvaagning","forsvar_beredskab","forskning_udvikling","logistik"]'::jsonb, '["安防巡逻","应急消防","科研教育","短途配送"]'::jsonb, 'https://www.genisomai.com/product-robot/L2', '2026-08-24'::date, null, null, 'Samme sektion og samme begrundelse som genisom-gangben-l2-w.yaml: teksten "下一个应用场景，它已提前就位" staar EN gang paa L2-siden for hele Gangben L2-familien, foer variant-fanebladene. Citeret selvstaendigt fra samme URL, ikke via arvet_fra. Egen oversaettelse: 安防巡逻 -> sikkerhed_overvaagning; 应急消防 -> forsvar_beredskab; 科研教育 -> forskning_udvikling; 短途配送 -> logistik.'),
  ((select id from robotter where slug = 'genisom-qiuqiu-sp1'), false, false, '["industri","inspektion"]'::jsonb, '["智身铅球 SP1 是面向石油化工、能源场站等高危工业环境的防爆四足巡检机器人","自主巡检 数据回传 人员零涉险"]'::jsonb, 'https://www.genisomai.com/product-robot/sp1', '2026-08-24'::date, null, null, 'Egen oversaettelse: "GENISOM Qiuqiu SP1 er en eksplosionssikker firbenet inspektionsrobot til hoejrisiko-industrimiljoeer som petrokemi og energistationer" (meta-description) og "Autonom inspektion, dataoverfoersel, nul personalerisiko" (marketingoverskrift, "自主巡检" = autonom inspektion). Sidens EGEN "naeste anvendelsesscenarie"-sektion ("下一个应用场景，它已提前就位") lister FIRE ANLAEGSTYPER, ikke aktivitetskategorier: 炼化装置区 (raffinaderianlaeg), 化工储罐区 (kemisk lagertankomraade), 燃气/LNG场站 (gas/LNG-station), 油气管线 (olie-/gasledning) - ingen af dem er en verbatim aktivitetskategori i skemaets tilladte saet, saa de er IKKE brugt som citat/vaerdi her. I stedet er industri/inspektion udledt af meta-beskrivelsens "高危工业环境" (hoejrisiko-industrimiljoe) og "防爆...巡检机器人" (eksplosionssikker...inspektionsrobot) samt brodtekstens eksplicitte "自主巡检" (autonom inspektion).'),
  ((select id from robotter where slug = 'genisom-tongchui-m1'), false, false, '["forsvar_beredskab","inspektion","sikkerhed_overvaagning","logistik"]'::jsonb, '["森林消防","石化消防","电力巡检","园区巡逻","物流运输"]'::jsonb, 'https://www.genisomai.com/product-robot/M1', '2026-08-24'::date, null, null, 'Fra sektionen "下一个应用场景，它已提前就位" (naeste anvendelsesscenarie, allerede klar) paa M1''s egen produktside. Egen oversaettelse: 森林消防 (skovbrandbekaempelse) -> forsvar_beredskab; 石化消防 (petrokemisk brandbekaempelse) -> forsvar_beredskab (samme kategori, to citater); 电力巡检 (elkraftinspektion) -> inspektion; 园区巡逻 (omraadepatrulje) -> sikkerhed_overvaagning; 物流运输 (logistiktransport) -> logistik.'),
  ((select id from robotter where slug = 'ghost-robotics-spirit-40'), false, true, null, null, 'https://www.ghostrobotics.io/spirit-40', '2026-08-19'::date, null, null, 'PRODUCENTEN HAR INGEN SIDE OM MODELLEN. Den gemte fil har <title>Not Found</title> og teksten "Page Not Found". Uden en side er der intet at citere, og Ghost Robotics generelle forsvarspositionering hoerer til Vision 60, ikke til en model producenten ikke laengere omtaler.'),
  ((select id from robotter where slug = 'ghost-robotics-vision-60'), false, false, '"forsvar_beredskab"'::jsonb, '["Designed to meet your real-world commercial and defense needs, Q-UGV is the most adaptable unmanned ground vehicle in the world.","Redefining government, homeland, and military operations."]'::jsonb, 'https://www.ghostrobotics.io/vision-60', '2026-08-19'::date, null, null, 'Producentens hovednavigation har to punkter: "Defense" og "Commercial". "Commercial" er ikke en anvendelse i det tilladte saet, og forsiden praeciserer den som "From the battlefield to the oil field".'),
  ((select id from robotter where slug = 'keybotic-keyper'), false, false, '["industri","inspektion","sikkerhed_overvaagning","forskning_udvikling"]'::jsonb, '["Autonomous Robot Dogs for Industrial Inspections","Meet Keyper, your autonomous industrial inspector","INDUSTRIES: Chemicals, Oil & Gas, Energy & Utilities, Mining & Minerals, Surveillance, Research"]'::jsonb, 'https://keybotic.com/technology/', '2026-08-24'::date, null, null, '"Autonomous Robot Dogs for Industrial Inspections" og "autonomous industrial inspector" -> industri + inspektion (hele produktets formaal er industriel inspektion). "Surveillance" (eget punkt paa producentens industriliste, samme ordlyd paa forside og /technology/) -> sikkerhed_overvaagning. "Research" (samme liste) -> forskning_udvikling. De fire foerste brancher (Chemicals, Oil & Gas, Energy & Utilities, Mining & Minerals) daekkes allerede af industri/inspektion og har ikke egne kategorier i skemaet.'),
  ((select id from robotter where slug = 'mab-honey-badger-4'), false, false, '["inspektion","forskning_udvikling"]'::jsonb, '["Industrial inspection","Academia & Research"]'::jsonb, 'https://www.mabrobotics.pl/honey-badger', '2026-08-19'::date, null, null, 'FIRMANIVEAU, IKKE MODELNIVEAU. Citaterne er to punkter i producentens "Industries"-menu, som staar paa hele sitet: Industrial inspection, Mining, Public safety, Utilities, Civil engineering, Academia & Research. Honey Badger er producentens eneste robot, men producenten har ikke selv sat etiketten paa modellen. Mining, Public safety, Utilities og Civil engineering har det tilladte saet ingen kategorier for.'),
  ((select id from robotter where slug = 'mab-honey-badger-5'), false, false, '["inspektion","forskning_udvikling"]'::jsonb, '["Industrial inspection","Academia & Research"]'::jsonb, 'https://www.mabrobotics.pl/honey-badger-5', '2026-08-19'::date, null, null, 'FIRMANIVEAU, IKKE MODELNIVEAU - se noten paa Honey Badger 4.0. Modelsidens egen overskrift "Designed with Precision for Industrial-grade Standards" er en byggekvalitet, ikke en anvendelse, og taeller ikke med.'),
  ((select id from robotter where slug = 'magiclab-magicdog-edu'), false, false, '["forskning_udvikling","forbruger_uddannelse"]'::jsonb, '"MagicDog is an intelligent quadruped robot developed for research, education, interactive entertainment and companion-style applications."'::jsonb, 'https://www.magiclabglobal.com/products/magicdog/', '2026-08-19'::date, null, null, 'Samme afsnit slutter: "PRO and EDU configurations are available".'),
  ((select id from robotter where slug = 'magiclab-magicdog-pro'), false, false, '["forskning_udvikling","forbruger_uddannelse"]'::jsonb, '"MagicDog is an intelligent quadruped robot developed for research, education, interactive entertainment and companion-style applications."'::jsonb, 'https://www.magiclabglobal.com/products/magicdog/', '2026-08-19'::date, null, null, 'Samme afsnit slutter: "PRO and EDU configurations are available", saa saetningen daekker begge varianter. magiclabglobal.com er producentens nye globale site (FUND-kina-3, afsnit om de to domaener).'),
  ((select id from robotter where slug = 'magiclab-magicdog-w'), false, false, '["forskning_udvikling","inspektion"]'::jsonb, '"MagicDog-W is suitable for research, demonstrations, patrol, surveying and expandable mobile applications."'::jsonb, 'https://www.magiclabglobal.com/products/magicdog-w/', '2026-08-19'::date, null, null, 'Producentens kinesiske og engelske produktsider paa magiclab.top kalder den kun "MagicLab Quadruped Wheeled Robot" - en form, ikke en anvendelse.'),
  ((select id from robotter where slug = 'magiclab-magicdog-y1'), false, false, '["industri","inspektion","forsvar_beredskab"]'::jsonb, '["MagicDog Y1 is an industrial quadruped robot engineered for inspection, emergency response, rescue support and demanding outdoor operations.","MagicLab Industrial Quadruped Robot"]'::jsonb, 'https://www.magiclabglobal.com/products/magicdog-y1/', '2026-08-19'::date, null, null, 'De to producentdomaener siger det samme: magiclab.top skriver "MagicLab Industrial Quadruped Robot" (CN: "魔法原子工业四足机器人").'),
  ((select id from robotter where slug = 'microrobotech-movenew-p1'), false, false, '["industri","inspektion","forsvar_beredskab","sikkerhed_overvaagning"]'::jsonb, '"All-terrain quadruped robot for industrial inspection, fire response, and public safety missions."'::jsonb, 'https://www.micbotics.com/list_12/98.html', '2026-08-24'::date, null, null, '"industrial inspection" -> industri + inspektion; "fire response" -> forsvar_beredskab; "public safety missions" -> sikkerhed_overvaagning.'),
  ((select id from robotter where slug = 'pudu-d5'), false, false, '["industri","inspektion","sikkerhed_overvaagning","forskning_udvikling"]'::jsonb, '"Designed for real-world deployment in industrial, inspection, security, research, and advanced robotics applications."'::jsonb, 'https://www.pudurobotics.com/en/products/d5', '2026-08-24'::date, null, null, 'Samme saetning staar ordret paa baade den officielle produktside og webbutikken (store.pudurobotics.com/products/pudu-d5).'),
  ((select id from robotter where slug = 'pudu-d5-w'), false, false, '["industri","inspektion","sikkerhed_overvaagning","forskning_udvikling"]'::jsonb, '"Designed for real-world deployment in industrial, inspection, security, research, and advanced robotics applications."'::jsonb, 'https://www.pudurobotics.com/en/products/d5', '2026-08-24'::date, null, null, 'Samme produktside og samme saetning som pudu-d5.yaml - D5 og D5-W er to variantvalg paa EN Shopify-produktside (handle "pudu-d5"), ikke to adskilte sider. Se noter herunder.'),
  ((select id from robotter where slug = 'rainbow-robotics-rbq-10'), false, false, '["forskning_udvikling","inspektion","sikkerhed_overvaagning"]'::jsonb, '["Research Platform","Based on dynamics-based gait control and AI gait technology, it provides walking stability and mobility outdoors, while supporting sensor and system expansion for field applications such as patrol, inspection, and observation.","PTZ cameras, thermal imaging, lighting, speakers, and other modules can be combined according to mission purpose and environment, supporting scenarios such as surveillance, inspection, and observation."]'::jsonb, 'https://rainbow-robotics.com/en/products/rbq-10/', '2026-08-19'::date, null, null, '"Research Platform" er en etikette paa selve produktet, ved siden af "Outdoor Walking" og "AI Gait". L22: "patrol" og "surveillance" er omsat til sikkerhed_overvaagning; tredje citat er produktsidens egen modulbeskrivelse. Producentens brancheliste for hele firmaet naevner ogsaa Defense & Security og Logistics, men den er ikke skrevet om RBQ-10 og er ikke brugt.'),
  ((select id from robotter where slug = 'raion-robotics-raibo2'), false, false, '["inspektion","forskning_udvikling","sikkerhed_overvaagning"]'::jsonb, '["Modular payload space supports perception, communication, and mission equipment for patrol, inspection, and research workflows.","RAIBO2 integrates high-output actuators, reinforced mechanical structure, and learning-based control into a field-ready quadruped platform."]'::jsonb, 'https://raionrobotics.com/en/product/Raibo2', '2026-08-21'::date, null, null, 'L22: "patrol" er omsat til sikkerhed_overvaagning. SVAGESTE af de seks: producenten skriver hverken "security" eller "surveillance" om RAIBO2 - kun "patrol", og kun én gang. Universitetslaboratoriet bag robotten, KAIST RaiLab, skriver noget andet: a practical and cost-effective solution for industrial applications - men RaiLab er ikke producenten, og deres ord er ikke foert her.'),
  ((select id from robotter where slug = 'rivr-one'), false, false, '"logistik"'::jsonb, '"Our delivery robot is designed to seamlessly navigate the last mile and the critical last 100 yards right to the doorstep, ensuring secure deliveries while integrating into your existing infrastructure."'::jsonb, 'https://www.rivr.ai/product', '2026-08-19'::date, null, null, 'Producentens navigation deler i Parcel Delivery, Grocery Delivery og "Instant food and convenience store delivery" - tre former for det samme.'),
  ((select id from robotter where slug = 'unitree-a1'), false, false, '["forbruger_uddannelse","forskning_udvikling"]'::jsonb, '["Robot - Consumer/Education","机器狗 - 消费级 / 科研"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen A1 staar i. Den engelske og den kinesiske navigation navngiver gruppen forskelligt: EN "Consumer/Education", CN "forbrugerniveau / videnskabelig forskning". Begge er producentens.'),
  ((select id from robotter where slug = 'unitree-a2'), false, false, '"industri"'::jsonb, '["Robot - Industry","机器狗 - 行业级"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen A2 staar i.'),
  ((select id from robotter where slug = 'unitree-a2-w'), false, false, '["inspektion","logistik","forsvar_beredskab"]'::jsonb, '"Suited for industrial inspection, park logistics, and emergency rescue and more."'::jsonb, 'https://www.unitree.com/A2-W', '2026-08-19'::date, null, null, 'A2-W staar ikke i producentens produktnavigation, hvor A2 staar under "Robot - Industry". Kategorien her er derfor produktsidens egen saetning, ikke navigationens gruppe. Samme side kalder robotten "Industrial-grade mobile platform" - det er en byggekvalitet, ikke en anvendelse, og taeller ikke med.'),
  ((select id from robotter where slug = 'unitree-aliengo'), false, false, '"industri"'::jsonb, '["Robot - Industry","机器狗 - 行业级"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen AlienGo staar i.'),
  ((select id from robotter where slug = 'unitree-as2'), false, false, '["forbruger_uddannelse","forskning_udvikling"]'::jsonb, '["Robot - Consumer/Education","机器狗 - 消费级 / 科研"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen As2 staar i. MODSIGELSE: As2 staar under Consumer/Education i navigationen, men As2-produktsidens egen titel er "Unitree As2 Compact Size Industrial Capability". Producenten siger begge dele.'),
  ((select id from robotter where slug = 'unitree-as2-w'), false, false, '["inspektion","sikkerhed_overvaagning"]'::jsonb, '"ideal for security, inspection, and advanced applications."'::jsonb, 'https://www.unitree.com/As2-W', '2026-08-19'::date, null, null, 'L22: producentens eget ord "security" i samme saetning er nu omsat til sikkerhed_overvaagning. Citatet er As2-W''s egen produktside; As2-W staar ikke i produktnavigationen, saa der er intet arvet her.'),
  ((select id from robotter where slug = 'unitree-b1'), false, false, '"industri"'::jsonb, '["Robot - Industry","机器狗 - 行业级"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen B1 staar i.'),
  ((select id from robotter where slug = 'unitree-b2'), false, false, '"industri"'::jsonb, '["Robot - Industry","机器狗 - 行业级"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen B2 staar i.'),
  ((select id from robotter where slug = 'unitree-b2-w'), false, false, '"industri"'::jsonb, '["Robot - Industry","机器狗 - 行业级"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, (select id from robotter where slug = 'unitree-b2'), 'ARVET (L23). B2-W staar ikke i produktnavigationen, og dens egen side https://www.unitree.com/b2-w er gennemlaest 2026-08-19 uden at naevne nogen anvendelse - kun "Go Further with Higher Efficiency" og "Brand New Intelligent Species". Citatet er B2''s, og koblingen B2-W = B2 i hjulet udgave er vores slutning, ikke producentens.'),
  ((select id from robotter where slug = 'unitree-go1'), false, false, '["forbruger_uddannelse","forskning_udvikling"]'::jsonb, '["Robot - Consumer/Education","机器狗 - 消费级 / 科研"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen Go1 staar i.'),
  ((select id from robotter where slug = 'unitree-go2'), false, false, '["forbruger_uddannelse","forskning_udvikling"]'::jsonb, '["Robot - Consumer/Education","机器狗 - 消费级 / 科研"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, null, 'Producentens egen produktnavigation, gruppen Go2 staar i.'),
  ((select id from robotter where slug = 'unitree-go2-w'), false, false, '["forbruger_uddannelse","forskning_udvikling"]'::jsonb, '["Robot - Consumer/Education","机器狗 - 消费级 / 科研"]'::jsonb, 'https://www.unitree.com/', '2026-08-19'::date, null, (select id from robotter where slug = 'unitree-go2'), 'ARVET (L23). Go2-W staar ikke i produktnavigationen, og dens egen side https://www.unitree.com/go2-w er gennemlaest 2026-08-19 og siger kun "Driving All Terrain" og "Go2 New Model Transformative Newborn". Citatet er Go2''s, og koblingen Go2-W = Go2 i hjulet udgave er vores slutning, ikke producentens.'),
  ((select id from robotter where slug = 'unitree-laikago'), false, true, null, null, 'https://www.unitree.com/laikago', '2026-08-21'::date, null, null, 'PRODUCENTEN HAR INGEN SIDE OM MODELLEN. Uden en produktside er der ingen positionering at citere, og Unitrees to navigationsgrupper (Robot - Consumer/Education og Robot - Industry) naevner ikke Laikago. Samme situation som Ghost Robotics Spirit 40.'),
  ((select id from robotter where slug = 'weilan-alphadog-c500'), false, false, '"forbruger_uddannelse"'::jsonb, '"Children’s education, family companionship, elderly care, express delivery, STEAM education"'::jsonb, 'https://www.weilan.com/en/en/alphadogc.html', '2026-08-19'::date, null, null, 'Listen staar under overskriften "Innovative Applications in Discovery" - producentens egne ord for at det er noget, der undersoeges. Derfor er "express delivery" IKKE foert som logistik: en anvendelse under udforskning er ikke en anvendelse, robotten saelges til.'),
  ((select id from robotter where slug = 'weilan-alphadog-c501'), false, false, '"forbruger_uddannelse"'::jsonb, '"Children’s education, family companionship, elderly care, express delivery, STEAM education"'::jsonb, 'https://www.weilan.com/en/en/alphadogc.html', '2026-08-19'::date, null, null, 'C500 og C501 deler produktside. Se noten paa C500 om "Innovative Applications in Discovery".'),
  ((select id from robotter where slug = 'weilan-alphadog-e300'), false, true, null, null, 'https://www.weilan.com/en/en/alphadoge.html', '2026-08-19'::date, null, null, 'DER STAAR EN POSITIONERING I FILEN, OG DEN ER TAGET NED. Saetningen "it can be assigned to safeguard people and properties, patrol parks and communities, guide a blind person, deliver packages to your front door, inspect factories or dangerous places, do rescue missions" ligger paa byte 23.014-23.500 - inde i HTML-kommentaren, en browser aldrig viser. Maalt: alle fire positioneringstekster paa E-siden ligger i kommentaren. Samme afgoerelse som for tallene: vi udgiver ikke noget, producenten har trukket tilbage.'),
  ((select id from robotter where slug = 'weilan-alphadog-e400l'), false, true, null, null, 'https://www.weilan.com/en/en/alphadoge.html', '2026-08-19'::date, null, null, 'Se noten paa E300: E-seriens positionering ligger inde i en HTML-kommentar og bruges ikke.'),
  ((select id from robotter where slug = 'weilan-babyalpha'), false, false, '"forbruger_uddannelse"'::jsonb, '"AI-powered Family Companion"'::jsonb, 'https://www.weilan.com/en/en/babyAlpha.html', '2026-08-19'::date, null, null, 'Samme side, synlig tekst: "a source of family entertainment that doubles as a home security guard". Producenten placerer den selv i hjemmet.'),
  ((select id from robotter where slug = 'xiaomi-cyberdog-1'), false, true, null, null, 'https://www.mi.com/cyberdog/specs', '2026-08-21'::date, null, null, 'GENNEMLAEST, INTET FUNDET - ogsaa i JS-bundlen, hvor specifikationerne ligger. Producentens eneste etikette er produkttypen 仿生四足机器人 (biomimetisk firbenet robot) og modelnummeret 21051191C. Det er hvad den ER, ikke hvem den er til. Samme resultat som paa CyberDog 2.'),
  ((select id from robotter where slug = 'xiaomi-cyberdog-2'), false, true, null, null, 'https://www.mi.com/cyberdog2/specs', '2026-08-19'::date, null, null, 'GENNEMLAEST, INTET FUNDET - ogsaa i JS-bundlen, hvor specifikationerne ligger. Producentens eneste etikette er produkttypen "仿生四足机器人" (biomimetisk firbenet robot). Det er hvad den ER, ikke hvem den er til.'),
  ((select id from robotter where slug = 'yobotics-e-dog'), false, false, '["forskning_udvikling","forbruger_uddannelse"]'::jsonb, '"It is a flagship product in the field of commercial, scientific research, and educational quadruped robots."'::jsonb, 'https://www.yobotics.cn/en/product/quadruped_robot_series/', '2026-08-19'::date, null, null, 'Serieindledning, ikke en modelspecifik saetning. Se noten paa Y10.'),
  ((select id from robotter where slug = 'yobotics-y10'), false, false, '["forskning_udvikling","forbruger_uddannelse"]'::jsonb, '"It is a flagship product in the field of commercial, scientific research, and educational quadruped robots."'::jsonb, 'https://www.yobotics.cn/en/product/quadruped_robot_series/', '2026-08-19'::date, null, null, 'Saetningen staar som indledning paa katalogsiden for hele serien (Y20, Y10, e-Dog) og er ikke skrevet om den enkelte model. Ordet "commercial" har det tilladte saet ingen kategori for.'),
  ((select id from robotter where slug = 'yobotics-y20'), false, false, '["forskning_udvikling","forbruger_uddannelse"]'::jsonb, '"It is a flagship product in the field of commercial, scientific research, and educational quadruped robots."'::jsonb, 'https://www.yobotics.cn/en/product/quadruped_robot_series/', '2026-08-19'::date, null, null, 'Serieindledning, ikke en modelspecifik saetning. Se noten paa Y10.'),
  ((select id from robotter where slug = 'yufan-lingmao-cyvet'), false, false, '["industri","sikkerhed_overvaagning","forbruger_uddannelse"]'::jsonb, '"灵猫是一个开放的具身智能载具和技术平台，具备多场景适应能力，不但可以用在工业场景解决多领域问题，更是可玩性极高的创客、科研爱好者、极客、玩家的实践载体。作为普通用户，也具备完整陪伴和安全防护功能，支持家用场景智能化交互功能，包括：语音对话、跟随行走、全屋巡逻、远程画面查看，适合科技爱好者、家庭安防、亲子科教等。"'::jsonb, 'https://www.uniubi.com/shop/buy?product=air', '2026-08-24'::date, null, null, '"工业场景" (industrielle scenarier) er omsat til industri. "家庭安防" (hjemmesikkerhed/patrulje) er omsat til sikkerhed_overvaagning. "亲子科教" (foraelder-barn naturvidenskabsundervisning) er omsat til forbruger_uddannelse. "创客、科研爱好者、极客、玩家" (maker/forsker/geek/spiller) er en malgruppebeskrivelse, ikke en branche, og er ikke omsat til nogen kategori.');
insert into billede (robot_id, fil, ophav, kilde, hentet, alt, note, delt_med_robot_id, plade, pos) values
  ((select id from robotter where slug = 'anybotics-anymal'), 'fotos/fabrikant/anybotics-anymal.jpg', 'fabrikant', 'https://www.anybotics.com/robotics/anymal/', '2026-08-19'::date, null, null, null, null, null),
  ((select id from robotter where slug = 'anybotics-anymal-x'), 'fotos/fabrikant/anybotics-anymal-x.jpg', 'fabrikant', 'https://www.anybotics.com/', '2026-08-19'::date, 'ANYbotics ANYmal X fotograferet indendoers i et industrianlaeg', null, null, null, null),
  ((select id from robotter where slug = 'astrall-dynamics-hypertron-t01'), 'fotos/fabrikant/astrall-dynamics-hypertron-t01.png', 'fabrikant', 'https://www.astralldynamics.com/', '2026-08-24'::date, null, null, null, null, null),
  ((select id from robotter where slug = 'boston-dynamics-spot'), 'fotos/fabrikant/boston-dynamics-spot.jpg', 'fabrikant', 'https://bostondynamics.com/products/spot/', '2026-08-19'::date, null, null, null, null, null),
  ((select id from robotter where slug = 'cvte-maxhub-x7'), 'fotos/fabrikant/cvte-maxhub-x7.jpg', 'fabrikant', 'https://www.cvte.com/product/quadrupedrobot', '2026-08-24'::date, null, null, null, null, null),
  ((select id from robotter where slug = 'deep-robotics-lite3'), 'fotos/fabrikant/deep-robotics-lite3.jpg', 'fabrikant', 'https://www.deeprobotics.cn/en/wap/product1.html', '2026-08-24'::date, 'DEEP Robotics Lite3, hvidt studiofoto/render fra siden af', 'IKKE det tidligere afviste delte ''andre produkter''-miniaturebillede (pro1.png/pro4.png, sha256 4eb65513a6... - byte-identisk paa tvaers af Lite3-, X20-, X30- og begge Lynx-sider) og heller ikke ledmodul-fotografierne (j60.png/j100.png). Dette billede er hentet fra Lite3''s EGEN mobil-side (en/wap/product1.html), som IKKE var i det tidligere indsamlede materiale (kun de fem filer fra desktop-siderne index/product1.html var hentet foer nu). Billed-URL''en /public/static/robot/demo/lite_01.jpg er unik for denne side og sha256-efterproevet mod alle 43 eksisterende filer i assets/fotos/fabrikant/ - ingen dubletter. Samme mobil-side indeholder ogsaa filen p8_.jpg, som ved visuel kontrol viser teksten ''X30'' paa robottens krop - den er derfor IKKE brugt, selvom den ligger paa Lite3-siden.', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-lynx-m20'), 'fotos/fabrikant/deep-robotics-lynx-m20.jpg', 'fabrikant', 'https://deeprobotics.cn/en/index/lynx.html', '2026-08-19'::date, 'DEEP Robotics Lynx-seriens hjulben-robot, studiofoto paa hvid baggrund', 'Producentens eget billede for hele Lynx-serien paa lynx.html; siden skelner ikke mellem M20, M20 Pro og M20S i billedvalget.', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-lynx-m20-pro'), 'fotos/fabrikant/deep-robotics-lynx-m20-pro.jpg', 'fabrikant', 'https://deeprobotics.cn/en/index/lynx.html', '2026-08-19'::date, 'DEEP Robotics Lynx-seriens hjulben-robot, studiofoto paa hvid baggrund', 'Producentens eget billede for hele Lynx-serien paa lynx.html; siden skelner ikke mellem M20, M20 Pro og M20S i billedvalget.', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-lynx-m20s'), 'fotos/fabrikant/deep-robotics-lynx-m20s.jpg', 'fabrikant', 'https://deeprobotics.cn/en/index/lynx.html', '2026-08-19'::date, 'DEEP Robotics Lynx-seriens hjulben-robot, studiofoto paa hvid baggrund', 'Producentens eget billede for hele Lynx-serien paa lynx.html; siden skelner ikke mellem M20, M20 Pro og M20S i billedvalget.', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-lynx-s10'), 'fotos/fabrikant/deep-robotics-lynx-s10.jpg', 'fabrikant', 'https://www.deeprobotics.cn/robot/index/lynxs10.html', '2026-08-19'::date, 'DEEP Robotics Lynx S10 kravler over vandfyldte klippetrin', 'Billedport 24. aug 2026: erstattet. Det oprindelige billede var et LiDAR-punktskysbillede fra app''en, ikke et foto af robotten. Nyt billede (s10_3.jpg) er fra samme producentside, efterproevet mod media/robotbilleder/deep-robotics-lynx-s10/MANIFEST.tsv.', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-x20'), 'fotos/fabrikant/deep-robotics-x20.jpg', 'fabrikant', 'https://www.deeprobotics.cn/en/wap/product.html', '2026-08-24'::date, 'DEEP Robotics X20, hvidt studiofoto/render fra siden af', 'IKKE det tidligere afviste delte ''andre produkter''-miniaturebillede (samme sha256 4eb65513a6... som paa Lite3-siden) og heller ikke ledmodul-fotografierne. Billedet er hentet fra X20''s EGEN mobil-side (en/wap/product.html), som IKKE var i det tidligere indsamlede materiale. Billed-URL''en /public/static/robot/demo/p66.jpg er unik og sha256-efterproevet mod alle 43 eksisterende filer i assets/fotos/fabrikant/ - ingen dubletter. Samme sides oevrige demobilleder (p11_-p55.jpg) viser samme robot i felttest med paatrykt ''DEEPRobotics/云深处科技''-logo direkte paa chassiset og en person i sikkerhedshjelm til stoerrelsesreference - ingen af dem baerer teksten ''X30'', modsat filen p8_.jpg paa samme side (afvist, se Lite3-postens note for samme fund).', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-x30'), 'fotos/fabrikant/deep-robotics-x30.jpg', 'fabrikant', 'https://deeprobotics.cn/en/index/product3.html', '2026-08-19'::date, 'DEEP Robotics Jueying X30-serien, studiofoto paa hvid baggrund', 'Samme billede bruges af producenten paa baade X30- og X30 Pro-siden.', null, null, null),
  ((select id from robotter where slug = 'deep-robotics-x30-pro'), 'fotos/fabrikant/deep-robotics-x30-pro.jpg', 'fabrikant', 'https://deeprobotics.cn/en/index/product3.html', '2026-08-19'::date, 'DEEP Robotics Jueying X30-serien, studiofoto paa hvid baggrund', 'Samme billede bruges af producenten paa baade X30- og X30 Pro-siden; Pro har ingen egen produktside (se arvet_fra).', null, null, null),
  ((select id from robotter where slug = 'genisom-gangben-l1'), 'fotos/fabrikant/genisom-gangben-l1.webp', 'fabrikant', 'https://www.genisomai.com/product-robot/L1', '2026-08-24'::date, null, null, null, null, null),
